COMMENT ON FUNCTION "interno"."asistente_de_la_sesion"() IS 'La ficha de Asistente de quien inició sesión, en la Prestadora donde está parado. Nula si en esa Prestadora no es Asistente.';



CREATE OR REPLACE FUNCTION "interno"."asistente_desactivado"("p_asistente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM asistentes a
      JOIN usuarios u ON u.id = a.usuario_id AND u.prestadora_id = a.prestadora_id
     WHERE a.id = p_asistente
       AND u.desactivada_en IS NOT NULL);
$$;


ALTER FUNCTION "interno"."asistente_desactivado"("p_asistente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."asistente_ocupado_entre"("p_asistente" "uuid", "p_guardia_excluida" "uuid", "p_desde" timestamp without time zone, "p_hasta" timestamp without time zone) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM guardias g
     WHERE g.prestadora_id = interno.prestadora_actual()
       AND g.asistente_id = p_asistente
       AND g.id <> p_guardia_excluida
       AND g.estado NOT IN ('cancelada', 'ausente')
       AND (g.fecha + g.hora_inicio) < p_hasta
       AND (interno.dia_en_que_termina_guardia(g.fecha, g.hora_inicio, g.hora_fin, g.dias_hasta_el_fin) + g.hora_fin) > p_desde
  );
$$;


ALTER FUNCTION "interno"."asistente_ocupado_entre"("p_asistente" "uuid", "p_guardia_excluida" "uuid", "p_desde" timestamp without time zone, "p_hasta" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."asistente_trabaja_en_modalidad"("p_asistente_id" "uuid", "p_modalidad" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(p_modalidad = ANY(a.canales), false)
    FROM public.asistentes a
   WHERE a.id = p_asistente_id;
$$;


ALTER FUNCTION "interno"."asistente_trabaja_en_modalidad"("p_asistente_id" "uuid", "p_modalidad" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."asistente_trabaja_en_modalidad"("p_asistente_id" "uuid", "p_modalidad" "text") IS 'Si este Asistente trabaja en esa modalidad. La usan las tres puertas: asignar una guardia, armar una serie e invitar (regla 12).';



CREATE OR REPLACE FUNCTION "interno"."atiende_al_paciente"("p_paciente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH yo AS (
    SELECT auth.uid()                       AS uid,
           interno.prestadora_actual()         AS tenant,
           interno.asistente_de_la_sesion() AS asistente
  ),
  pac AS (
    SELECT p.id, p.cliente_id
      FROM pacientes p, yo
     WHERE p.id = p_paciente
       AND p.prestadora_id = yo.tenant
  )
  SELECT EXISTS (
    SELECT 1
      FROM pac, yo
     WHERE yo.uid IS NOT NULL
       AND (
         -- Quien recibe el Servicio.
         pac.cliente_id = interno.cliente_id_de_usuario(yo.uid)

         -- Quien coordina uno de sus Servicios.
         OR interno.coordina_al_paciente(pac.id)

         -- Quien la Prestadora sumó al equipo de uno de sus Servicios.
         OR EXISTS (
           SELECT 1
             FROM equipo_servicio e
             JOIN servicios s ON s.id = e.servicio_id
                             AND s.prestadora_id = e.prestadora_id
                             AND s.cliente_id = pac.cliente_id
                             AND s.estado = 'vigente'
            WHERE e.prestadora_id = yo.tenant
              AND e.situacion = 'sumada'
              AND (e.usuario_id = yo.uid
                   OR (yo.asistente IS NOT NULL AND e.asistente_id = yo.asistente))
         )

         -- Quien lo presta, guardia por guardia.
         OR EXISTS (
           SELECT 1
             FROM guardias g
             JOIN servicios s ON s.id = g.servicio_id
                             AND s.prestadora_id = g.prestadora_id
                             AND s.estado = 'vigente'
            WHERE g.prestadora_id = yo.tenant
              AND g.estado <> 'cancelada'
              AND yo.asistente IS NOT NULL
              AND g.asistente_id = yo.asistente
              AND (g.paciente_id = pac.id
                   OR EXISTS (SELECT 1 FROM guardia_pacientes gp
                               WHERE gp.guardia_id = g.id AND gp.paciente_id = pac.id))
         )

         -- Quien lo presta por una serie que sigue en pie.
         OR EXISTS (
           SELECT 1
             FROM series_guardias sg
             JOIN servicios s ON s.id = sg.servicio_id
                             AND s.prestadora_id = sg.prestadora_id
                             AND s.estado = 'vigente'
            WHERE sg.prestadora_id = yo.tenant
              AND sg.estado <> 'cancelada'
              AND yo.asistente IS NOT NULL
              AND sg.asistente_id = yo.asistente
              AND (sg.paciente_id = pac.id
                   OR EXISTS (SELECT 1 FROM series_guardias_pacientes sp
                               WHERE sp.serie_id = sg.id AND sp.paciente_id = pac.id))
         )

         -- Quien tiene tomada una alarma de una de sus guardias, mientras la tenga.
         OR EXISTS (
           SELECT 1
             FROM guardias g
            WHERE g.prestadora_id = yo.tenant
              AND g.id = ANY (interno.guardias_a_la_vista_por_una_alarma(true))
              AND (g.paciente_id = pac.id
                   OR EXISTS (SELECT 1 FROM guardia_pacientes gp
                               WHERE gp.guardia_id = g.id AND gp.paciente_id = pac.id))
         )
       )
  )
$$;


ALTER FUNCTION "interno"."atiende_al_paciente"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."autorizar_cambio_de_clave"("p_usuario" "uuid", "p_autorizado_por" "text", "p_minutos" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  v_id uuid;
begin
  if not interno.es_cuenta_de_administracion(p_usuario) then
    raise exception 'autorizar_cambio_de_clave: la cuenta no es de administración';
  end if;
  if coalesce(btrim(p_autorizado_por), '') = '' then
    raise exception 'autorizar_cambio_de_clave: falta quién lo autoriza';
  end if;
  if p_minutos is null or p_minutos < 1 then
    raise exception 'autorizar_cambio_de_clave: los minutos tienen que ser un entero mayor que cero';
  end if;

  update interno.cambios_de_clave_autorizados
     set anulado_en = now()
   where usuario_id = p_usuario and usado_en is null and anulado_en is null;

  insert into interno.cambios_de_clave_autorizados (prestadora_id, usuario_id, autorizado_por, expira_en)
  select u.prestadora_id, u.id, btrim(p_autorizado_por), now() + make_interval(mins => p_minutos)
    from public.usuarios u
   where u.id = p_usuario
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "interno"."autorizar_cambio_de_clave"("p_usuario" "uuid", "p_autorizado_por" "text", "p_minutos" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."aviso_de_borrado_de_consultas_a_hce_pendiente"("p_prestadora" "uuid") RETURNS TABLE("anio" integer, "se_borra_el" "date", "aviso" "text", "dias" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH v AS (
    SELECT * FROM interno.consultas_a_hce_por_vencer(p_prestadora)
  ), ya AS (
    SELECT ra.accion
      FROM registro_actividad ra, v
     WHERE ra.prestadora_id = p_prestadora
       AND ra.accion IN ('preaviso_de_borrado', 'notificacion_de_borrado')
       AND ra.detalle ->> 'anio' = v.anio::text
  )
  SELECT v.anio, v.se_borra_el,
         CASE
           WHEN current_date >= v.notificacion_el THEN 'notificacion'
           ELSE 'preaviso'
         END,
         v.se_borra_el - current_date
    FROM v
   WHERE current_date < v.se_borra_el
     AND current_date >= v.preaviso_el
     AND NOT EXISTS (SELECT 1 FROM ya WHERE ya.accion = 'notificacion_de_borrado')
     AND (current_date >= v.notificacion_el
          OR NOT EXISTS (SELECT 1 FROM ya WHERE ya.accion = 'preaviso_de_borrado'));
$$;


ALTER FUNCTION "interno"."aviso_de_borrado_de_consultas_a_hce_pendiente"("p_prestadora" "uuid") OWNER TO "postgres";


