CREATE OR REPLACE FUNCTION "interno"."calcular_prorroga_de_gracia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_gracia date;
BEGIN
  v_gracia := interno.gracia_hasta(NEW.asistente_id, NEW.tipo_documento_id, CURRENT_DATE);
  IF v_gracia IS NULL THEN
    RAISE EXCEPTION 'documento_sin_gracia' USING ERRCODE = '23514';
  END IF;
  NEW.hasta := GREATEST(v_gracia, CURRENT_DATE) + NEW.dias;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."calcular_prorroga_de_gracia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."cerrar_vigencia_de_la_prestacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  recien_se_da_de_baja boolean;
  la_trae_escrita boolean;
BEGIN
  IF NEW.estado <> 'de_baja' THEN
    RETURN NEW;
  END IF;

  recien_se_da_de_baja := TG_OP = 'INSERT' OR OLD.estado <> 'de_baja';
  la_trae_escrita := CASE
    WHEN TG_OP = 'INSERT' THEN NEW.vigente_hasta IS NOT NULL
    ELSE NEW.vigente_hasta IS DISTINCT FROM OLD.vigente_hasta
  END;

  IF recien_se_da_de_baja AND NOT la_trae_escrita THEN
    -- `GREATEST` cubre la prestacion que se da de baja antes de arrancar: no
    -- puede terminar antes de empezar, y la restriccion de mas arriba lo exige.
    NEW.vigente_hasta := GREATEST(NEW.vigente_desde, CURRENT_DATE);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."cerrar_vigencia_de_la_prestacion"() OWNER TO "postgres";


