CREATE OR REPLACE FUNCTION "interno"."coordinador_alcanza_asistente"("p_asistente_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT interno.coordinador_alcanza_asistente_de(auth.uid(), p_asistente_id);
$$;


ALTER FUNCTION "interno"."coordinador_alcanza_asistente"("p_asistente_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."coordinador_alcanza_asistente"("p_asistente_id" "uuid") IS 'Si quien esta mirando coordina alguno de los lugares donde ese Asistente acepta trabajar.';



CREATE OR REPLACE FUNCTION "interno"."coordinador_alcanza_asistente_de"("p_usuario" "uuid", "p_asistente_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM usuarios u
    JOIN usuario_lugares ul ON ul.usuario_id = u.id
    JOIN asistente_lugares al ON al.lugar_id = ul.lugar_id
    WHERE u.id = p_usuario
      AND u.rol = 'coordinador'
      AND al.asistente_id = p_asistente_id
  )
  OR EXISTS (
    SELECT 1
    FROM usuarios u
    JOIN ausencias a ON a.coordinador_que_cubre_id = u.id
                    AND a.prestadora_id = u.prestadora_id
    JOIN usuario_lugares ul ON ul.usuario_id = a.usuario_id
                           AND ul.prestadora_id = a.prestadora_id
    JOIN asistente_lugares al ON al.lugar_id = ul.lugar_id
    WHERE u.id = p_usuario
      AND u.rol = 'coordinador'
      AND a.usuario_id IS NOT NULL
      AND a.fecha_inicio <= current_date
      AND (a.fecha_vuelta_real IS NULL OR a.fecha_vuelta_real > current_date)
      AND al.asistente_id = p_asistente_id
  );
$$;


ALTER FUNCTION "interno"."coordinador_alcanza_asistente_de"("p_usuario" "uuid", "p_asistente_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."coordinador_alcanza_guardia"("p_asistente_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT p_asistente_id IS NULL
      OR interno.coordinador_alcanza_asistente(p_asistente_id);
$$;


ALTER FUNCTION "interno"."coordinador_alcanza_guardia"("p_asistente_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."coordinador_alcanza_guardia"("p_asistente_id" "uuid") IS 'Si un Coordinador alcanza lo que pasa por ese Asistente: comparte zona con él, o no hay Asistente todavía. La usan las políticas de guardias y de series_guardias, y es el único lugar donde está escrita esa regla.';



CREATE OR REPLACE FUNCTION "interno"."coordinador_alcanza_la_guardia_de"("p_servicio" "uuid", "p_paciente" "uuid", "p_guardia" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT CASE
    WHEN p_servicio IS NOT NULL THEN interno.coordina_el_servicio(p_servicio)
    ELSE (p_paciente IS NOT NULL AND interno.coordinador_ve_al_paciente(p_paciente))
      OR EXISTS (SELECT 1 FROM guardia_pacientes gp
                  WHERE gp.guardia_id = p_guardia
                    AND interno.coordinador_ve_al_paciente(gp.paciente_id))
  END;
$$;


