CREATE OR REPLACE FUNCTION "interno"."excepcion_por_documentos"("p_prestadora_id" "uuid", "p_guardia_id" "uuid", "p_asistente_id" "uuid", "p_bloquean" "text"[], "p_motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF cardinality(p_bloquean) = 0 THEN
    RETURN;
  END IF;

  IF btrim(COALESCE(p_motivo, '')) = '' THEN
    RAISE EXCEPTION 'documentos_bloquean:%:', array_to_string(p_bloquean, ', ')
      USING ERRCODE = '23514';
  END IF;

  IF NOT interno.tiene_permiso('asignar_con_documentos_pendientes') THEN
    RAISE EXCEPTION 'sin_permiso_para_asignar_con_documentos_pendientes' USING ERRCODE = '42501';
  END IF;

  INSERT INTO excepciones_por_documentos (prestadora_id, guardia_id, asistente_id, usuario_id, motivo, documentos)
  VALUES (p_prestadora_id, p_guardia_id, p_asistente_id, interno.usuario_de_la_sesion(), btrim(p_motivo), p_bloquean);
END;
$$;


ALTER FUNCTION "interno"."excepcion_por_documentos"("p_prestadora_id" "uuid", "p_guardia_id" "uuid", "p_asistente_id" "uuid", "p_bloquean" "text"[], "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_contratante_del_servicio"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  prestadora_del_cliente uuid;
begin
  select prestadora_id into prestadora_del_cliente
    from clientes where id = new.cliente_id;

  if prestadora_del_cliente is null then
    raise exception 'contratante_inexistente:%', new.cliente_id;
  end if;

  if prestadora_del_cliente <> new.prestadora_id then
    raise exception 'contratante_de_otra_prestadora:%', new.cliente_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "interno"."exigir_contratante_del_servicio"() OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."exigir_contratante_del_servicio"() IS 'Que el Cliente de un Servicio exista y sea de la misma Prestadora, y que el alta diga cuál Legajo lo contrató. Es lo que reemplaza a la clave foránea que no se puede poner, porque la tabla destino depende del tipo.';



CREATE OR REPLACE FUNCTION "interno"."exigir_documentos_en_asignacion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_bloquean text[];
  v_dia      date;
  v_paciente uuid;
  v_servicio uuid;
BEGIN
  IF NOT (TG_OP = 'INSERT'
          OR (NEW.estado = 'aceptada' AND OLD.estado IS DISTINCT FROM 'aceptada')) THEN
    RETURN NEW;
  END IF;

  IF NEW.guardia_id IS NOT NULL THEN
    IF interno.hay_excepcion_por_documentos(NEW.guardia_id, NEW.asistente_id) THEN
      RETURN NEW;
    END IF;

    SELECT interno.dia_en_que_termina_guardia(g.fecha, g.hora_inicio, g.hora_fin, g.dias_hasta_el_fin),
           g.paciente_id, g.servicio_id
      INTO v_dia, v_paciente, v_servicio
      FROM public.guardias g
     WHERE g.id = NEW.guardia_id;
  ELSIF NEW.serie_id IS NOT NULL THEN
    SELECT GREATEST(s.vigente_desde, CURRENT_DATE), s.paciente_id, s.servicio_id
      INTO v_dia, v_paciente, v_servicio
      FROM public.series_guardias s
     WHERE s.id = NEW.serie_id;
  END IF;

  v_bloquean := interno.documentos_que_bloquean(NEW.asistente_id, COALESCE(v_dia, CURRENT_DATE), v_paciente, v_servicio);

  IF cardinality(v_bloquean) > 0 THEN
    RAISE EXCEPTION 'documentos_bloquean:%:', array_to_string(v_bloquean, ', ')
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."exigir_documentos_en_asignacion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_documentos_en_guardia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_bloquean text[];
BEGIN
  IF NEW.asistente_id IS NULL
     OR (TG_OP = 'UPDATE' AND NEW.asistente_id IS NOT DISTINCT FROM OLD.asistente_id) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND interno.hay_excepcion_por_documentos(NEW.id, NEW.asistente_id) THEN
    RETURN NEW;
  END IF;

  v_bloquean := interno.documentos_que_bloquean(
    NEW.asistente_id,
    interno.dia_en_que_termina_guardia(NEW.fecha, NEW.hora_inicio, NEW.hora_fin, NEW.dias_hasta_el_fin),
    NEW.paciente_id,
    NEW.servicio_id
  );

  IF cardinality(v_bloquean) > 0 THEN
    RAISE EXCEPTION 'documentos_bloquean:%:', array_to_string(v_bloquean, ', ')
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."exigir_documentos_en_guardia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_familiar_del_relevo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  clase_del_familiar text;
begin
  if new.familiar_persona_id is null then
    raise exception 'falta_el_familiar_del_relevo';
  end if;

  select clase into clase_del_familiar
    from public.personas
   where id = new.familiar_persona_id;

  -- Falla cerrado: sin Ficha a la vista, o con una que no es una persona física, no se guarda.
  if clase_del_familiar is distinct from 'fisica' then
    raise exception 'el_familiar_del_relevo_es_una_persona';
  end if;

  return new;
end
$$;


ALTER FUNCTION "interno"."exigir_familiar_del_relevo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_final_del_catalogo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_pide_detalle boolean;
BEGIN
  -- Un expediente abierto no tiene final, y eso es lo normal: se abre sin él.
  IF NEW.resuelto_como IS NULL THEN
    RETURN NEW;
  END IF;

  -- Lo ya escrito no se revisa. Los expedientes cerrados antes de que existiera el catálogo
  -- guardan finales que no están en él, y tocarles cualquier otra columna no es motivo para
  -- rechazarlos.
  IF TG_OP = 'UPDATE' AND OLD.resuelto_como IS NOT DISTINCT FROM NEW.resuelto_como THEN
    RETURN NEW;
  END IF;

  SELECT f.pide_detalle INTO v_pide_detalle
  FROM finales_turno_sin_cubrir f
  WHERE f.prestadora_id = NEW.prestadora_id
    AND f.activo
    AND coalesce(f.clave, f.nombre) = NEW.resuelto_como
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'final_de_turno_inexistente:%', NEW.resuelto_como;
  END IF;

  IF v_pide_detalle AND coalesce(btrim(NEW.resuelto_detalle), '') = '' THEN
    RAISE EXCEPTION 'final_de_turno_pide_detalle:%', NEW.resuelto_como;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."exigir_final_del_catalogo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_motivo_de_cierre_del_catalogo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_pide_detalle boolean;
BEGIN
  SELECT m.pide_detalle INTO v_pide_detalle
  FROM motivos_cierre_servicio m
  WHERE m.prestadora_id = NEW.prestadora_id
    AND m.activo
    AND coalesce(m.clave, m.nombre) = NEW.motivo
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'motivo_de_cierre_inexistente:%', NEW.motivo;
  END IF;

  IF v_pide_detalle AND coalesce(btrim(NEW.motivo_detalle), '') = '' THEN
    RAISE EXCEPTION 'motivo_de_cierre_pide_detalle:%', NEW.motivo;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."exigir_motivo_de_cierre_del_catalogo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_motivo_de_sustitucion_del_catalogo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_pide_detalle boolean;
BEGIN
  -- Sin causa cargada no hay nada que controlar. Es el caso de las coberturas viejas, que se
  -- anotaron cuando este catálogo no existía y no se reescriben.
  IF NEW.motivo IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT m.pide_detalle INTO v_pide_detalle
  FROM motivos_sustitucion_guardia m
  WHERE m.prestadora_id = NEW.prestadora_id
    AND m.activo
    AND coalesce(m.clave, m.nombre) = NEW.motivo
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'motivo_de_sustitucion_inexistente:%', NEW.motivo;
  END IF;

  IF v_pide_detalle AND coalesce(btrim(NEW.motivo_detalle), '') = '' THEN
    RAISE EXCEPTION 'motivo_de_sustitucion_pide_detalle:%', NEW.motivo;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."exigir_motivo_de_sustitucion_del_catalogo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."exigir_paciente_y_servicio_del_mismo_contratante"("p_paciente_id" "uuid", "p_servicio_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  cliente_servicio uuid;
  prestadora_servicio uuid;
  cliente_paciente uuid;
  prestadora_paciente uuid;
BEGIN
  -- Sin Servicio no hay nada que comparar.
  IF p_servicio_id IS NULL THEN
    RETURN;
  END IF;

  SELECT cliente_id, prestadora_id
    INTO cliente_servicio, prestadora_servicio
    FROM servicios WHERE id = p_servicio_id;

  IF prestadora_servicio IS NULL THEN
    RAISE EXCEPTION 'servicio_inexistente:%', p_servicio_id;
  END IF;

  SELECT cliente_id, prestadora_id
    INTO cliente_paciente, prestadora_paciente
    FROM pacientes WHERE id = p_paciente_id;

  IF prestadora_paciente IS NULL THEN
    RAISE EXCEPTION 'paciente_inexistente:%', p_paciente_id;
  END IF;

  IF prestadora_paciente <> prestadora_servicio THEN
    RAISE EXCEPTION 'paciente_de_otra_prestadora:%', p_paciente_id;
  END IF;

  IF cliente_paciente IS NULL OR cliente_paciente <> cliente_servicio THEN
    RAISE EXCEPTION 'paciente_fuera_del_contratante:%:%', p_paciente_id, p_servicio_id;
  END IF;
END;
$$;


ALTER FUNCTION "interno"."exigir_paciente_y_servicio_del_mismo_contratante"("p_paciente_id" "uuid", "p_servicio_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."exigir_paciente_y_servicio_del_mismo_contratante"("p_paciente_id" "uuid", "p_servicio_id" "uuid") IS 'La regla de que un Servicio sólo factura Pacientes que le corresponden, escrita una sola vez. La llaman los disparadores de guardias, prestaciones y guardia_pacientes.';



CREATE OR REPLACE FUNCTION "interno"."fila_del_pedido"("p_tabla" "text", "p_columnas" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_partes text;
BEGIN
  IF p_columnas IS NULL OR p_columnas = ARRAY['*'] THEN
    RETURN 'to_jsonb(t)';
  END IF;
  IF cardinality(p_columnas) = 0 OR cardinality(p_columnas) > 50 THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  SELECT string_agg(format('%L, t.%I', c, interno.columna_del_pedido(p_tabla, c)), ', ')
    INTO v_partes
    FROM unnest(p_columnas) c;
  RETURN 'jsonb_build_object(' || v_partes || ')';
END;
$$;


ALTER FUNCTION "interno"."fila_del_pedido"("p_tabla" "text", "p_columnas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."firmante_autorizacion_signos_vitales"("p_paciente" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
           (SELECT a.persona_id FROM apoderados a
             WHERE a.cliente_id = c.id
               AND a.funcion = 'signos_vitales'
               AND a.quitado_en IS NULL
               AND a.estado = 'aprobado'),
           CASE WHEN pe.clase = 'juridica' THEN NULL ELSE pe.id END)
    FROM pacientes pa
    JOIN clientes c ON c.id = pa.cliente_id
    JOIN personas pe ON pe.id = c.contratante_persona_id
   WHERE pa.id = p_paciente;
$$;


ALTER FUNCTION "interno"."firmante_autorizacion_signos_vitales"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."fn_modalidad_en_asignacion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_modalidad text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF NEW.guardia_id IS NOT NULL THEN
    SELECT g.canal_modalidad INTO v_modalidad
      FROM public.guardias g
     WHERE g.id = NEW.guardia_id;
  ELSIF NEW.serie_id IS NOT NULL THEN
    SELECT s.canal_modalidad INTO v_modalidad
      FROM public.series_guardias s
     WHERE s.id = NEW.serie_id;
  END IF;

  IF v_modalidad IS NOT NULL
     AND NOT interno.asistente_trabaja_en_modalidad(NEW.asistente_id, v_modalidad) THEN
    RAISE EXCEPTION 'modalidad_bloquea:%:', v_modalidad
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."fn_modalidad_en_asignacion"() OWNER TO "postgres";


