CREATE OR REPLACE FUNCTION "interno"."la_prohibicion_alcanza_lo_suyo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  la_prohibicion public.tareas_tipo_asistente%rowtype;
  la_tarea public.tareas_tipo_asistente%rowtype;
begin
  select * into la_prohibicion from public.tareas_tipo_asistente where id = new.prohibicion_id;

  if not found or la_prohibicion.clase <> 'prohibida' then
    raise exception 'Sólo una tarea prohibida alcanza otras tareas o vías.' using errcode = 'P0001';
  end if;

  if new.prestadora_id is distinct from la_prohibicion.prestadora_id then
    raise exception 'Lo que alcanza una prohibición es de quien escribió la prohibición.'
      using errcode = 'P0001';
  end if;

  if tg_table_name = 'tareas_que_alcanza_la_prohibicion' then
    select * into la_tarea from public.tareas_tipo_asistente where id = new.tarea_id;

    if not found then
      raise exception 'La tarea no existe o no es de esta Prestadora.' using errcode = 'P0001';
    end if;

    if la_tarea.prestadora_id is null and la_prohibicion.prestadora_id is null
       and la_tarea.pais <> la_prohibicion.pais then
      raise exception 'Una prohibición del producto alcanza sólo tareas de su país.'
        using errcode = 'P0001';
    end if;

    if la_tarea.prestadora_id is not null
       and la_tarea.prestadora_id is distinct from la_prohibicion.prestadora_id then
      raise exception 'Esa tarea es de otra Prestadora.' using errcode = 'P0001';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "interno"."la_prohibicion_alcanza_lo_suyo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."la_resolucion_dice_quien_la_firmo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_pide_detalle boolean;
BEGIN
  -- Quién firma no viene en el pedido: sale de la sesión, y pisa lo que haya llegado.
  IF interno.usuario_de_la_sesion() IS NOT NULL THEN
    NEW.resuelto_por := interno.usuario_de_la_sesion();
  END IF;

  NEW.detalle := nullif(btrim(coalesce(NEW.detalle, '')), '');

  -- Y el detalle lo exige la base, no la pantalla. Acá y no adentro de `resolver`, para que valga
  -- también si alguien escribe la fila por su cuenta.
  SELECT m.pide_detalle INTO v_pide_detalle
    FROM motivos_resolucion m
   WHERE m.id = NEW.motivo_id;

  IF coalesce(v_pide_detalle, false) AND NEW.detalle IS NULL THEN
    RAISE EXCEPTION 'resolucion_sin_detalle';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."la_resolucion_dice_quien_la_firmo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."la_respuesta_al_relevo_la_fecha_la_base"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.respuesta := NULL;
    NEW.minutos_que_indica := NULL;
    NEW.minutos_por_gps := NULL;
    NEW.respondido_at := NULL;
    RETURN NEW;
  END IF;
  IF OLD.respuesta IS NULL AND NEW.respuesta IS NOT NULL THEN
    NEW.respondido_at := now();
  ELSE
    NEW.respondido_at := OLD.respondido_at;
  END IF;
  RETURN NEW;
END;
$$;


