CREATE OR REPLACE FUNCTION "interno"."pedido_de_salud_valido"("p_tabla" "text", "p_origen" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR interno.prestadora_actual() IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_tabla IS NULL OR NOT (p_tabla = ANY (interno.tablas_de_salud())) THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  IF nullif(btrim(coalesce(p_origen, '')), '') IS NULL OR length(p_origen) > 200 THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
END;
$$;


ALTER FUNCTION "interno"."pedido_de_salud_valido"("p_tabla" "text", "p_origen" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."persona_autorizada_puede"("p_usuario" "uuid", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT CASE
    WHEN p_usuario IS NULL THEN false
    WHEN EXISTS (
      SELECT 1 FROM clientes f
       WHERE f.usuario_id = p_usuario
         AND f.prestadora_id = interno.prestadora_actual()
    ) THEN true
    ELSE COALESCE(
      (SELECT p.permitido
         FROM permisos_personas_autorizadas p
        WHERE p.usuario_id = p_usuario
          AND p.clave = p_clave),
      false
    )
  END
$$;


ALTER FUNCTION "interno"."persona_autorizada_puede"("p_usuario" "uuid", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."prestadora_actual"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
    -- 1. El permiso de acceso que CeltaTech abrió para esta cuenta, mientras está vigente. Tapa
    --    todo lo demás.
    (SELECT s.prestadora_id FROM permisos_de_acceso s
      WHERE s.admin_id = auth.uid()
        AND s.salida_at IS NULL
        AND s.expira_at > NOW()
        AND s.ultima_actividad_at > NOW() - INTERVAL '5 minutes'
      ORDER BY s.entrada_at DESC LIMIT 1),

    -- 2. La Prestadora de la cuenta con la que se entró, si la cuenta no está desactivada. Es una
    --    sola: para trabajar en otra hay que salir de ésta y entrar allá, con la cuenta de allá.
    (SELECT prestadora_id FROM usuarios WHERE id = auth.uid() AND desactivada_en IS NULL),

    -- 3. El trabajo sin persona y la copia de respaldo: la Prestadora para la que el backend
    --    generó su credencial.
    (SELECT NULLIF(auth.jwt() ->> 'prestadora_id', '')::uuid
      WHERE auth.jwt() ->> 'role' IN ('trabajo_sin_persona', 'copia_de_respaldo'))
  )
$$;


ALTER FUNCTION "interno"."prestadora_actual"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."prestadora_de_la_restriccion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  SELECT prestadora_id INTO v_prestadora FROM public.clientes WHERE id = NEW.cliente_id;
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'El Cliente del aviso no existe';
  END IF;
  NEW.prestadora_id := v_prestadora;
  RETURN NEW;
END;
$$;


