CREATE OR REPLACE FUNCTION "interno"."quien_tiene_la_alarma"("p_prestadora" "uuid", "p_tipo" "text", "p_referencia" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT a.tomada_por
    FROM alarmas_tomadas a
   WHERE a.prestadora_id = p_prestadora
     AND a.tipo = p_tipo
     AND a.referencia_id = p_referencia
     AND a.soltada_at IS NULL
     AND a.vence_at > now()
   ORDER BY a.tomada_at DESC
   LIMIT 1;
$$;


