CREATE OR REPLACE FUNCTION "public"."mover_turno_a_otro_paciente"("p_guardia_id" "uuid", "p_paciente_id" "uuid", "p_fecha" "date", "p_hora_inicio" time without time zone, "p_hora_fin" time without time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_guardia    public.guardias;
  v_asistente  uuid;
  v_nueva      uuid;
  v_quitar     jsonb;
  v_asignar    jsonb;
BEGIN
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'guardia_no_encontrada';
  END IF;

  SELECT * INTO v_guardia
    FROM guardias
   WHERE id = p_guardia_id
     AND prestadora_id = v_prestadora;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'guardia_no_encontrada';
  END IF;

  IF v_guardia.estado <> 'programada' THEN
    RAISE EXCEPTION 'guardia_no_se_asigna' USING ERRCODE = '23514';
  END IF;

  -- El que esperaba respuesta manda sobre el que figura: es a quien se le asignó por última vez.
  SELECT asistente_id INTO v_asistente
    FROM asignaciones_de_turno
   WHERE guardia_id = p_guardia_id
     AND prestadora_id = v_prestadora
     AND estado = 'sin_responder';
  v_asistente := COALESCE(v_asistente, v_guardia.asistente_id);

  IF v_asistente IS NULL THEN
    RAISE EXCEPTION 'guardia_sin_asistente' USING ERRCODE = '23514';
  END IF;

  -- El Paciente de destino tiene que ser de la misma Prestadora. Un identificador de otra no se
  -- distingue de uno que no existe.
  IF NOT EXISTS (SELECT 1 FROM pacientes p WHERE p.id = p_paciente_id AND p.prestadora_id = v_prestadora) THEN
    RAISE EXCEPTION 'paciente_no_encontrado';
  END IF;

  INSERT INTO guardias (
    prestadora_id, paciente_id, servicio_id, coordinador_id, fecha, hora_inicio, hora_fin,
    dias_hasta_el_fin, modalidad, canal_modalidad
  )
  VALUES (
    v_prestadora, p_paciente_id, v_guardia.servicio_id, v_guardia.coordinador_id,
    COALESCE(p_fecha, v_guardia.fecha),
    COALESCE(p_hora_inicio, v_guardia.hora_inicio),
    COALESCE(p_hora_fin, v_guardia.hora_fin),
    v_guardia.dias_hasta_el_fin, v_guardia.modalidad, v_guardia.canal_modalidad
  )
  RETURNING id INTO v_nueva;

  -- Primero se lo saca del original —que abre la alarma— y después se le ofrece el nuevo.
  v_quitar  := public.asignar_turno(p_guardia_id, NULL);
  v_asignar := public.asignar_turno(v_nueva, v_asistente);

  RETURN jsonb_build_object(
    'guardia_nueva_id', v_nueva,
    'asistente_id', v_asistente,
    'titular_retirado', v_quitar->'titular_retirado',
    'pendiente_retirado', v_quitar->'pendiente_retirado'
  );
END;
$$;


ALTER FUNCTION "public"."mover_turno_a_otro_paciente"("p_guardia_id" "uuid", "p_paciente_id" "uuid", "p_fecha" "date", "p_hora_inicio" time without time zone, "p_hora_fin" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nombrar_apoderado"("p_cliente" "uuid", "p_funcion" "text", "p_nombre" "text", "p_apellido" "text", "p_cuil" "text", "p_archivo" "text", "p_usuario" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := interno.quien_gestiona_al_apoderado(p_cliente, p_usuario);
  v_prestadora uuid := interno.prestadora_actual();
  v_pais text;
  v_numero text;
  v_tipo text;
  v_persona uuid;
  v_id uuid;
BEGIN
  IF p_funcion IS NULL OR p_funcion NOT IN ('pagos', 'signos_vitales')
     OR btrim(COALESCE(p_nombre, '')) = '' OR btrim(COALESCE(p_apellido, '')) = ''
     OR btrim(COALESCE(p_cuil, '')) = '' OR btrim(COALESCE(p_archivo, '')) = '' THEN
    RAISE EXCEPTION 'faltan_datos' USING ERRCODE = '22023';
  END IF;

  v_numero := regexp_replace(p_cuil, '[\s.\-]', '', 'g');
  IF NOT interno.cumple_modulo_11(v_numero) THEN
    RAISE EXCEPTION 'numero_no_valido' USING ERRCODE = '22023';
  END IF;

  IF p_archivo NOT LIKE v_prestadora::text || '/' || p_cliente::text || '/' || p_funcion || '/%' THEN
    RAISE EXCEPTION 'archivo_invalido' USING ERRCODE = '22023';
  END IF;

  SELECT pais INTO v_pais FROM prestadoras WHERE id = v_prestadora;

  -- Si esa persona ya tiene Ficha se usa la misma, sin cambiarle nada.
  SELECT p.id INTO v_persona
    FROM personas p
   WHERE p.prestadora_id = v_prestadora
     AND p.clase = 'fisica'
     AND p.documento_numero = v_numero
     AND p.documento_tipo IN (
       SELECT c.codigo FROM catalogo_documentos_de_identidad c
        WHERE c.pais = v_pais AND c.clase = 'fisica' AND c.verifica_modulo_11 AND c.activo)
   LIMIT 1;

  IF v_persona IS NULL THEN
    SELECT c.codigo INTO v_tipo
      FROM catalogo_documentos_de_identidad c
     WHERE c.pais = v_pais AND c.clase = 'fisica' AND c.verifica_modulo_11 AND c.activo
     ORDER BY c.orden
     LIMIT 1;
    IF v_tipo IS NULL THEN
      RAISE EXCEPTION 'documento_no_corresponde' USING ERRCODE = '22023';
    END IF;

    INSERT INTO personas (prestadora_id, clase, nombre, apellido, documento_tipo, documento_numero, dni)
    VALUES (v_prestadora, 'fisica', btrim(p_nombre), btrim(p_apellido), v_tipo, v_numero,
            ltrim(substr(v_numero, 3, 8), '0'))
    RETURNING id INTO v_persona;
  END IF;

  UPDATE apoderados
     SET quitado_en = now(), quitado_por = v_quien
   WHERE cliente_id = p_cliente AND funcion = p_funcion AND quitado_en IS NULL;

  INSERT INTO apoderados (prestadora_id, cliente_id, funcion, persona_id, archivo_url, estado, cargado_por)
  VALUES (v_prestadora, p_cliente, p_funcion, v_persona, p_archivo, 'en_revision', v_quien)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."nombrar_apoderado"("p_cliente" "uuid", "p_funcion" "text", "p_nombre" "text", "p_apellido" "text", "p_cuil" "text", "p_archivo" "text", "p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pedir_medicacion"("p_paciente" "uuid", "p_medicamento" "text", "p_dosis" "text", "p_frecuencia" "text", "p_via" "uuid", "p_prescripcion" "text", "p_desde" "date", "p_hasta" "date", "p_documento" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_antes text := coalesce(current_setting('careonys.lectura_de_salud', true), '');
  v_id uuid := gen_random_uuid();
  v_quien uuid := auth.uid();
  v_prestadora uuid;
  v_cliente uuid;
  v_en_la_app boolean;
BEGIN
  SELECT p.prestadora_id, p.cliente_id INTO v_prestadora, v_cliente
    FROM pacientes p
   WHERE p.id = p_paciente;
  IF v_prestadora IS NULL OR v_quien IS NULL THEN
    RAISE EXCEPTION 'paciente_no_encontrado' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('careonys.lectura_de_salud', 'anotada', true);
  INSERT INTO indicaciones_medicacion
    (id, prestadora_id, paciente_id, cliente_id, medicamento, dosis, frecuencia,
     via_administracion_id, prescripcion_archivo_url, fecha_desde, fecha_hasta, solicitado_por)
  VALUES
    (v_id, v_prestadora, p_paciente, v_cliente, p_medicamento, p_dosis, p_frecuencia,
     p_via, p_prescripcion, p_desde, p_hasta, v_quien);
  PERFORM set_config('careonys.lectura_de_salud', v_antes, true);
  PERFORM interno.anotar_lo_que_se_leyo('indicaciones_medicacion', ARRAY[p_paciente], 'pedir_medicacion');

  IF p_documento IS NOT NULL THEN
    v_en_la_app := coalesce((p_documento ->> 'en_la_app')::boolean, false);
    INSERT INTO consentimientos_medicacion
      (prestadora_id, indicacion_id, documento_texto, documento_verificador, documento_idioma,
       estado, cerrado_como, cerrado_en, cerrado_desde, cargado_por)
    VALUES
      (v_prestadora, v_id, p_documento ->> 'texto', p_documento ->> 'verificador', p_documento ->> 'idioma',
       CASE WHEN v_en_la_app THEN 'cerrado' ELSE 'pendiente_firma' END,
       CASE WHEN v_en_la_app THEN 'confirmado_en_la_app' END,
       CASE WHEN v_en_la_app THEN now() END,
       CASE WHEN v_en_la_app THEN 'app_clientes' END,
       v_quien);
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."pedir_medicacion"("p_paciente" "uuid", "p_medicamento" "text", "p_dosis" "text", "p_frecuencia" "text", "p_via" "uuid", "p_prescripcion" "text", "p_desde" "date", "p_hasta" "date", "p_documento" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."periodos_pagados_de_la_sesion"() RETURNS TABLE("desde" "date", "hasta" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT l.periodo_desde, l.periodo_hasta
  FROM public.liquidaciones_asistente l
  WHERE l.estado = 'pagada'
    AND l.prestadora_id = interno.prestadora_actual()
    AND l.asistente_id = interno.asistente_de_la_sesion();
$$;


ALTER FUNCTION "public"."periodos_pagados_de_la_sesion"() OWNER TO "postgres";


