CREATE OR REPLACE FUNCTION "public"."sumar_contactos_al_saldo"("p_acceso_id" "uuid", "p_cuantos" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_saldo integer;
BEGIN
  IF p_cuantos IS NULL OR p_cuantos <= 0 THEN
    RAISE EXCEPTION 'sumar_contactos_al_saldo: se suman contactos, no cero ni menos';
  END IF;

  -- En una sola sentencia. Un saldo vacío es un acceso que todavía no se sostenía por saldo: la
  -- primera carga lo estrena, y de ahí en más se le suma lo de cada compra.
  UPDATE public.accesos_intermediacion
     SET saldo_contactos = COALESCE(saldo_contactos, 0) + p_cuantos,
         updated_at = now()
   WHERE id = p_acceso_id
  RETURNING saldo_contactos INTO v_saldo;

  -- Sin fila, queda nulo. Se devuelve así: quien llama tiene que poder distinguir «no había qué
  -- cargar» de «quedó en cero», que no son lo mismo.
  RETURN v_saldo;
END;
$$;


ALTER FUNCTION "public"."sumar_contactos_al_saldo"("p_acceso_id" "uuid", "p_cuantos" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sumar_contactos_al_saldo"("p_acceso_id" "uuid", "p_cuantos" integer) IS 'Le suma contactos al saldo de un acceso y devuelve con cuántos queda. Se llama cuando entra la plata de un paquete. Suma y no pisa: el paquete no vence por calendario, así que lo que quedó sin usar sigue estando.';



CREATE OR REPLACE FUNCTION "public"."sumar_intento_de_codigo"("p_tabla" "text", "p_id" "uuid", "p_prestadora_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_intentos integer;
BEGIN
  -- Falla cerrado: sin Prestadora no se cuenta nada.
  IF p_prestadora_id IS NULL THEN
    RAISE EXCEPTION 'sumar_intento_de_codigo: falta la Prestadora';
  END IF;

  IF p_tabla = 'instrucciones_acceso_personas_autorizadas' THEN
    UPDATE public.instrucciones_acceso_personas_autorizadas
       SET codigo_intentos = codigo_intentos + 1
     WHERE id = p_id
       AND prestadora_id = p_prestadora_id
    RETURNING codigo_intentos INTO v_intentos;

  ELSIF p_tabla = 'codigos_al_telefono' THEN
    UPDATE public.codigos_al_telefono
       SET codigo_intentos = codigo_intentos + 1
     WHERE id = p_id
       AND prestadora_id = p_prestadora_id
    RETURNING codigo_intentos INTO v_intentos;

  ELSE
    RAISE EXCEPTION 'sumar_intento_de_codigo: esa tabla no lleva cuenta de intentos';
  END IF;

  -- Si no se actualizó ninguna fila, `v_intentos` queda nulo. Se devuelve así a propósito: quien
  -- llama trata el nulo como "se agotaron", que es lo que corresponde cuando no se pudo contar.
  RETURN v_intentos;
END;
$$;


ALTER FUNCTION "public"."sumar_intento_de_codigo"("p_tabla" "text", "p_id" "uuid", "p_prestadora_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tiene_permiso_de"("p_usuario" "uuid", "p_accion" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rol           TEXT;
  v_prestadora_id UUID;
  v_cfg           permisos_prestadora;
  v_solo_admin    BOOLEAN;
BEGIN
  SELECT rol, prestadora_id INTO v_rol, v_prestadora_id FROM usuarios WHERE id = p_usuario;

  IF v_rol IN ('admin_prestadora', 'superadmin') THEN
    RETURN TRUE;
  END IF;
  IF v_rol IS DISTINCT FROM 'coordinador' THEN
    RETURN FALSE;
  END IF;

  SELECT * INTO v_cfg FROM permisos_prestadora
    WHERE prestadora_id = v_prestadora_id AND accion = p_accion;

  -- La Prestadora no configuró nada para esta acción: manda el valor por defecto del
  -- catálogo. Si la acción ni siquiera está en el catálogo, la respuesta es que no: un
  -- nombre mal escrito no puede terminar abriendo un permiso.
  IF NOT FOUND THEN
    SELECT default_solo_admin INTO v_solo_admin
      FROM catalogo_acciones_permisos WHERE accion = p_accion;
    RETURN NOT COALESCE(v_solo_admin, TRUE);
  END IF;

  IF p_usuario = ANY(v_cfg.excepciones_denegar)  THEN RETURN FALSE; END IF;
  IF p_usuario = ANY(v_cfg.excepciones_permitir) THEN RETURN TRUE;  END IF;
  RETURN v_cfg.alcance = 'admin_y_coordinador';
END;
$$;


ALTER FUNCTION "public"."tiene_permiso_de"("p_usuario" "uuid", "p_accion" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tiene_permiso_de"("p_usuario" "uuid", "p_accion" "text") IS 'Si un usuario tiene permitida una acción. Único lugar donde está programada esa decisión: la usan las reglas de acceso de la base y también el motor (pendiente #127).';



