    CONSTRAINT "apoderados_observado_con_motivo" CHECK ((("estado" <> 'observado'::"text") OR ("btrim"(COALESCE("motivo_observacion", ''::"text")) <> ''::"text"))),
    CONSTRAINT "apoderados_sin_poder_solo_si_falta" CHECK ((("estado" = 'falta'::"text") OR ("archivo_url" IS NOT NULL)))
);


