    CONSTRAINT "auditoria_reasignaciones_por_emergencia_motivo_check" CHECK ((("btrim"("motivo") <> ''::"text") AND ("char_length"("motivo") <= 500)))
);


ALTER TABLE "public"."auditoria_reasignaciones_por_emergencia" OWNER TO "postgres";


