CREATE TABLE IF NOT EXISTS "public"."ausencias" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asistente_id" "uuid",
    "tipo" "text" NOT NULL,
    "fecha_inicio" "date" NOT NULL,
    "fecha_fin" "date" NOT NULL,
    "certificado_url" "text",
    "dias_computados" numeric(5,1),
    "guardias_afectadas" "uuid"[],
    "observaciones" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "prestadora_id" "uuid" NOT NULL,
    "avisada_en" timestamp with time zone DEFAULT "now"(),
    "aviso_ausencia_at" timestamp with time zone,
    "aviso_ausencia_veces" integer DEFAULT 0 NOT NULL,
    "aviso_ausencia_clase" "text",
    "fecha_vuelta_real" "date",
    "pregunta_vuelta_at" timestamp with time zone,
    "pregunta_vuelta_veces" integer DEFAULT 0 NOT NULL,
    "usuario_id" "uuid",
    "coordinador_que_cubre_id" "uuid",
    CONSTRAINT "ausencias_de_una_sola_persona" CHECK (("num_nonnulls"("asistente_id", "usuario_id") = 1)),
    CONSTRAINT "ausencias_fin_no_antes_del_inicio" CHECK (("fecha_fin" >= "fecha_inicio")),
    CONSTRAINT "ausencias_tipo_check" CHECK (("tipo" = ANY (ARRAY['enfermedad_inculpable'::"text", 'accidente_inculpable'::"text", 'otra_licencia'::"text", 'ausencia_no_justificada'::"text"]))),
    CONSTRAINT "ausencias_vuelta_despues_del_inicio" CHECK ((("fecha_vuelta_real" IS NULL) OR ("fecha_vuelta_real" > "fecha_inicio")))
);


ALTER TABLE "public"."ausencias" OWNER TO "postgres";


COMMENT ON COLUMN "public"."ausencias"."avisada_en" IS 'Momento en que la Prestadora se entero de esta ausencia, que no es el momento en que se cargo. De aca sale si llego con tiempo o de golpe; la cuenta no se guarda.';



COMMENT ON COLUMN "public"."ausencias"."aviso_ausencia_at" IS 'Ultima vez que se aviso por esta ausencia. Lo escribe el proceso de fondo, no la pantalla.';



COMMENT ON COLUMN "public"."ausencias"."aviso_ausencia_veces" IS 'Cuantas veces se aviso por esta ausencia.';



COMMENT ON COLUMN "public"."ausencias"."aviso_ausencia_clase" IS 'Con que clase se aviso la ultima vez (con_tiempo o de_golpe). Si la clase cambia se vuelve a avisar aunque no haya pasado el intervalo: el problema dejo de ser el mismo.';



