);


ALTER TABLE "public"."ausencias_cambios_de_fecha" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."autorizaciones_monitoreo_paciente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "metodo" "text" NOT NULL,
    "estado" "text" NOT NULL,
    "documento_texto" "text" NOT NULL,
    "documento_verificador" "text" NOT NULL,
    "documento_idioma" "text" NOT NULL,
    "firmante_persona_id" "uuid",
    "archivo_url" "text",
    "motivo_rechazo" "text",
    "cargado_por" "uuid" NOT NULL,
    "revisado_por" "uuid",
    "revisado_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "autorizaciones_monitoreo_paciente_check" CHECK ((("metodo" = 'aplicacion'::"text") OR ("archivo_url" IS NOT NULL))),
    CONSTRAINT "autorizaciones_monitoreo_paciente_check1" CHECK ((("estado" <> 'rechazada'::"text") OR ("length"("btrim"(COALESCE("motivo_rechazo", ''::"text"))) > 0))),
    CONSTRAINT "autorizaciones_monitoreo_paciente_documento_idioma_check" CHECK (("documento_idioma" = ANY (ARRAY['es-AR'::"text", 'en'::"text", 'pt-BR'::"text"]))),
    CONSTRAINT "autorizaciones_monitoreo_paciente_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'aceptada'::"text", 'rechazada'::"text"]))),
    CONSTRAINT "autorizaciones_monitoreo_paciente_metodo_check" CHECK (("metodo" = ANY (ARRAY['aplicacion'::"text", 'documento_firmado_panel'::"text", 'documento_firmado_cliente'::"text"])))
);


ALTER TABLE "public"."autorizaciones_monitoreo_paciente" OWNER TO "postgres";


