    "asistente_sustituto_id" "uuid" NOT NULL,
    "motivo" "text",
    "motivo_detalle" "text",
    "costo_adicional" numeric,
    "moneda" "text",
    "asignada_por" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "objetada_at" timestamp with time zone,
    "aceptada_at" timestamp with time zone
);


ALTER TABLE "public"."coberturas_de_ausencia" OWNER TO "postgres";


COMMENT ON COLUMN "public"."coberturas_de_ausencia"."aceptada_at" IS 'Cuándo la aceptó el sustituto. Hasta entonces no cubre ninguna guardia.';



CREATE TABLE IF NOT EXISTS "public"."cobros_cliente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "factura_id" "uuid" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "fecha_cobro" "date" DEFAULT CURRENT_DATE NOT NULL,
    "medio" "text" NOT NULL,
    "origen" "text" DEFAULT 'panel'::"text" NOT NULL,
    "referencia_externa" "text",
    "observaciones" "text",
    "estado" "text" DEFAULT 'registrado'::"text" NOT NULL,
    "motivo_anulacion" "text",
    "anulado_por" "uuid",
    "anulado_at" timestamp with time zone,
    "registrado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cobros_cliente_anulado_con_fecha" CHECK ((("estado" = 'anulado'::"text") = ("anulado_at" IS NOT NULL))),
    CONSTRAINT "cobros_cliente_anulado_con_motivo" CHECK ((("estado" <> 'anulado'::"text") OR ("motivo_anulacion" IS NOT NULL))),
    CONSTRAINT "cobros_cliente_estado_check" CHECK (("estado" = ANY (ARRAY['registrado'::"text", 'anulado'::"text"]))),
    CONSTRAINT "cobros_cliente_monto_check" CHECK (("monto" > (0)::numeric)),
    CONSTRAINT "cobros_cliente_origen_check" CHECK (("origen" = ANY (ARRAY['panel'::"text", 'importacion'::"text", 'api'::"text", 'pasarela'::"text", 'migracion'::"text"])))
);


ALTER TABLE "public"."cobros_cliente" OWNER TO "postgres";


COMMENT ON TABLE "public"."cobros_cliente" IS 'Cada entrada de plata contra una factura de un Cliente. Varias filas por factura: así se representa el cobro parcial. No es un comprobante fiscal.';



COMMENT ON COLUMN "public"."cobros_cliente"."medio" IS 'Con que medio pago el Cliente. Es una opcion de la lista «medios_de_pago_del_cliente»: las que trae el producto y las que agrego esta Prestadora.';



CREATE TABLE IF NOT EXISTS "public"."cobros_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "acceso_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "medio" "text" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "periodo" "date" NOT NULL,
    "estado_cobro" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "referencia_externa" "text",
    "fecha_cobro" "date" DEFAULT CURRENT_DATE NOT NULL,
    "registrado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "url_accion" "text",
    "codigo_cupon" "text",
    CONSTRAINT "cobros_intermediacion_estado_cobro_check" CHECK (("estado_cobro" = ANY (ARRAY['pendiente'::"text", 'exitoso'::"text", 'fallido'::"text"])))
);


ALTER TABLE "public"."cobros_intermediacion" OWNER TO "postgres";


COMMENT ON COLUMN "public"."cobros_intermediacion"."url_accion" IS 'Dirección del QR con el que el Cliente paga este período, en los rieles que la devuelven.';



COMMENT ON COLUMN "public"."cobros_intermediacion"."codigo_cupon" IS 'Código del cupón con el que el Cliente paga este período, en los rieles de cobranza en efectivo.';



CREATE TABLE IF NOT EXISTS "public"."codigos_al_telefono" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "uso" "text" NOT NULL,
    "telefono" "text" NOT NULL,
    "codigo_verificador" "text" NOT NULL,
    "codigo_expira_en" timestamp with time zone NOT NULL,
    "codigo_intentos" smallint DEFAULT 0 NOT NULL,
    "verificado_en" timestamp with time zone,
    "anulado_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."codigos_al_telefono" OWNER TO "postgres";


COMMENT ON TABLE "public"."codigos_al_telefono" IS 'El código corto que se le manda al teléfono de una persona. Se guarda el identificador de verificación del código, nunca el código. Lo escribe y lo lee únicamente el backend.';



COMMENT ON COLUMN "public"."codigos_al_telefono"."telefono" IS 'El número que se está verificando, que es al que se le manda el mensaje. No viaja a ninguna pantalla ni a ningún registro.';



COMMENT ON COLUMN "public"."codigos_al_telefono"."codigo_intentos" IS 'Cuántas veces se probó un código contra este pedido. Es la cuenta del acto, no la del código: pedir uno nuevo no la vuelve a cero. Un código vencido no gasta intento.';



CREATE TABLE IF NOT EXISTS "public"."codigos_de_presencia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "sujeto_tipo" "text" NOT NULL,
    "sujeto_id" "uuid" NOT NULL,
    "codigo_verificador" "text" NOT NULL,
    "expira_en" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "codigos_de_presencia_sujeto_tipo_check" CHECK (("sujeto_tipo" = ANY (ARRAY['cliente'::"text", 'asistente'::"text"])))
);


ALTER TABLE "public"."codigos_de_presencia" OWNER TO "postgres";


COMMENT ON TABLE "public"."codigos_de_presencia" IS 'El código de seis dígitos que una persona muestra en la pantalla de su teléfono para que el Asistente que llega compruebe que está en la casa (pendiente #113, Plan A). Se guarda su identificador de verificación y vence solo a los segundos que configuró la Prestadora.';



COMMENT ON COLUMN "public"."codigos_de_presencia"."sujeto_tipo" IS 'Quién muestra el código: cliente (cualquiera de las personas autorizadas) o asistente (el que se va, cuando hay relevo). El Paciente no tiene cuenta en el producto y por eso no figura acá.';



COMMENT ON COLUMN "public"."codigos_de_presencia"."codigo_verificador" IS 'sha256 del código. El código en claro no se guarda en ningún lado: sólo viaja a la pantalla que lo muestra y de ahí a la que lo lee.';



CREATE TABLE IF NOT EXISTS "public"."conceptos_liquidacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "signo" "text" NOT NULL,
    "unidad" "text" NOT NULL,
    "origen_valor" "text" DEFAULT 'propio'::"text" NOT NULL,
    "valor" numeric(14,4),
    "escala_tipo" "text",
    "moneda" "public"."moneda_iso",
    "activo" boolean DEFAULT true NOT NULL,
    "orden" smallint DEFAULT 100 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "conceptos_liquidacion_moneda_cuando_es_plata" CHECK (((("unidad" <> 'porcentaje'::"text") AND ("origen_valor" = 'propio'::"text")) = ("moneda" IS NOT NULL))),
    CONSTRAINT "conceptos_liquidacion_origen_valor_check" CHECK (("origen_valor" = ANY (ARRAY['propio'::"text", 'escala_legal'::"text"]))),
    CONSTRAINT "conceptos_liquidacion_signo_check" CHECK (("signo" = ANY (ARRAY['suma'::"text", 'resta'::"text"]))),
    CONSTRAINT "conceptos_liquidacion_unidad_check" CHECK (("unidad" = ANY (ARRAY['monto_fijo_mensual'::"text", 'porcentaje'::"text", 'monto_por_hora'::"text"]))),
    CONSTRAINT "conceptos_liquidacion_valor_segun_origen" CHECK (((("origen_valor" = 'propio'::"text") AND ("valor" IS NOT NULL) AND ("escala_tipo" IS NULL)) OR (("origen_valor" = 'escala_legal'::"text") AND ("escala_tipo" IS NOT NULL) AND ("valor" IS NULL))))
);


ALTER TABLE "public"."conceptos_liquidacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."conceptos_liquidacion" IS 'Los conceptos de suma y resta que cada Prestadora aplica al pago de sus Asistentes. Ninguno viene cargado de fábrica.';



CREATE TABLE IF NOT EXISTS "public"."condiciones_comerciales_servicio" (
    "servicio_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "contratante_persona_id" "uuid",
    "pagador_tipo" "text",
    "pagador_persona_id" "uuid",
    "dias_hasta_el_vencimiento" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "condiciones_comerciales_pagador_conocido" CHECK ((("pagador_tipo" IS NULL) OR ("pagador_tipo" = ANY (ARRAY['cliente'::"text", 'obra_social'::"text", 'otro'::"text"])))),
    CONSTRAINT "condiciones_comerciales_plazo_razonable" CHECK ((("dias_hasta_el_vencimiento" IS NULL) OR (("dias_hasta_el_vencimiento" >= 0) AND ("dias_hasta_el_vencimiento" <= 365))))
);


ALTER TABLE "public"."condiciones_comerciales_servicio" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."conexiones_con_software_externo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "clase" "text" NOT NULL,
    "software" "text" NOT NULL,
    "credencial_secret_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "conexiones_con_software_externo_clase_check" CHECK (("clase" = ANY (ARRAY['facturacion'::"text", 'creditos_y_cobranzas'::"text"])))
);


ALTER TABLE "public"."conexiones_con_software_externo" OWNER TO "postgres";


COMMENT ON TABLE "public"."conexiones_con_software_externo" IS 'Cual es el software de facturacion y cual el de creditos y cobranzas de cada Prestadora, y la referencia a la caja fuerte con la credencial con la que se entra. Aca no se factura ni se cobra: esto dice unicamente con quien habla.';



COMMENT ON COLUMN "public"."conexiones_con_software_externo"."credencial_secret_id" IS 'Referencia a vault.secrets con la credencial con la que se entra a ese software. El texto nunca se guarda aca y nunca sale hacia el navegador.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_alarmas_tomadas" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_alarmas_tomadas_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_alarmas_tomadas" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_alarmas_tomadas" IS 'Cuanto dura hacerse cargo de una alarma. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/alarmasTomadas.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_alertas_ia" (
    "prestadora_id" "uuid" NOT NULL,
    "palabras_clave" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reportes_a_analizar" integer DEFAULT 7 NOT NULL,
    "roja_avisa_cliente" boolean DEFAULT true NOT NULL,
    "amarilla_avisa_cliente" boolean DEFAULT false NOT NULL,
    "amarilla_avisa_coordinador" boolean DEFAULT true NOT NULL,
    CONSTRAINT "configuracion_alertas_ia_reportes_a_analizar_check" CHECK ((("reportes_a_analizar" >= 1) AND ("reportes_a_analizar" <= 30)))
);


ALTER TABLE "public"."configuracion_alertas_ia" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_alertas_ia" IS 'Cómo revisa esta Prestadora los reportes de sus Pacientes con inteligencia artificial: qué palabras adelantan la revisión, cuánto material mira y a quién le avisa según lo que encuentra. Sin fila, valen los valores de fábrica que están en backend/src/routes/panelConfiguracion.js.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."palabras_clave" IS 'Palabras que, si aparecen en un reporte, disparan la revisión en el momento en vez de esperar al horario de siempre (por ejemplo: caída, sangrado, no responde). Las lee backend/src/routes/appAsistentes.js al recibir el reporte.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."reportes_a_analizar" IS 'Cuántos de los últimos reportes de ese Paciente mira la revisión. De fábrica, 7. Cuantos más mire, más contexto tiene y más cuesta cada revisión.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."roja_avisa_cliente" IS 'Si una alerta roja —lo urgente— también le llega al Cliente del Paciente. De fábrica, sí. Al Coordinador le llega siempre, eso no se configura.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."amarilla_avisa_cliente" IS 'Si una alerta amarilla —lo que conviene mirar, sin urgencia— también le llega al Cliente. De fábrica, no: la amarilla es material de trabajo de la Prestadora, no una noticia para dar.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."amarilla_avisa_coordinador" IS 'Si una alerta amarilla le llega al Coordinador. De fábrica, sí. Se puede apagar en una Prestadora que prefiera revisarlas por pantalla en vez de recibirlas de a una.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_ausencia_automatica" (
    "prestadora_id" "uuid" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "minutos_tolerancia_checkin" integer DEFAULT 15 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metros_tolerancia_checkin" integer DEFAULT 150 NOT NULL,
    "segundos_codigo_en_pantalla" integer DEFAULT 30 NOT NULL,
    CONSTRAINT "segundos_codigo_en_pantalla_razonable" CHECK ((("segundos_codigo_en_pantalla" >= 10) AND ("segundos_codigo_en_pantalla" <= 300)))
);


ALTER TABLE "public"."configuracion_ausencia_automatica" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_ausencia_automatica"."segundos_codigo_en_pantalla" IS 'Cada cuántos segundos se renueva el código que el Cliente —o el Asistente que se va— muestra en la pantalla de su teléfono para que lo lea el Asistente que llega. Decisión de cada Prestadora.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_ausencias" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_ausencias_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_ausencias" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_ausencias" IS 'Con cuanta anticipacion sobre el primer turno afectado una ausencia se considera avisada con tiempo, y cada cuanto se insiste. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/avisoDeAusencia.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_aviso_cese_asistente" (
    "prestadora_id" "uuid" NOT NULL,
    "horas_plazo_aviso_verbal" smallint DEFAULT 24 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activo" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."configuracion_aviso_cese_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_aviso_guardia_sin_cubrir" (
    "prestadora_id" "uuid" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "horas_antes" smallint DEFAULT 48 NOT NULL,
    "horas_entre_avisos" smallint DEFAULT 12 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_aviso_guardia_sin_cubrir_horas_antes_check" CHECK ((("horas_antes" > 0) AND ("horas_antes" <= 720))),
    CONSTRAINT "configuracion_aviso_guardia_sin_cubrir_horas_entre_avisos_check" CHECK ((("horas_entre_avisos" > 0) AND ("horas_entre_avisos" <= 720)))
);


ALTER TABLE "public"."configuracion_aviso_guardia_sin_cubrir" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_aviso_guardia_sin_cubrir" IS 'Cuándo avisarle al Coordinador que una guardia próxima sigue sin Asistente. Una fila por Prestadora; sin fila no se manda ningún aviso.';



COMMENT ON COLUMN "public"."configuracion_aviso_guardia_sin_cubrir"."horas_antes" IS 'Con cuánta anticipación avisar. El aviso arranca cuando faltan estas horas para que empiece la guardia.';



COMMENT ON COLUMN "public"."configuracion_aviso_guardia_sin_cubrir"."horas_entre_avisos" IS 'Cada cuánto repetir el aviso mientras el hueco siga abierto. Evita que el proceso, que corre cada 5 minutos, mande el mismo correo doce veces por hora.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_calculo_candidatos" (
    "prestadora_id" "uuid" NOT NULL,
    "perfil" "text" DEFAULT 'continuidad'::"text" NOT NULL,
    "pesos" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "topes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_calculo_candidatos_perfil_conocido" CHECK (("perfil" = ANY (ARRAY['continuidad'::"text", 'descanso'::"text", 'cercania'::"text"]))),
    CONSTRAINT "configuracion_calculo_candidatos_pesos_es_objeto" CHECK (("jsonb_typeof"("pesos") = 'object'::"text")),
    CONSTRAINT "configuracion_calculo_candidatos_topes_es_objeto" CHECK (("jsonb_typeof"("topes") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_calculo_candidatos" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_calculo_candidatos" IS 'Como ordena cada Prestadora la lista de quienes pueden cubrir un hueco: el perfil elegido y lo que corrio respecto de el. Los valores de fabrica y las tres formas armadas viven en panel/src/lib/perfilesDeCandidatos.js.';



COMMENT ON COLUMN "public"."configuracion_calculo_candidatos"."perfil" IS 'Identificador permanente de la forma armada. Se nombra por su funcion y no se renombra.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_cobro_intermediacion" (
    "prestadora_id" "uuid" NOT NULL,
    "dias_de_aviso_antes_del_cobro" integer DEFAULT 3 NOT NULL,
    "dias_de_gracia_por_cobro_rechazado" integer DEFAULT 7 NOT NULL,
    "dias_de_vida_del_cupon" integer DEFAULT 10 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_cobro_intermediacion_aviso_al_menos_un_dia" CHECK (("dias_de_aviso_antes_del_cobro" >= 1)),
    CONSTRAINT "configuracion_cobro_intermediacion_cupon_al_menos_un_dia" CHECK (("dias_de_vida_del_cupon" >= 1)),
    CONSTRAINT "configuracion_cobro_intermediacion_gracia_al_menos_un_dia" CHECK (("dias_de_gracia_por_cobro_rechazado" >= 1))
);


ALTER TABLE "public"."configuracion_cobro_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_cobro_intermediacion" IS 'Los plazos comerciales del cobro de Match, elegidos por cada Prestadora. Una fila por Prestadora, sembrada al darla de alta.';



COMMENT ON COLUMN "public"."configuracion_cobro_intermediacion"."dias_de_aviso_antes_del_cobro" IS 'Con cuántos días de anticipación se avisa el primer cobro que viene.';



COMMENT ON COLUMN "public"."configuracion_cobro_intermediacion"."dias_de_gracia_por_cobro_rechazado" IS 'Cuántos días se conserva el acceso, con reintentos, cuando un cobro no entra.';



COMMENT ON COLUMN "public"."configuracion_cobro_intermediacion"."dias_de_vida_del_cupon" IS 'Cuántos días vive el cupón de la red de cobranza desde que se emite.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_de_hce" (
    "prestadora_id" "uuid" NOT NULL,
    "restriccion_de_hce" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_de_hce" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_de_hce" IS 'Si rige la restricción de HCE: la información de salud de un paciente la ve sólo quien lo atiende. Sin renglón, rige.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_equipo_paciente" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_equipo_paciente_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_equipo_paciente" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_equipo_paciente" IS 'Con cuantos turnos y en que ventana de dias se entra solo al equipo de un Paciente. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/equipoDelPaciente.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_escalada_coordinador" (
    "prestadora_id" "uuid" NOT NULL,
    "coordinador_backup_id" "uuid",
    "minutos_antes_backup" integer DEFAULT 15 NOT NULL,
    "umbrales_premura" "jsonb" DEFAULT '[{"maximo_minutos": 60, "intervalo_minutos": 10}, {"maximo_minutos": 240, "intervalo_minutos": 30}, {"maximo_minutos": null, "intervalo_minutos": 60}]'::"jsonb" NOT NULL,
    "fase_automatica_activa" boolean DEFAULT false NOT NULL,
    "minutos_antes_fase_automatica" integer DEFAULT 120 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "minutos_gracia_cierre_guardia" integer DEFAULT 15 NOT NULL,
    "horas_antes_aviso_grave_sin_cerrar" integer DEFAULT 4 NOT NULL,
    "minutos_antes_todos_los_coordinadores" integer DEFAULT 45,
    "minutos_antes_administracion" integer DEFAULT 90,
    "minutos_insistencia_emergencia" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "horas_antes_aviso_grave_sin_cerrar_razonable" CHECK ((("horas_antes_aviso_grave_sin_cerrar" > 0) AND ("horas_antes_aviso_grave_sin_cerrar" <= 72))),
    CONSTRAINT "minutos_gracia_cierre_guardia_razonable" CHECK ((("minutos_gracia_cierre_guardia" > 0) AND ("minutos_gracia_cierre_guardia" <= 1440))),
    CONSTRAINT "minutos_insistencia_emergencia_razonable" CHECK ((("minutos_insistencia_emergencia" >= 1) AND ("minutos_insistencia_emergencia" <= 10)))
);


ALTER TABLE "public"."configuracion_escalada_coordinador" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_escalada_coordinador"."horas_antes_aviso_grave_sin_cerrar" IS 'Cuántas horas después de vencido el plazo de cierre el aviso escala al evento guardia_sin_cerrar_grave, que tiene su propia lista de destinatarios. Sale una sola vez por guardia.';



COMMENT ON COLUMN "public"."configuracion_escalada_coordinador"."minutos_antes_todos_los_coordinadores" IS 'Minutos desde que empezo la alarma antes de avisarle a todos los Coordinadores. En nulo, ese escalon queda apagado.';



COMMENT ON COLUMN "public"."configuracion_escalada_coordinador"."minutos_antes_administracion" IS 'Minutos desde que empezo la alarma antes de avisarle a la administracion. En nulo, ese escalon queda apagado.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_escalada_relevo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nivel" integer NOT NULL,
    "minutos_demora" integer,
    "orden_prioridad" "text"[],
    "plantilla_mensaje" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_escalada_relevo" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_facturacion_clientes" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "secreto_del_aviso_secret_id" "uuid",
    "secreto_del_aviso_de_facturacion_secret_id" "uuid",
    CONSTRAINT "configuracion_facturacion_clientes_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_facturacion_clientes" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_facturacion_clientes" IS 'Como factura y como cobra esta Prestadora lo que no depende de un Cliente sola: el plazo de pago acordado y si el seguimiento de la cobranza es suyo o de otro software. Solo lo que corrio respecto de fabrica; los bordes viven en panel/src/lib/facturacionDeClientes.js.';



COMMENT ON COLUMN "public"."configuracion_facturacion_clientes"."secreto_del_aviso_secret_id" IS 'Referencia a vault.secrets con el secreto con el que el software de creditos y cobranzas de esta Prestadora firma sus avisos de restriccion. El texto nunca se guarda aca. Vacio quiere decir que no entra ningun aviso.';



COMMENT ON COLUMN "public"."configuracion_facturacion_clientes"."secreto_del_aviso_de_facturacion_secret_id" IS 'Referencia a vault.secrets con el secreto con el que el software de facturacion de esta Prestadora firma lo que emitio. El texto nunca se guarda aca. Vacio quiere decir que no entra ningun aviso.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_funciones_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "funcion_clave" "text" NOT NULL,
    "activa" boolean DEFAULT false NOT NULL,
    "advertida_en" timestamp with time zone,
    "advertida_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_funciones_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_funciones_intermediacion" IS 'Qué funciones de riesgo legal de Match tiene encendidas cada Prestadora. Sin fila, apagada. Nada acá bloquea nada: encender muestra el aviso de la jurisdicción, si lo hay, y lo deja auditado.';



COMMENT ON COLUMN "public"."configuracion_funciones_intermediacion"."advertida_en" IS 'Cuándo se mostró el último aviso legal al encender esta función. El historial completo, con el texto mostrado, está en auditoria_advertencias_legales.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_incidentes_turno_sin_cubrir" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_incidentes_turno_sin_cubrir_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_incidentes_turno_sin_cubrir" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_incidentes_turno_sin_cubrir" IS 'A cuantas horas de empezar un turno sin nadie abre un incidente, y cada cuanto se insiste. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/incidenteTurnoSinCubrir.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_medicacion" (
    "prestadora_id" "uuid" NOT NULL,
    "pide_firma_del_cliente" boolean DEFAULT true NOT NULL,
    "actualizado_por" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_medicacion" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_mensaje_de_texto_prestadora" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "proveedor" "text",
    "remitente" "text",
    "token_secret_id" "uuid",
    "activo" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sin_proveedor_el_mensaje_de_texto_no_se_enciende" CHECK (((NOT "activo") OR ("proveedor" IS NOT NULL)))
);


ALTER TABLE "public"."configuracion_mensaje_de_texto_prestadora" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_mensaje_de_texto_prestadora" IS 'Con que proveedor manda mensajes de texto cada Prestadora. Sin fila no hay proveedor y la via no se puede elegir. La credencial vive en Vault; aca solo su puntero.';



COMMENT ON COLUMN "public"."configuracion_mensaje_de_texto_prestadora"."token_secret_id" IS 'Puntero al secreto de Vault. Nunca la credencial en texto plano, igual que el token de WhatsApp.';



COMMENT ON COLUMN "public"."configuracion_mensaje_de_texto_prestadora"."activo" IS 'Si la via esta encendida en esta Prestadora. Sin proveedor no puede estar en verdadero.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_notificaciones" (
    "evento" "text" NOT NULL,
    "descripcion" "text" NOT NULL,
    "emails" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "whatsapp_activo" boolean DEFAULT false NOT NULL,
    "notificar_cliente" boolean DEFAULT false NOT NULL,
    "plantilla_whatsapp_id" "uuid",
    "mensaje_de_texto_activo" boolean DEFAULT false NOT NULL
);


ALTER TABLE "public"."configuracion_notificaciones" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_notificaciones"."descripcion" IS 'Texto histórico, en español, de cuando la lista de avisos vivía en esta tabla. El Panel ya no lo muestra: el nombre y la explicación de cada aviso salen traducidos de panel/src/i18n/translations.js, y la lista de avisos que existen es la de backend/src/utils/catalogoAvisos.js. Se conserva como respaldo por si llegara una fila de un aviso que el catálogo no conoce.';



COMMENT ON COLUMN "public"."configuracion_notificaciones"."plantilla_whatsapp_id" IS 'Con qué plantilla aprobada sale este aviso por WhatsApp. Nulo mientras la Prestadora no eligió ninguna, y entonces el aviso sale por correo.';



COMMENT ON COLUMN "public"."configuracion_notificaciones"."mensaje_de_texto_activo" IS 'Si este aviso sale tambien por mensaje de texto. Respaldo de WhatsApp: se intenta despues de WhatsApp y antes del correo. Encenderla no alcanza si la Prestadora no tiene proveedor cargado.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_pago_asistentes" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "frecuencia_pago" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "configuracion_pago_asistentes_frecuencia_es_objeto" CHECK (("jsonb_typeof"("frecuencia_pago") = 'object'::"text")),
    CONSTRAINT "configuracion_pago_asistentes_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_pago_asistentes" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_pago_asistentes" IS 'Como paga esta Prestadora lo que no depende de una persona sola. Solo lo que corrio respecto de fabrica; los valores de fabrica y los bordes viven en panel/src/lib/formaDePago.js.';



COMMENT ON COLUMN "public"."configuracion_pago_asistentes"."frecuencia_pago" IS 'Cada cuánto cobran los Asistentes de esta Prestadora. Sólo lo corrido respecto de fábrica; vacío es fábrica.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_prestadora" (
    "prestadora_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "telefono" "text",
    "whatsapp_numero" "text",
    "email" "text",
    "dominio" "text",
    "zona_cobertura_texto" "text",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "telefono_emergencias" "text"
);


ALTER TABLE "public"."configuracion_prestadora" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_prestadora"."dominio" IS 'La direccion por la que entra esta Prestadora. Se le asigna sola al darla de alta, es unica y no cambia nunca.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_reclutamiento" (
    "prestadora_id" "uuid" NOT NULL,
    "responsable_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_reclutamiento" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_referencias_laborales" (
    "prestadora_id" "uuid" NOT NULL,
    "minimo_verificadas" smallint DEFAULT 2 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_referencias_laborales_minimo_razonable" CHECK ((("minimo_verificadas" >= 0) AND ("minimo_verificadas" <= 5)))
);


ALTER TABLE "public"."configuracion_referencias_laborales" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_referencias_laborales" IS 'Cuántas referencias laborales verificadas espera cada Prestadora antes de incorporar a un Asistente. Sin fila, no se espera ninguna y no se avisa nada.';



COMMENT ON COLUMN "public"."configuracion_referencias_laborales"."minimo_verificadas" IS 'El tope de cinco es el mismo del formulario de postulación: no se puede exigir más de lo que se puede cargar. En cero, el aviso no aparece nunca.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_respuesta_automatica_whatsapp" (
    "prestadora_id" "uuid" NOT NULL,
    "horas_sin_mensajes_para_terminar" smallint DEFAULT 24 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "las_horas_estan_en_rango" CHECK ((("horas_sin_mensajes_para_terminar" > 0) AND ("horas_sin_mensajes_para_terminar" <= 720)))
);


ALTER TABLE "public"."configuracion_respuesta_automatica_whatsapp" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_respuesta_automatica_whatsapp" IS 'Cómo se comporta el bot de WhatsApp de cada Prestadora. Sin fila, el bot no vuelve a contestar donde ya contestó una persona.';



COMMENT ON COLUMN "public"."configuracion_respuesta_automatica_whatsapp"."horas_sin_mensajes_para_terminar" IS 'Cuántas horas sin mensajes dan por terminada una conversación que atendió una persona. Pasadas, el bot vuelve a contestar.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_visibilidad_app" (
    "prestadora_id" "uuid" NOT NULL,
    "clave" "text" NOT NULL,
    "visible" boolean NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_visibilidad_app" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_visibilidad_app" IS 'Qué muestran las aplicaciones del Cliente y del Asistente en cada Prestadora. Solo guarda lo que se cambió respecto del valor de fábrica; la lista de claves posibles vive en backend/src/utils/catalogoVisibilidad.js.';



COMMENT ON COLUMN "public"."configuracion_visibilidad_app"."clave" IS 'Identificador permanente de la cosa que se prende o se apaga. Nombrado por su función, nunca por la pantalla donde aparece hoy, y no se renombra jamás (CLAUDE.md §7 regla 13).';



CREATE TABLE IF NOT EXISTS "public"."configuracion_whatsapp_prestadora" (
    "prestadora_id" "uuid" NOT NULL,
    "activo" boolean DEFAULT false NOT NULL,
    "numero_telefono" "text",
    "waba_id" "text",
    "phone_number_id" "text",
    "token_secret_id" "uuid",
    "verificado_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "app_secret_secret_id" "uuid",
    "verify_token_secret_id" "uuid"
);


ALTER TABLE "public"."configuracion_whatsapp_prestadora" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_whatsapp_prestadora"."app_secret_secret_id" IS 'Referencia a vault.secrets con el secreto de la aplicación de Meta, con el que se comprueba la firma X-Hub-Signature-256 de cada aviso entrante. El texto nunca se guarda acá. Pendiente #165.';



COMMENT ON COLUMN "public"."configuracion_whatsapp_prestadora"."verify_token_secret_id" IS 'Referencia a vault.secrets con el token que Meta devuelve en el saludo inicial de la dirección de esta Prestadora. Uno por Prestadora, nunca uno solo para todo el producto. El texto nunca se guarda acá. Pendiente #165.';



CREATE TABLE IF NOT EXISTS "public"."consentimientos_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "clave" "text" NOT NULL,
    "texto_consentimiento_id" "uuid" NOT NULL,
    "version_mostrada" integer NOT NULL,
    "idioma_mostrado" "text" NOT NULL,
    "texto_mostrado" "text" NOT NULL,
    "decision" "text" NOT NULL,
    "decidido_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "retirado_at" timestamp with time zone,
    "motivo_retiro" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "consentimientos_asistente_decision_check" CHECK (("decision" = ANY (ARRAY['otorgado'::"text", 'rechazado'::"text"]))),
    CONSTRAINT "consentimientos_asistente_retiro_coherente" CHECK ((("retirado_at" IS NULL) OR ("decision" = 'otorgado'::"text")))
);


ALTER TABLE "public"."consentimientos_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."consentimientos_medicacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "indicacion_id" "uuid" NOT NULL,
    "documento_texto" "text" NOT NULL,
    "documento_verificador" "text" NOT NULL,
    "documento_idioma" "text" NOT NULL,
    "estado" "text" DEFAULT 'pendiente_firma'::"text" NOT NULL,
    "cerrado_como" "text",
    "cerrado_en" timestamp with time zone,
    "cerrado_desde" "text",
    "archivo_firmado_url" "text",
    "firmante_persona_id" "uuid",
    "firmante_nombre" "text",
    "cargado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "consentimientos_medicacion_cerrado_como_check" CHECK ((("cerrado_como" IS NULL) OR ("cerrado_como" = ANY (ARRAY['documento_firmado'::"text", 'confirmado_en_la_app'::"text"])))),
    CONSTRAINT "consentimientos_medicacion_check" CHECK ((("estado" = 'cerrado'::"text") = (("cerrado_como" IS NOT NULL) AND ("cerrado_en" IS NOT NULL)))),
    CONSTRAINT "consentimientos_medicacion_check1" CHECK (((("firmante_persona_id" IS NULL) AND ("firmante_nombre" IS NULL)) OR (("firmante_persona_id" IS NOT NULL) AND ("length"("btrim"("firmante_nombre")) > 0)))),
    CONSTRAINT "consentimientos_medicacion_documento_idioma_check" CHECK (("documento_idioma" = ANY (ARRAY['es-AR'::"text", 'en'::"text", 'pt-BR'::"text"]))),
    CONSTRAINT "consentimientos_medicacion_documento_texto_check" CHECK (("length"("btrim"("documento_texto")) > 0)),
    CONSTRAINT "consentimientos_medicacion_documento_verificador_check" CHECK (("length"("btrim"("documento_verificador")) > 0)),
    CONSTRAINT "consentimientos_medicacion_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente_firma'::"text", 'cerrado'::"text", 'anulado'::"text"])))
);


ALTER TABLE "public"."consentimientos_medicacion" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."consentimientos_paciente_solo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "guardia_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "quien_consintio" "text" NOT NULL,
    "cliente_id" "uuid",
    "medio" "text" NOT NULL,
    "desde_at" timestamp with time zone NOT NULL,
    "hasta_at" timestamp with time zone NOT NULL,
    "registrado_por" "uuid" NOT NULL,
    "registrado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "nota" "text",
    CONSTRAINT "consentimientos_paciente_solo_con_nombre" CHECK (("length"("btrim"("quien_consintio")) > 0)),
    CONSTRAINT "consentimientos_paciente_solo_medio_conocido" CHECK (("medio" = ANY (ARRAY['telefono'::"text", 'en_persona'::"text", 'mensaje'::"text", 'correo'::"text"]))),
    CONSTRAINT "consentimientos_paciente_solo_termina_despues" CHECK (("hasta_at" > "desde_at"))
);


ALTER TABLE "public"."consentimientos_paciente_solo" OWNER TO "postgres";


COMMENT ON TABLE "public"."consentimientos_paciente_solo" IS 'El Cliente supo y acepto que la persona atendida quedara sola durante un rato de este turno. Registra una conversacion que ya ocurrio; no cubre el turno ni lo cierra.';



COMMENT ON COLUMN "public"."consentimientos_paciente_solo"."quien_consintio" IS 'Nombre de la persona del Cliente con la que se hablo. La cuenta es de todas; quien dijo que si es una.';



COMMENT ON COLUMN "public"."consentimientos_paciente_solo"."hasta_at" IS 'Hasta cuando vale. Obligatorio: un consentimiento sin fin no es un consentimiento.';



COMMENT ON COLUMN "public"."consentimientos_paciente_solo"."nota" IS 'Lo que quedo de la conversacion. Nunca datos de salud de la persona atendida.';



CREATE TABLE IF NOT EXISTS "public"."consentimientos_pagador" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "pagador_persona_id" "uuid" NOT NULL,
    "pagador_nombre" "text" NOT NULL,
    "documento_texto" "text" NOT NULL,
    "documento_verificador" "text" NOT NULL,
    "documento_idioma" "text" NOT NULL,
    "estado" "text" DEFAULT 'pendiente_firma'::"text" NOT NULL,
    "cerrado_como" "text",
    "cerrado_en" timestamp with time zone,
    "cerrado_desde" "text",
    "archivo_firmado_url" "text",
    "cargado_por" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "firmante_persona_id" "uuid",
    "firmante_nombre" "text",
    "firmado_con_email" "text",
    "servicio_id" "uuid" NOT NULL,
    CONSTRAINT "consentimientos_pagador_cerrado_como_conocido" CHECK ((("cerrado_como" IS NULL) OR ("cerrado_como" = ANY (ARRAY['documento_firmado'::"text", 'confirmado_en_la_app'::"text", 'firmado_con_el_enlace'::"text"])))),
    CONSTRAINT "consentimientos_pagador_cierre_coherente" CHECK ((("estado" = 'cerrado'::"text") = (("cerrado_como" IS NOT NULL) AND ("cerrado_en" IS NOT NULL)))),
    CONSTRAINT "consentimientos_pagador_con_nombre" CHECK (("length"("btrim"("pagador_nombre")) > 0)),
    CONSTRAINT "consentimientos_pagador_estado_conocido" CHECK (("estado" = ANY (ARRAY['pendiente_firma'::"text", 'cerrado'::"text", 'anulado'::"text"]))),
    CONSTRAINT "consentimientos_pagador_firmante_entero" CHECK (((("firmante_persona_id" IS NULL) AND ("firmante_nombre" IS NULL)) OR (("firmante_persona_id" IS NOT NULL) AND ("length"("btrim"("firmante_nombre")) > 0))))
);


ALTER TABLE "public"."consentimientos_pagador" OWNER TO "postgres";


COMMENT ON TABLE "public"."consentimientos_pagador" IS 'Que el Pagador asumio la obligacion de pagar esta contratacion, y lo firmo. Sin una fila cerrada no hay Pagador definido.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."pagador_nombre" IS 'Como se llamaba el dia que firmo. El Legajo dice con quien quedo atado; esto, que fue lo que leyo.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."documento_verificador" IS 'Identificador de verificación del texto firmado. Si alguien le mueve una coma, deja de coincidir.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."cerrado_desde" IS 'Con que aparato se cerro. Nunca la direccion de red ni ningun otro dato que no haga falta.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."firmante_persona_id" IS 'El Apoderado que firmo por la entidad. Nulo cuando quien paga es una persona fisica y firma ella.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."firmante_nombre" IS 'Cómo se llamaba el Apoderado el día que firmó. Si mañana la entidad cambia de Apoderado, el documento sigue diciendo quién lo firmó.';



CREATE TABLE IF NOT EXISTS "public"."consultas_de_relevo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "incidente_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "rol" "text" NOT NULL,
    "consultado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "respuesta" "text",
    "minutos_que_indica" integer,
    "minutos_por_gps" integer,
    "respondido_at" timestamp with time zone,
    "avisado_del_cierre_at" timestamp with time zone,
    CONSTRAINT "consultas_de_relevo_check" CHECK ((("respuesta" IS DISTINCT FROM 'disponible'::"text") OR ("minutos_que_indica" IS NOT NULL))),
    CONSTRAINT "consultas_de_relevo_check1" CHECK ((("respuesta" IS NULL) = ("respondido_at" IS NULL))),
    CONSTRAINT "consultas_de_relevo_minutos_por_gps_check" CHECK (("minutos_por_gps" >= 0)),
    CONSTRAINT "consultas_de_relevo_minutos_que_indica_check" CHECK (("minutos_que_indica" >= 0)),
    CONSTRAINT "consultas_de_relevo_respuesta_check" CHECK (("respuesta" = ANY (ARRAY['disponible'::"text", 'no_disponible'::"text"]))),
    CONSTRAINT "consultas_de_relevo_rol_check" CHECK (("rol" = ANY (ARRAY['suplente'::"text", 'franquero'::"text", 'emergencia'::"text"])))
);


ALTER TABLE "public"."consultas_de_relevo" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."contactos_vistos_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "acceso_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."contactos_vistos_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."contactos_vistos_intermediacion" IS 'Qué Asistentes tiene ya abiertos un Cliente, y con qué acceso los pagó. Es lo que hace que el saldo del paquete se descuente de a un Asistente y no de a una mirada. docs/PRD_07_Modalidad_Match.md §3.3.';



CREATE TABLE IF NOT EXISTS "public"."contenidos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "titulo" "text" NOT NULL,
    "cuerpo" "text" NOT NULL,
    "enlace_url" "text",
    "orden" integer DEFAULT 0 NOT NULL,
    "publicado" boolean DEFAULT false NOT NULL,
    "creado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "destinatarios" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    CONSTRAINT "contenidos_cuerpo_con_texto" CHECK (("btrim"("cuerpo") <> ''::"text")),
    CONSTRAINT "contenidos_destinatarios_conocidos" CHECK (("destinatarios" <@ ARRAY['clientes'::"text", 'asistentes'::"text", 'personal'::"text"])),
    CONSTRAINT "contenidos_enlace_es_https" CHECK ((("enlace_url" IS NULL) OR ("enlace_url" ~ '^https://'::"text"))),
    CONSTRAINT "contenidos_publicado_con_destinatarios" CHECK (((NOT "publicado") OR ("cardinality"("destinatarios") > 0))),
    CONSTRAINT "contenidos_titulo_con_texto" CHECK (("btrim"("titulo") <> ''::"text"))
);


ALTER TABLE "public"."contenidos" OWNER TO "postgres";


COMMENT ON TABLE "public"."contenidos" IS 'La biblioteca que cada Prestadora escribe para su gente: Clientes, Asistentes y su propio personal. Sin siembra de fábrica y sin traducción: lo escribe la Prestadora.';



COMMENT ON COLUMN "public"."contenidos"."titulo" IS 'Título tal como lo escribió la Prestadora. No se traduce.';



COMMENT ON COLUMN "public"."contenidos"."cuerpo" IS 'Texto tal como lo escribió la Prestadora. No se traduce.';



COMMENT ON COLUMN "public"."contenidos"."enlace_url" IS 'Enlace opcional a material que la Prestadora ya publica en otro lado. Siempre https://. Acá no se guardan archivos.';



COMMENT ON COLUMN "public"."contenidos"."orden" IS 'En qué orden se muestran. A igual número, manda la fecha de creación.';



COMMENT ON COLUMN "public"."contenidos"."publicado" IS 'Si la ven sus destinatarios. Sin publicar, la pieza existe solamente para quien escribe contenidos.';



COMMENT ON COLUMN "public"."contenidos"."destinatarios" IS 'Quiénes ven la pieza una vez publicada: clientes, asistentes, personal. Uno o más.';



CREATE TABLE IF NOT EXISTS "public"."contenidos_archivos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "contenido_id" "uuid" NOT NULL,
    "ruta" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "tipo" "text" NOT NULL,
    "tamano" bigint NOT NULL,
    "subido_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "contenidos_archivos_nombre_con_texto" CHECK (("btrim"("nombre") <> ''::"text")),
    CONSTRAINT "contenidos_archivos_ruta_de_su_prestadora" CHECK ((("split_part"("ruta", '/'::"text", 1) = ("prestadora_id")::"text") AND ("split_part"("ruta", '/'::"text", 2) = ("contenido_id")::"text"))),
    CONSTRAINT "contenidos_archivos_tamano_permitido" CHECK ((("tamano" > 0) AND ("tamano" <= 10485760)))
);


ALTER TABLE "public"."contenidos_archivos" OWNER TO "postgres";


COMMENT ON TABLE "public"."contenidos_archivos" IS 'Los archivos que la Prestadora sube a una pieza de Contenidos. Los ve quien ve la pieza.';



COMMENT ON COLUMN "public"."contenidos_archivos"."ruta" IS 'Dónde quedó en el depósito contenidos-archivos: <prestadora>/<contenido>/<identificador>.<extensión>.';



COMMENT ON COLUMN "public"."contenidos_archivos"."nombre" IS 'El nombre con el que se subió, para mostrarlo y para la descarga.';



