CREATE TABLE IF NOT EXISTS "public"."entrevistas_postulacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "postulacion_id" bigint NOT NULL,
    "agendada_para" timestamp with time zone NOT NULL,
    "llave_publica" "text" NOT NULL,
    "sala_videollamada" "text",
    "estado" "text" DEFAULT 'agendada'::"text" NOT NULL,
    "agendada_por" "uuid" NOT NULL,
    "cerrada_por" "uuid",
    "cerrada_at" timestamp with time zone,
    "observaciones" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "entrevistador_id" "uuid" NOT NULL,
    CONSTRAINT "entrevistas_postulacion_estado_check" CHECK (("estado" = ANY (ARRAY['agendada'::"text", 'realizada'::"text", 'cancelada'::"text"]))),
    CONSTRAINT "entrevistas_postulacion_llave_publica_check" CHECK (("length"("llave_publica") >= 32))
);


ALTER TABLE "public"."entrevistas_postulacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."entrevistas_postulacion" IS 'La entrevista de la etapa 3 del Proceso de Incorporacion de Asistentes. Guarda cuando es, quien la agendo, como salio y la sala donde se hizo. El postulante entra con una llave, porque todavia no tiene cuenta.';



COMMENT ON COLUMN "public"."entrevistas_postulacion"."llave_publica" IS 'Lo que el postulante recibe por correo. No es la direccion de la sala: es una direccion del producto, que comprueba que sea la hora antes de dejar entrar.';



CREATE TABLE IF NOT EXISTS "public"."envios_de_correo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid",
    "aceptado" boolean NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."envios_de_correo" OWNER TO "postgres";


COMMENT ON TABLE "public"."envios_de_correo" IS 'Un renglón por correo despachado, para contar contra el tope del despachante. No guarda destinatario, asunto ni contenido: para contar no hacen falta, y un registro no lleva información sensible adentro.';



COMMENT ON COLUMN "public"."envios_de_correo"."prestadora_id" IS 'De qué Prestadora era el correo. Vacío cuando el envío no sale de ninguna en particular, como la recuperación de una cuenta. Si la Prestadora se borra, el renglón queda: la cuenta del mes ya pasó.';



COMMENT ON COLUMN "public"."envios_de_correo"."aceptado" IS 'Si el despachante lo tomó. Falso es un correo que no salió, y muchos seguidos son la señal de que se llegó al tope.';



CREATE TABLE IF NOT EXISTS "public"."equipo_servicio" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "servicio_id" "uuid" NOT NULL,
    "asistente_id" "uuid",
    "usuario_id" "uuid",
    "situacion" "text" NOT NULL,
    "cubre_francos" boolean DEFAULT false NOT NULL,
    "motivo" "text",
    "decidido_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "equipo_servicio_sacada_no_cubre_francos" CHECK ((NOT (("situacion" = 'sacada'::"text") AND "cubre_francos"))),
    CONSTRAINT "equipo_servicio_situacion_check" CHECK (("situacion" = ANY (ARRAY['sumada'::"text", 'sacada'::"text"]))),
    CONSTRAINT "equipo_servicio_una_persona" CHECK (("num_nonnulls"("asistente_id", "usuario_id") = 1))
);


ALTER TABLE "public"."equipo_servicio" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."equipos_conocidos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "marca_verificador" "text" NOT NULL,
    "primera_entrada_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ultima_entrada_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revocado_en" timestamp with time zone
);


ALTER TABLE "public"."equipos_conocidos" OWNER TO "postgres";


COMMENT ON TABLE "public"."equipos_conocidos" IS 'Los aparatos desde los que esta persona ya entró. Guarda el identificador de verificación de una marca que emitió el backend y que el navegador conserva, nunca nada del aparato ni de dónde se conecta.';



CREATE TABLE IF NOT EXISTS "public"."escalas_legales" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tipo" "text" NOT NULL,
    "categoria" "text",
    "valor" numeric(14,4) NOT NULL,
    "unidad" "text" NOT NULL,
    "vigencia_desde" "date" NOT NULL,
    "vigencia_hasta" "date",
    "fuente" "text",
    "cargado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "jurisdiccion" "text" NOT NULL,
    "moneda" "public"."moneda_iso",
    CONSTRAINT "escalas_legales_moneda_cuando_es_plata" CHECK ((("unidad" = ANY (ARRAY['monto_fijo_mensual'::"text", 'monto_por_hora'::"text"])) = ("moneda" IS NOT NULL))),
    CONSTRAINT "escalas_legales_unidad_check" CHECK (("unidad" = ANY (ARRAY['monto_fijo_mensual'::"text", 'porcentaje'::"text", 'dias'::"text", 'meses'::"text", 'horas'::"text", 'anios'::"text", 'monto_por_hora'::"text"])))
);


ALTER TABLE "public"."escalas_legales" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."escalones_de_alarma_avisados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "referencia_id" "uuid" NOT NULL,
    "escalon" "text" NOT NULL,
    "avisado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "destinatarios" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "escalones_de_alarma_avisados_escalon_conocido" CHECK (("escalon" = ANY (ARRAY['coordinador_respaldo'::"text", 'todos_los_coordinadores'::"text", 'administracion'::"text"]))),
    CONSTRAINT "escalones_de_alarma_avisados_tipo_conocido" CHECK (("tipo" = ANY (ARRAY['alerta_temprana_guardia'::"text", 'incidente_relevo'::"text", 'guardia_sin_cerrar'::"text", 'incidente_turno_sin_cubrir'::"text", 'emergencia_guardia'::"text"])))
);


ALTER TABLE "public"."escalones_de_alarma_avisados" OWNER TO "postgres";


COMMENT ON TABLE "public"."escalones_de_alarma_avisados" IS 'Que escalon de la escalada ya salio para cada alarma. Escalar no es volver a insistir: es ampliar quien se entera, y eso pasa una sola vez por escalon.';



COMMENT ON COLUMN "public"."escalones_de_alarma_avisados"."referencia_id" IS 'La fila alarmada. La tabla a la que apunta depende del tipo: no hay clave foranea posible.';



COMMENT ON COLUMN "public"."escalones_de_alarma_avisados"."destinatarios" IS 'A cuanta gente le salio. Cero es un problema de configuracion, no del aviso.';



CREATE TABLE IF NOT EXISTS "public"."especialidades" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
