    CONSTRAINT "mensajes_intermediacion_cuerpo_check" CHECK (("btrim"("cuerpo") <> ''::"text")),
    CONSTRAINT "mensajes_intermediacion_lado_check" CHECK (("lado" = ANY (ARRAY['cliente'::"text", 'asistente'::"text"])))
);


ALTER TABLE "public"."mensajes_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."mensajes_intermediacion" IS 'Los mensajes de un hilo de Match. Se guardan ya tapados: lo que no puede viajar en un mensaje no queda escrito en ningun lado, asi que llegar al dato por otra via no lo muestra.';



COMMENT ON COLUMN "public"."mensajes_intermediacion"."cuerpo" IS 'El texto ya tapado. Lo que las reglas de los mensajes alcanzan no se guarda: se tapa antes de escribirlo, del lado de la base.';



COMMENT ON COLUMN "public"."mensajes_intermediacion"."automatico" IS 'Lo escribio el producto, no una persona. El cuerpo es una clave de traduccion, no texto visible.';



COMMENT ON COLUMN "public"."mensajes_intermediacion"."regla_tapada" IS 'La clave de la primera regla que tapo algo en este mensaje, o nula si no se tapo nada. Es una clave, nunca el texto tapado.';



