    "verificada_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "referencias_laborales_asistente_resultado_conocido" CHECK (("resultado" = ANY (ARRAY['pendiente'::"text", 'verificada'::"text", 'no_responde'::"text", 'rechazada'::"text"]))),
    CONSTRAINT "referencias_laborales_asistente_verificada_tiene_firma" CHECK ((("resultado" = 'pendiente'::"text") OR ("verificada_en" IS NOT NULL)))
);


