CREATE OR REPLACE VIEW "public"."resoluciones_vigentes" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("prestadora_id", "tabla", "fila_id") "prestadora_id",
    "tabla",
    "fila_id",
    "id" AS "resolucion_id",
    "estado",
    "motivo_id",
    "detalle",
    "resuelto_por",
    "created_at"
   FROM "public"."resoluciones" "r"
  ORDER BY "prestadora_id", "tabla", "fila_id", "created_at" DESC, "secuencia" DESC;


ALTER VIEW "public"."resoluciones_vigentes" OWNER TO "postgres";


