    CONSTRAINT "la_aprobacion_dice_quien_la_firmo" CHECK ((("aprobada_at" IS NULL) = ("aprobada_por" IS NULL))),
    CONSTRAINT "la_respuesta_preparada_sale_del_producto_o_de_la_ia" CHECK (("origen" = ANY (ARRAY['prestadora'::"text", 'ia'::"text"]))),
    CONSTRAINT "la_respuesta_preparada_tiene_nombre" CHECK (("btrim"("nombre_interno") <> ''::"text")),
