);


ALTER TABLE "public"."tokens_recuperacion_clave" OWNER TO "postgres";


COMMENT ON TABLE "public"."tokens_recuperacion_clave" IS 'Los enlaces de un solo uso con los que alguien que perdió su clave elige una nueva. Los escribe y los lee únicamente el motor.';



CREATE TABLE IF NOT EXISTS "public"."uso_ia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
