SELECT id, prestadora_id, clave, i18n, admite_texto_propio, activo, created_at FROM jsonb_populate_recordset(NULL::"public"."mensajes_del_sistema", $datos$[{"id": "00039380-d9b1-4dfd-ad18-b725ec73177b", "i18n": {"en": "The service you were taking part in has been closed. For more information, please get in touch with your coordinator.", "es-AR": "Se cerró el Servicio en el que participaba. Para más información, puede comunicarse con su Coordinador.", "pt-BR": "O Serviço do qual participava foi encerrado. Para mais informações, pode entrar em contato com o seu Coordenador."}, "clave": "cese_de_servicio.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "00e04773-18d9-47da-a399-9b346496ffb8", "i18n": {"en": "{{documento}} has been approved.", "es-AR": "{{documento}} quedó aprobado.", "pt-BR": "{{documento}} foi aprovado."}, "clave": "documento_aprobado.cuerpo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "016196ad-c7d7-40e3-9c39-2bede64b75cf", "i18n": {"en": "The relief has still not arrived after {{minutos}} minutes.", "es-AR": "El relevo sigue sin llegar hace {{minutos}} minutos.", "pt-BR": "A rendição continua sem chegar há {{minutos}} minutos."}, "clave": "incidente_relevo_respaldo.demora", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "0248c1cc-3f57-49c1-aac2-17702a27f64b", "i18n": {"en": "A shift has been assigned on {{fecha}} at {{horaInicio}}.", "es-AR": "Hay una guardia asignada el {{fecha}} a las {{horaInicio}}.", "pt-BR": "Há um plantão atribuído no dia {{fecha}} às {{horaInicio}}."}, "clave": "guardia_asignada.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "02a51ae7-9c54-4a5d-b7f1-9090cef56194", "i18n": {"en": "Source: {{origen}}. Reason: {{motivo}}. Unresolved for {{minutos}} minute.", "es-AR": "Origen: {{origen}}. Motivo: {{motivo}}. Sin resolver hace {{minutos}} minuto.", "pt-BR": "Origem: {{origen}}. Motivo: {{motivo}}. Sem resolver há {{minutos}} minuto."}, "clave": "alerta_temprana_sin_resolver.detalle_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "06ceeb6e-06d2-4b98-a230-271b073fe981", "i18n": {"en": "It starts in {{horas}} h.", "es-AR": "Empieza en {{horas}} h.", "pt-BR": "Começa em {{horas}} h."}, "clave": "comun.empieza_en", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "08019f70-282b-4e06-af84-7beb95acaf81", "i18n": {"en": "{{asistente}} will be away from {{fechaInicio}}.", "es-AR": "{{asistente}} no va a estar desde el {{fechaInicio}}.", "pt-BR": "{{asistente}} não vai estar de {{fechaInicio}}."}, "clave": "comun.ausencia_desde", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "084d3d89-95fc-4333-9a07-dcef1dada4dd", "i18n": {"en": "The shift still has nobody assigned.", "es-AR": "La guardia sigue sin nadie asignado.", "pt-BR": "O plantão continua sem ninguém atribuído."}, "clave": "incidente_relevo_fase_automatica.sigue_sin_nadie", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "08d90b66-4827-433d-9df5-19a2672cd2cc", "i18n": {"en": "Not uploaded", "es-AR": "Falta cargar", "pt-BR": "Falta enviar"}, "clave": "apoderado.estado_falta", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "0c766061-11d4-42b5-b838-cc01ea780d28", "i18n": {"en": "Signature", "es-AR": "Firma", "pt-BR": "Assinatura"}, "clave": "pie_de_firmas.firma", "activo": true, "created_at": "2026-11-08T19:27:12.397247+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "0ef87475-10f7-4e0f-8544-5baeb8b1492d", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, will be covered by {{nuevo}}.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, la hace {{nuevo}}.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, será feito por {{nuevo}}."}, "clave": "cambio_de_asistente_cliente.cuerpo_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "11cb3e52-702b-401b-a6ab-ebbcf2d4de4b", "i18n": {"en": "Returned with notes", "es-AR": "Observado", "pt-BR": "Com observação"}, "clave": "apoderado.estado_observado", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1336e58d-4ac1-4bb4-b459-64642421bec5", "i18n": {"en": "New message from the coordinator", "es-AR": "Nuevo mensaje del Coordinador", "pt-BR": "Nova mensagem do Coordenador"}, "clave": "mensaje_del_coordinador.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "137f5735-a16e-4ef1-9404-8043c9f6545f", "i18n": {"en": "The link expires in {{dias}} days. If you were not expecting this email, you can ignore it.", "es-AR": "El enlace vence en {{dias}} días. Si no esperaba este correo, puede ignorarlo.", "pt-BR": "O link expira em {{dias}} dias. Se este e-mail não era esperado, pode ser ignorado."}, "clave": "activacion_cuenta.pie_de_aviso", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "160830ae-284d-466d-80b6-69402fd56699", "i18n": {"en": "The relief has still not arrived after {{minutos}} minutes.", "es-AR": "El relevo sigue sin llegar hace {{minutos}} minutos.", "pt-BR": "A rendição continua sem chegar há {{minutos}} minutos."}, "clave": "incidente_relevo_sin_resolver.demora", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "16397db5-c462-4eb9-ae67-369598723fa7", "i18n": {"en": "The search for someone to cover the shift has started", "es-AR": "Se salió a buscar quién cubra la guardia", "pt-BR": "Saiu-se à procura de quem cubra o plantão"}, "clave": "incidente_relevo_fase_automatica.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "16f56c2b-dec0-4ab4-b728-ec8287e55ac5", "i18n": {"en": "Place and date", "es-AR": "Lugar y fecha", "pt-BR": "Local e data"}, "clave": "pie_de_firmas.fecha", "activo": true, "created_at": "2026-11-08T19:27:12.397247+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "183edcf0-0182-4ae0-8574-2ed4bcaa233b", "i18n": {"en": "Replacement assigned", "es-AR": "Reemplazo asignado", "pt-BR": "Substituição atribuída"}, "clave": "reemplazo_para_responder.titulo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "184e6945-ac3c-47ac-a8af-12d2f7730281", "i18n": {"en": "Shift with nobody: little time left before it starts", "es-AR": "Guardia sin nadie: queda poco para que empiece", "pt-BR": "Plantão sem ninguém: falta pouco para começar"}, "clave": "incidente_turno_sin_cubrir.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "18f50c16-dae5-498a-b355-916324fbcdc4", "i18n": {"en": "Hi {{nombre}},", "es-AR": "Hola {{nombre}},", "pt-BR": "Olá {{nombre}},"}, "clave": "comun.saludo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "1946f25b-2a71-4615-88cb-63cca2cdd37e", "i18n": {"en": "You have a replacement assigned starting {{desde}}. Accept or decline the offer.", "es-AR": "Tiene asignado un reemplazo a partir del {{desde}}. Acepte o rechace la propuesta.", "pt-BR": "Você tem uma substituição atribuída a partir do dia {{desde}}. Aceite ou recuse a proposta."}, "clave": "reemplazo_para_responder.cuerpo_sin_fin", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "19d8381e-bf61-40b3-a438-0c28dda8a70a", "i18n": {"en": "Last name", "es-AR": "Apellido", "pt-BR": "Sobrenome"}, "clave": "apoderado.apellido", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "19df8b05-96bc-483a-9184-a10f354c3575", "i18n": {"en": "The period of {{dias}} day expired and {{nombre}} did not accept the recording of their location during the shift.", "es-AR": "Venció el plazo de {{dias}} día y {{nombre}} no aceptó el registro de su ubicación durante el turno de guardia.", "pt-BR": "Venceu o prazo de {{dias}} dia e {{nombre}} não aceitou o registro da sua localização durante o turno de plantão."}, "clave": "plazo_ubicacion_sin_aceptar.texto_uno", "activo": true, "created_at": "2026-10-22T06:06:30.781747+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1a9d8279-6ef4-4634-86bc-0cf519542215", "i18n": {"en": "Choose a new password", "es-AR": "Elegir una clave nueva", "pt-BR": "Escolher uma senha nova"}, "clave": "recuperacion_clave.boton", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1b4418db-6674-4946-a6f7-09762272e475", "i18n": {"en": "minute", "es-AR": "minuto", "pt-BR": "minuto"}, "clave": "comun.minutos_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "1cfd8779-db8c-4b29-85b7-1615535d37cc", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, for {{pacientes}} is still open several hours after its closing time. If you have any questions, you can contact your coordinator.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, para {{pacientes}} sigue figurando abierta varias horas después de su hora de cierre. Ante cualquier duda, puede comunicarse con su Coordinador.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, para {{pacientes}} continua aberto várias horas depois da hora de encerramento. Em caso de dúvida, pode entrar em contato com o seu Coordenador."}, "clave": "guardia_sin_cerrar_grave_cliente.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1db4b153-dc6c-4164-8674-0202c0dc1c69", "i18n": {"en": "A care worker with no name on file", "es-AR": "un Asistente sin nombre cargado", "pt-BR": "um Assistente sem nome cadastrado"}, "clave": "cambio_de_asistente.asistente_sin_nombre_encabezando", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1e577580-9257-45d5-b8a4-87bae98b8ef2", "i18n": {"en": "the start time came with no departure recorded, no delay reported and no arrival logged", "es-AR": "llegó la hora de inicio sin marca de salida, sin aviso de demora y sin llegada registrada", "pt-BR": "chegou o horário de início sem registro de saída, sem aviso de atraso e sem chegada registrada"}, "clave": "origen_de_alerta.sin_aviso_ni_salida", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1e9669a2-d1fa-4cb5-a25c-65c71f992313", "i18n": {"en": "Return with notes", "es-AR": "Observar", "pt-BR": "Observar"}, "clave": "apoderado.observar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1ec14283-6e6c-49a1-a057-e556842b59ef", "i18n": {"en": "Deletion of the {{anio}} access record in {{dias}} days", "es-AR": "Borrado del registro de accesos de {{anio}} en {{dias}} días", "pt-BR": "Exclusão do registro de acessos de {{anio}} em {{dias}} dias"}, "clave": "borrado_del_registro_de_accesos_notificacion.asunto", "activo": true, "created_at": "2026-11-10T23:51:19.634456+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "1f43cfab-d632-4e27-8a60-224e81875a9d", "i18n": {"en": "DNI", "es-AR": "DNI", "pt-BR": "DNI"}, "clave": "pie_de_firmas.dni", "activo": true, "created_at": "2026-11-08T19:27:12.397247+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1f5d72a5-cdee-4199-a1e0-08dba2fd7caf", "i18n": {"en": "These care workers have their {{etiqueta}} expired or expiring within {{dias}} day:", "es-AR": "Estos Asistentes tienen {{etiqueta}} vencido o por vencer dentro de {{dias}} día:", "pt-BR": "Estes Assistentes têm {{etiqueta}} vencido ou a vencer dentro de {{dias}} dia:"}, "clave": "vencimiento_documentos.encabezado_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1f950474-5792-4e6e-8f4f-4d356e64c354", "i18n": {"en": "The family member is still to be told, and that decision is yours.", "es-AR": "Queda por avisarle al familiar, y esa decisión es suya.", "pt-BR": "Falta avisar o familiar, e essa decisão é sua."}, "clave": "incidente_relevo_fase_automatica.queda_el_familiar", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1f994393-0a2d-4011-83f5-44cb6f4ccda6", "i18n": {"en": "It also leaves {{otras}} more shifts with nobody.", "es-AR": "Además deja otras {{otras}} guardias sin nadie.", "pt-BR": "Além disso, deixa outros {{otras}} plantões sem ninguém."}, "clave": "ausencia_de_golpe.ademas_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "1fd2c73e-949b-4d95-8ad0-d0707725a3ff", "i18n": {"en": "and", "es-AR": "y", "pt-BR": "e"}, "clave": "comun.conjuncion", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "22245303-42af-4559-8a60-5e1a62f74b35", "i18n": {"en": "Unresolved for more than {{minutosUmbral}} minute.", "es-AR": "Sin resolver hace más de {{minutosUmbral}} minuto.", "pt-BR": "Sem resolver há mais de {{minutosUmbral}} minuto."}, "clave": "incidente_relevo_fase_automatica.sin_resolver_desde_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "22e91328-6ad5-443c-acce-df14f1096022", "i18n": {"en": "phone call logged by the care provider", "es-AR": "aviso telefónico registrado por la Prestadora", "pt-BR": "aviso por telefone registrado pela Prestadora"}, "clave": "origen_de_alerta.aviso_telefonico", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "23338099-d49d-4f8e-b38f-cfe39587efd3", "i18n": {"en": "This is reminder number {{veces}} for this same shift.", "es-AR": "Es el recordatorio número {{veces}} de esta misma guardia.", "pt-BR": "É o lembrete número {{veces}} deste mesmo plantão."}, "clave": "incidente_turno_sin_cubrir.recordatorio_repetido", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "24d1f7e1-fd87-4ed5-b355-91a09fa70660", "i18n": {"en": "{{servicio}}: {{importe}}.", "es-AR": "{{servicio}}: {{importe}}.", "pt-BR": "{{servicio}}: {{importe}}."}, "clave": "baja_servicio_con_deuda.texto_sin_atraso", "activo": true, "created_at": "2026-11-09T20:10:30.621449+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "254b5ed3-42da-4161-b263-c95a818e7f5a", "i18n": {"en": "{{contactados}} care worker was contacted, in the priority order on file.", "es-AR": "Se le escribió a {{contactados}} Asistente, en el orden de prioridad cargado.", "pt-BR": "{{contactados}} Assistente foi contatado, na ordem de prioridade cadastrada."}, "clave": "incidente_relevo_fase_automatica.contactados_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "2587ddfe-6ab1-437f-acb9-42f57424af96", "i18n": {"en": "Your code to confirm the instruction about the access of your authorized people is {{codigo}}. It expires in {{minutos}} minutes. If you did not request it, do not use it and let {{remite}} know.", "es-AR": "Su código para confirmar la instrucción sobre los accesos de sus personas autorizadas es {{codigo}}. Vence en {{minutos}} minutos. Si no lo pidió usted, no lo use y avise a {{remite}}.", "pt-BR": "O seu código para confirmar a instrução sobre os acessos das suas pessoas autorizadas é {{codigo}}. Vence em {{minutos}} minutos. Se não tiver sido solicitado, não o use e avise {{remite}}."}, "clave": "codigo_instruccion_personas_autorizadas.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "27e6c67e-afec-4411-bcf9-642d38902f82", "i18n": {"en": "Document returned", "es-AR": "Documento observado", "pt-BR": "Documento com observação"}, "clave": "documento_observado.titulo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "27f00258-9c8b-48f0-86d0-12c3ded87b81", "i18n": {"en": "Source: {{origen}}. Reason: {{motivo}}. Unresolved for {{minutos}} minutes.", "es-AR": "Origen: {{origen}}. Motivo: {{motivo}}. Sin resolver hace {{minutos}} minutos.", "pt-BR": "Origem: {{origen}}. Motivo: {{motivo}}. Sem resolver há {{minutos}} minutos."}, "clave": "alerta_temprana_sin_resolver.detalle", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "29279578-32db-405c-9b89-78a977ec351d", "i18n": {"en": "The recurring shift on {{dias}}, from {{horaInicio}} to {{horaFin}}, is no longer assigned to you.", "es-AR": "Ya no tiene asignado el turno fijo de los {{dias}}, de {{horaInicio}} a {{horaFin}}.", "pt-BR": "O plantão fixo de {{dias}}, das {{horaInicio}} às {{horaFin}}, não está mais atribuído a você."}, "clave": "turno_fijo_retirado.cuerpo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "29bcb0dd-4c5a-4120-9ae8-38066fafd6de", "i18n": {"en": "{{documento}} expires on {{fecha}}. Please upload the renewal.", "es-AR": "{{documento}} vence el {{fecha}}. Suba la renovación.", "pt-BR": "{{documento}} vence em {{fecha}}. Envie a renovação."}, "clave": "documento_por_vencer.cuerpo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "2adc34c0-737b-4147-97fb-f399bc6b49b2", "i18n": {"en": "{{servicio}}: {{importe}}, {{dias}} days overdue.", "es-AR": "{{servicio}}: {{importe}}, con {{dias}} días de atraso.", "pt-BR": "{{servicio}}: {{importe}}, com {{dias}} dias de atraso."}, "clave": "baja_servicio_con_deuda.texto", "activo": true, "created_at": "2026-11-09T20:10:30.621449+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "2d0432b5-732c-482f-b427-f2c0d3083460", "i18n": {"en": "Sequentially assigned to {{rechazos}}. All declined it.", "es-AR": "Asignada de forma secuencial a {{rechazos}}. Todos la rechazaron.", "pt-BR": "Atribuída de forma sequencial a {{rechazos}}. Todos a recusaram."}, "clave": "guardia_sin_cubrir.rechazada_varias_veces", "activo": true, "created_at": "2026-10-15T22:38:21.592176+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "2f2a61d9-1267-4ed9-866b-684374b36c78", "i18n": {"en": "{{asistente}} will be away from {{fechaInicio}} to {{fechaFin}}.", "es-AR": "{{asistente}} no va a estar desde el {{fechaInicio}} hasta el {{fechaFin}}.", "pt-BR": "{{asistente}} não vai estar de {{fechaInicio}} até {{fechaFin}}."}, "clave": "comun.ausencia_desde_hasta", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "2fb0091b-01e9-4296-8ea4-699e11fb38eb", "i18n": {"en": "This leaves {{turnos}} shift with nobody. The first one is on {{fecha}}, from {{horaInicio}} to {{horaFin}}, and it starts in {{horas}} h.", "es-AR": "Deja {{turnos}} guardia sin nadie. La primera es la del {{fecha}}, de {{horaInicio}} a {{horaFin}}, y empieza en {{horas}} h.", "pt-BR": "Deixa {{turnos}} plantão sem ninguém. O primeiro é o de {{fecha}}, das {{horaInicio}} às {{horaFin}}, e começa em {{horas}} h."}, "clave": "ausencia_avisada_con_tiempo.deja_turnos_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "300eca57-6c69-4ffb-b66c-842c8052c820", "i18n": {"en": "Unresolved for {{minutos}} minutes: passed to management", "es-AR": "Sin resolver hace {{minutos}} minutos: pasa a la administración", "pt-BR": "Sem resolver há {{minutos}} minutos: passa à administração"}, "clave": "escalada_a_la_administracion.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "31d25bb8-6c6c-478f-8f76-7d4a7a4e1662", "i18n": {"en": "Document expired", "es-AR": "Documento vencido", "pt-BR": "Documento vencido"}, "clave": "documento_vencido.titulo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "323c24df-4b0c-49dc-8615-e539b7589b07", "i18n": {"en": "Shift reminder", "es-AR": "Recordatorio de guardia", "pt-BR": "Lembrete de plantão"}, "clave": "recordatorio_de_guardia.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "3324c5b6-a108-408b-bf2c-9a50c82b50bb", "i18n": {"en": "The relief has still not arrived after {{minutos}} minute.", "es-AR": "El relevo sigue sin llegar hace {{minutos}} minuto.", "pt-BR": "A rendição continua sem chegar há {{minutos}} minuto."}, "clave": "incidente_relevo_sin_resolver.demora_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "33b2e539-594c-470c-918d-ee702dd325fc", "i18n": {"en": "Your interview is scheduled for {{cuando}}.\n\nOn the day of the interview, join through this link:\n{{enlace}}\n\nAccess opens {{anticipo}} minutes before the start time. You do not need to install anything or create an account.", "es-AR": "Su entrevista está agendada para el {{cuando}}.\n\nEl día de la entrevista, ingrese por este enlace:\n{{enlace}}\n\nEl acceso se habilita {{anticipo}} minutos antes de la hora. No necesita instalar nada ni crear una cuenta.", "pt-BR": "Sua entrevista está marcada para {{cuando}}.\n\nNo dia da entrevista, entre por este link:\n{{enlace}}\n\nO acesso é liberado {{anticipo}} minutos antes do horário. Não é necessário instalar nada nem criar uma conta."}, "clave": "entrevista_agendada.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "343d4234-34a6-4d93-aaa9-26b3f68447a1", "i18n": {"en": "The care worker already clocked out: what is missing is the confirmation that everything was done.", "es-AR": "El Asistente ya marcó su salida: falta confirmar que quedó todo hecho.", "pt-BR": "O Assistente já registrou a saída: falta confirmar que ficou tudo feito."}, "clave": "guardia_sin_cerrar.salida_marcada", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "346b2427-a88f-4fc6-9e95-573dc3ddb1ec", "i18n": {"en": "The care worker clocked out, so they left the home: what is missing is the confirmation that everything was done.", "es-AR": "El Asistente marcó su salida, así que se fue del domicilio: lo que falta es confirmar que quedó todo hecho.", "pt-BR": "O Assistente registrou a saída, então saiu do domicílio: falta confirmar que ficou tudo feito."}, "clave": "guardia_sin_cerrar_grave.salida_marcada", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "34cc32b9-c956-44ed-8447-e90322fb69c8", "i18n": {"en": "The details are in the Panel.", "es-AR": "El detalle está en el Panel.", "pt-BR": "O detalhe está no Painel."}, "clave": "alerta_ia_coordinador.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "364ebecc-6deb-4b39-9655-586f351f065a", "i18n": {"en": "a care worker with no name on file", "es-AR": "un Asistente sin nombre cargado", "pt-BR": "um Assistente sem nome cadastrado"}, "clave": "cambio_de_asistente.asistente_sin_nombre", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "38968c79-6fc4-47c7-a9e3-50bafd18fa5b", "i18n": {"en": "Shift on {{fecha}} at {{horaInicio}}. Source: {{origen}}. Reason: {{motivo}}.", "es-AR": "Guardia del {{fecha}} a las {{horaInicio}}. Origen: {{origen}}. Motivo: {{motivo}}.", "pt-BR": "Plantão de {{fecha}} às {{horaInicio}}. Origem: {{origen}}. Motivo: {{motivo}}."}, "clave": "aviso_demora_asistente.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "38df7711-9274-4597-a23e-d10fd5ce0aa4", "i18n": {"en": "hours", "es-AR": "horas", "pt-BR": "horas"}, "clave": "comun.horas", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "3a452a1a-428a-4f20-8642-a3329e28786b", "i18n": {"en": "{{contactados}} care workers were contacted, in the priority order on file.", "es-AR": "Se le escribió a {{contactados}} Asistentes, en el orden de prioridad cargado.", "pt-BR": "{{contactados}} Assistentes foram contatados, na ordem de prioridade cadastrada."}, "clave": "incidente_relevo_fase_automatica.contactados_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "3da41688-f939-43a8-861c-c8e060201dab", "i18n": {"en": "{{documento}}: {{motivo}}. Please upload it again.", "es-AR": "{{documento}}: {{motivo}}. Vuelva a cargarlo.", "pt-BR": "{{documento}}: {{motivo}}. Envie-o novamente."}, "clave": "documento_observado.cuerpo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "3eae9894-9add-4a9e-8cb8-dfbeddaa21cf", "i18n": {"en": "Save", "es-AR": "Guardar", "pt-BR": "Salvar"}, "clave": "apoderado.guardar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "41888463-9792-46b7-b19a-8684c807b800", "i18n": {"en": "Interview with {{prestadora}}", "es-AR": "Entrevista con {{prestadora}}", "pt-BR": "Entrevista com {{prestadora}}"}, "clave": "entrevista_agendada.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "43a38c69-c522-477d-87a8-89d7aeea7e54", "i18n": {"en": "This is message number {{veces}} for this same shift.", "es-AR": "Es el mensaje número {{veces}} de esta misma guardia.", "pt-BR": "É a mensagem número {{veces}} deste mesmo plantão."}, "clave": "comun.aviso_repetido_guardia", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "4470be1e-3a3d-4ea7-a0ca-20681eed4ec3", "i18n": {"en": "{{nombre}} cannot cover a shift", "es-AR": "{{nombre}} no puede cubrir un turno", "pt-BR": "{{nombre}} não pode cobrir um turno"}, "clave": "cobertura_objetada.asunto", "activo": true, "created_at": "2026-09-30T23:36:26.907358+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "44a41238-5dea-4af9-a1cd-651c489e6f87", "i18n": {"en": "Early warning of a possible no-show, unresolved", "es-AR": "Alerta temprana de posible ausencia sin resolver", "pt-BR": "Alerta antecipado de possível ausência sem resolver"}, "clave": "alerta_temprana_sin_resolver.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "464abbbc-7bce-4841-8a4a-63644d9775fc", "i18n": {"en": "The email on your {{empresa}} account changed. If you did not request this change, contact {{empresa}}.", "es-AR": "El email de su cuenta en {{empresa}} cambió. Si usted no pidió este cambio, comuníquese con {{empresa}}.", "pt-BR": "O e-mail da sua conta na {{empresa}} mudou. Se você não pediu esta alteração, entre em contato com {{empresa}}."}, "clave": "email_cambiado.texto", "activo": true, "created_at": "2026-10-19T21:14:34.120412+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "4707ab30-0bcc-4858-bf74-8f801cf9671b", "i18n": {"en": "{{etiqueta}} expiring soon — {{cuantos}} care workers", "es-AR": "Vencimientos próximos de {{etiqueta}} — {{cuantos}} Asistentes", "pt-BR": "Vencimentos próximos de {{etiqueta}} — {{cuantos}} Assistentes"}, "clave": "vencimiento_documentos.asunto_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "4886457e-b985-499d-a1b8-cab781fa2e4a", "i18n": {"en": "Shift on {{fecha}} from {{horaInicio}} to {{horaFin}}. The care worker requested emergency relief and is still at the home.", "es-AR": "Guardia del {{fecha}} de {{horaInicio}} a {{horaFin}}. El Asistente pidió un relevo de emergencia y sigue en el domicilio.", "pt-BR": "Plantão de {{fecha}} das {{horaInicio}} às {{horaFin}}. O Assistente pediu uma rendição de emergência e continua no domicílio."}, "clave": "relevo_de_emergencia.texto", "activo": true, "created_at": "2026-10-27T04:40:58.720695+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "4b63ceb0-48b0-40e3-905f-1b8d3d8e253d", "i18n": {"en": "Choose it here:", "es-AR": "Se elige acá:", "pt-BR": "A escolha é feita aqui:"}, "clave": "recuperacion_clave.invitacion_al_enlace", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "4d95d3b0-c0eb-4784-aeb9-e79c98fa6be3", "i18n": {"en": "Unresolved for more than {{minutosUmbral}} minutes.", "es-AR": "Sin resolver hace más de {{minutosUmbral}} minutos.", "pt-BR": "Sem resolver há mais de {{minutosUmbral}} minutos."}, "clave": "incidente_relevo_fase_automatica.sin_resolver_desde", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "4db0a096-b362-42fc-9b26-2019928868eb", "i18n": {"en": "Thursday", "es-AR": "jueves", "pt-BR": "quinta-feira"}, "clave": "comun.dia_jueves", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "4fee3f62-be53-476a-aa7a-6242a71e0e22", "i18n": {"en": "{{anterior}} no longer covers this shift. {{nuevo}} covers it now.", "es-AR": "{{anterior}} ya no hace esta guardia. Ahora la hace {{nuevo}}.", "pt-BR": "{{anterior}} não faz mais este plantão. Agora é feito por {{nuevo}}."}, "clave": "cambio_de_asistente.cambio_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "50b763dd-500e-4568-92db-93481b8f3016", "i18n": {"en": "It also leaves {{otras}} more shift with nobody.", "es-AR": "Además deja otra guardia sin nadie.", "pt-BR": "Além disso, deixa outro plantão sem ninguém."}, "clave": "ausencia_de_golpe.ademas_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "515bf718-1ec6-4342-ac6a-bea5aea23ae7", "i18n": {"en": "Shift with an open alert", "es-AR": "Guardia con una alerta pendiente", "pt-BR": "Plantão com um alerta pendente"}, "clave": "alerta_temprana_guardia_cliente.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "5242d689-a0a3-4a14-8224-996ef5d0ae3e", "i18n": {"en": "Friday", "es-AR": "viernes", "pt-BR": "sexta-feira"}, "clave": "comun.dia_viernes", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "5281e7a3-d95d-4dc9-83cc-4e62c484f1c2", "i18n": {"en": "Cancel", "es-AR": "Cancelar", "pt-BR": "Cancelar"}, "clave": "apoderado.cancelar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "535d744f-2e92-4938-a975-f87d28008563", "i18n": {"en": "Your interview with {{prestadora}} was cancelled", "es-AR": "Se canceló su entrevista con {{prestadora}}", "pt-BR": "Sua entrevista com {{prestadora}} foi cancelada"}, "clave": "entrevista_cancelada.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "53f2f541-acad-4b46-94e9-f3224660e504", "i18n": {"en": "Complete this field.", "es-AR": "Complete este dato.", "pt-BR": "Preencha este dado."}, "clave": "apoderado.campo_obligatorio", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "54965aef-36de-49ad-b64e-e4f7e3971174", "i18n": {"en": "Shift assigned", "es-AR": "Turno asignado", "pt-BR": "Plantão atribuído"}, "clave": "turno_para_responder.titulo", "activo": true, "created_at": "2026-10-16T05:03:19.135198+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "550ef7c2-855f-4304-b795-ea10b60abb69", "i18n": {"en": "This patient has no team set up yet.", "es-AR": "Este Paciente todavía no tiene equipo armado.", "pt-BR": "Este Paciente ainda não tem equipe montada."}, "clave": "incidente_turno_sin_cubrir.sin_equipo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "56d906cf-027a-4160-bf31-2a8dff244659", "i18n": {"en": "Appoint signatory", "es-AR": "Nombrar apoderado", "pt-BR": "Nomear procurador"}, "clave": "apoderado.nombrar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "570e32ff-6533-46d1-a8a7-38e09b5fbe48", "i18n": {"en": "care workers", "es-AR": "Asistentes", "pt-BR": "Assistentes"}, "clave": "comun.asistente_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "58d58f89-3e57-47b8-a843-fff86b7cf93c", "i18n": {"en": "Document to sign", "es-AR": "Documento para firmar", "pt-BR": "Documento para assinar"}, "clave": "documento_para_firmar.asunto", "activo": true, "created_at": "2026-11-05T04:47:46.731061+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "5a72165a-53ba-4186-8bcd-55b6224c1dc5", "i18n": {"en": "The care worker on a shift changed", "es-AR": "Cambió el Asistente de una guardia", "pt-BR": "O Assistente de um plantão mudou"}, "clave": "cambio_de_asistente.asunto_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "5b6d43db-85c1-40ff-ae0f-0c29f536883f", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, has ended and the relief has not arrived yet. If you have any questions, you can contact your coordinator.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, terminó y el relevo todavía no llegó. Ante cualquier duda, puede comunicarse con su Coordinador.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, terminou e a rendição ainda não chegou. Em caso de dúvida, pode entrar em contato com o seu Coordenador."}, "clave": "incidente_relevo_cliente.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "5f63cee9-94b9-4e24-aad7-544c45217c55", "i18n": {"en": "The link expires in {{dias}} day. If you were not expecting this email, you can ignore it.", "es-AR": "El enlace vence en {{dias}} día. Si no esperaba este correo, puede ignorarlo.", "pt-BR": "O link expira em {{dias}} dia. Se este e-mail não era esperado, pode ser ignorado."}, "clave": "activacion_cuenta.pie_de_aviso_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "61a08f16-0f4c-4cdc-b4e1-9a459df69f3d", "i18n": {"en": "{{nombre}}: the password on your account has just been changed.\n\nIf this was not you, tell {{prestadora}} right away.", "es-AR": "{{nombre}}: la clave de su cuenta acaba de cambiarse.\n\nSi no fue usted, avise a {{prestadora}} ahora mismo.", "pt-BR": "{{nombre}}: a senha da sua conta acaba de ser alterada.\n\nSe não foi você, avise a {{prestadora}} agora mesmo."}, "clave": "clave_recuperada.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "63e1308d-776a-4141-a653-40493dd9f3c9", "i18n": {"en": "The shift ended and the relief has not arrived", "es-AR": "La guardia terminó y el relevo todavía no llegó", "pt-BR": "O plantão terminou e a rendição ainda não chegou"}, "clave": "incidente_relevo_sin_resolver.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "641e04c8-fe5d-4796-8514-ec506306608f", "i18n": {"en": "Your {{empresa}} account has been created. One step left: choose your password.", "es-AR": "Su cuenta en {{empresa}} ya está creada. Falta un paso: elegir su contraseña.", "pt-BR": "A sua conta na {{empresa}} já está criada. Falta um passo: escolher a sua senha."}, "clave": "activacion_cuenta.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "65d53d70-92ff-47e9-ae00-7ed9bff7ed79", "i18n": {"en": "Document about to expire", "es-AR": "Documento por vencer", "pt-BR": "Documento a vencer"}, "clave": "documento_por_vencer.titulo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "66f327c6-f090-4e82-b462-f12fdc2727ea", "i18n": {"en": "Your {{prestadora}} account was opened from a new device", "es-AR": "Entraron a su cuenta de {{prestadora}} desde un equipo nuevo", "pt-BR": "Entraram na sua conta da {{prestadora}} a partir de um equipamento novo"}, "clave": "entrada_desde_equipo_nuevo.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "66f8be46-85fd-41da-902f-bef31234b3d4", "i18n": {"en": "minutes", "es-AR": "minutos", "pt-BR": "minutos"}, "clave": "comun.minutos", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "69d6b3d8-ee9f-4aac-abdb-cb545cc61e76", "i18n": {"en": "Upcoming deletion of the {{anio}} access record", "es-AR": "Próximo borrado del registro de accesos de {{anio}}", "pt-BR": "Próxima exclusão do registro de acessos de {{anio}}"}, "clave": "borrado_del_registro_de_accesos_preaviso.asunto", "activo": true, "created_at": "2026-11-10T23:51:19.634456+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "6b22f94d-30eb-4b03-acea-0bcda0981ddd", "i18n": {"en": "Approved", "es-AR": "Aprobado", "pt-BR": "Aprovado"}, "clave": "apoderado.estado_aprobado", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "6c8a13ec-8e2b-4f9d-b35c-a24b89ae3136", "i18n": {"en": "It should have started {{horas}} h ago.", "es-AR": "Tendría que haber empezado hace {{horas}} h.", "pt-BR": "Deveria ter começado há {{horas}} h."}, "clave": "comun.tendria_que_haber_empezado", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "6f96c175-424c-4a4f-8823-082efe354a92", "i18n": {"en": "{{nombre}}: expires {{fechaVencimiento}}", "es-AR": "{{nombre}}: vence {{fechaVencimiento}}", "pt-BR": "{{nombre}}: vence {{fechaVencimiento}}"}, "clave": "vencimiento_documentos.linea", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "6fba71ae-ad2a-45f1-a317-ef078f183508", "i18n": {"en": "You have a replacement assigned from {{desde}} to {{hasta}}. Accept or decline the offer.", "es-AR": "Tiene asignado un reemplazo del {{desde}} al {{hasta}}. Acepte o rechace la propuesta.", "pt-BR": "Você tem uma substituição atribuída de {{desde}} a {{hasta}}. Aceite ou recuse a proposta."}, "clave": "reemplazo_para_responder.cuerpo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "707a220c-5503-4d23-bd8d-86b7f243674e", "i18n": {"en": "Under review", "es-AR": "En revisión", "pt-BR": "Em análise"}, "clave": "apoderado.estado_en_revision", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "71248a6a-b310-4d7d-95ad-0d735c1391c5", "i18n": {"en": "Saturday", "es-AR": "sábado", "pt-BR": "sábado"}, "clave": "comun.dia_sabado", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "717ab30b-0029-44cb-9664-8f68aa0d6316", "i18n": {"en": "The payment could not be taken", "es-AR": "El cobro no se pudo hacer", "pt-BR": "A cobrança não pôde ser feita"}, "clave": "cobro_no_realizado.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "71bce872-a6ab-4f89-ad45-a6c846ad862b", "i18n": {"en": "There is something important to review in the application.", "es-AR": "Hay una novedad importante para revisar en la aplicación.", "pt-BR": "Há uma novidade importante para revisar no aplicativo."}, "clave": "alerta_ia_cliente.cuerpo_roja", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "722309fa-1535-4dc0-bfd2-a6a7c61659ac", "i18n": {"en": "Shift not closed", "es-AR": "Guardia sin cerrar", "pt-BR": "Plantão sem encerrar"}, "clave": "guardia_sin_cerrar_grave_cliente.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "73d90690-1df9-41b4-a4c5-aa1436ceb5a9", "i18n": {"en": "Your account email changed", "es-AR": "Cambió el email de su cuenta", "pt-BR": "O e-mail da sua conta mudou"}, "clave": "email_cambiado.asunto", "activo": true, "created_at": "2026-10-19T21:14:34.120412+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "77b19c58-05db-4ccb-9895-93cd8da2e340", "i18n": {"en": "The care worker has not clocked out yet.", "es-AR": "El Asistente todavía no marcó su salida.", "pt-BR": "O Assistente ainda não registrou a saída."}, "clave": "guardia_sin_cerrar.salida_sin_marcar", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7837bafc-d1f9-4b3f-a695-2aaabdd1a525", "i18n": {"en": "The care worker on several shifts changed", "es-AR": "Cambió el Asistente de varias guardias", "pt-BR": "O Assistente de vários plantões mudou"}, "clave": "cambio_de_asistente.asunto_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "788f3a79-f0b0-43f8-9f62-ea5fab2804b0", "i18n": {"en": "Update about the patient", "es-AR": "Novedad sobre el Paciente", "pt-BR": "Novidade sobre o Paciente"}, "clave": "alerta_ia_cliente.titulo_amarilla", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7968ba6a-1fb8-453c-8ddb-54584660d6f9", "i18n": {"en": "Recover your {{empresa}} password", "es-AR": "Recupere su clave en {{empresa}}", "pt-BR": "Recupere a sua senha na {{empresa}}"}, "clave": "recuperacion_clave.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "79b2240e-79cb-49b3-a0f6-7d7fb341c2bc", "i18n": {"en": "Your application is under review.", "es-AR": "Su postulación está en revisión.", "pt-BR": "A sua candidatura está em análise."}, "clave": "estado_postulacion.en_revision", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7c83dc12-05f2-4ead-bfc4-b74a04767159", "i18n": {"en": "Upload", "es-AR": "Cargar", "pt-BR": "Enviar"}, "clave": "apoderado.cargar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7d378f5a-8829-452d-ac68-2a90a98a1964", "i18n": {"en": "Service ended", "es-AR": "Finalización de servicio", "pt-BR": "Fim do serviço"}, "clave": "cese_de_servicio.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7e9770b4-877c-45fe-a89b-aee7164adf8d", "i18n": {"en": "{{nombre}}'s absence was expected to end on {{fecha}} and no return has been recorded. Until a return or a new expected date is recorded, the absence stays open and coverage continues.", "es-AR": "La ausencia de {{nombre}} tenía prevista la vuelta para el {{fecha}} y nadie la anotó. Mientras no se anote la vuelta o una nueva fecha prevista, la ausencia sigue abierta y la cobertura continúa.", "pt-BR": "A ausência de {{nombre}} tinha retorno previsto para {{fecha}} e ninguém o registrou. Enquanto não se registrar o retorno ou uma nova data prevista, a ausência continua aberta e a cobertura segue."}, "clave": "vuelta_de_ausencia_sin_confirmar.cuerpo", "activo": true, "created_at": "2026-09-30T23:36:26.907358+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7f613b4c-6374-48da-b613-c52537309092", "i18n": {"en": "Emergency reported from a shift", "es-AR": "Emergencia avisada desde una guardia", "pt-BR": "Emergência avisada a partir de um plantão"}, "clave": "emergencia_en_guardia.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "7fd2a52e-0d4f-418e-a088-d73247e44f5b", "i18n": {"en": "There is no priority order on file, so nobody was contacted.", "es-AR": "No hay ningún orden de prioridad cargado, así que no se contactó a nadie.", "pt-BR": "Não há nenhuma ordem de prioridade cadastrada, portanto ninguém foi contatado."}, "clave": "incidente_relevo_fase_automatica.sin_orden", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "831a4a80-8e4b-4aa3-8fbc-ccf3f533fea9", "i18n": {"en": "another care worker", "es-AR": "otro Asistente", "pt-BR": "outro Assistente"}, "clave": "cambio_de_asistente_cliente.otro_asistente", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "83a60204-b800-4716-9364-dd22f7be3100", "i18n": {"en": "Cancellation of a Service with debt", "es-AR": "Baja de un Servicio con deuda", "pt-BR": "Baixa de um Serviço com dívida"}, "clave": "baja_servicio_con_deuda.asunto", "activo": true, "created_at": "2026-11-09T20:10:30.621449+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "8480b53f-6ef4-4a93-8ebd-3d7ef51bb2ff", "i18n": {"en": "Signed electronically through the link sent to the email account {{email}} on {{fecha}} at {{hora}}.", "es-AR": "Firmado electrónicamente mediante el enlace enviado a su cuenta de correo {{email}} el {{fecha}} a las {{hora}}.", "pt-BR": "Assinado eletronicamente por meio do link enviado para a conta de e-mail {{email}} em {{fecha}} às {{hora}}."}, "clave": "documento_para_firmar.firmado_electronicamente", "activo": true, "created_at": "2026-11-08T19:27:12.397247+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "85ca799d-c800-4763-915b-07559c525d50", "i18n": {"en": "{{servicio}}: {{importe}}, {{dias}} day overdue.", "es-AR": "{{servicio}}: {{importe}}, con {{dias}} día de atraso.", "pt-BR": "{{servicio}}: {{importe}}, com {{dias}} dia de atraso."}, "clave": "baja_servicio_con_deuda.texto_uno", "activo": true, "created_at": "2026-11-09T20:10:30.621449+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "85d790fe-4f0e-4305-9669-f74b12e55dc1", "i18n": {"en": "{{nombre}}: the phone number on your account has just been changed and is not verified yet.\n\nIf this was not you, tell {{prestadora}} right away.", "es-AR": "{{nombre}}: el teléfono de su cuenta acaba de cambiarse y todavía está sin verificar.\n\nSi no fue usted, avise a {{prestadora}} ahora mismo.", "pt-BR": "{{nombre}}: o telefone da sua conta acaba de ser alterado e ainda está sem verificar.\n\nSe não foi você, avise a {{prestadora}} agora mesmo."}, "clave": "telefono_cambiado.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "860934e4-e689-4a51-89c1-1ecf9b10621a", "i18n": {"en": "Nobody in the priority order on file was available to contact.", "es-AR": "No había nadie disponible en el orden de prioridad cargado.", "pt-BR": "Não havia ninguém disponível na ordem de prioridade cadastrada."}, "clave": "incidente_relevo_fase_automatica.nadie_disponible", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "86efc3fd-8266-4ae3-b035-fd9b944d508c", "i18n": {"en": "Shift withdrawn", "es-AR": "Turno retirado", "pt-BR": "Plantão retirado"}, "clave": "turno_retirado.titulo", "activo": true, "created_at": "2026-10-16T05:03:19.135198+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "8755cedb-f1fa-46cf-bbb1-f9a2e3a3be58", "i18n": {"en": "Printed name", "es-AR": "Aclaración", "pt-BR": "Nome legível"}, "clave": "pie_de_firmas.aclaracion", "activo": true, "created_at": "2026-11-08T19:27:12.397247+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "87a9f25d-3ad5-4e93-860c-e82cdc7125e4", "i18n": {"en": "Assigned to {{asistente}}. It was due to end {{atraso}} ago and is still open.", "es-AR": "A cargo de {{asistente}}. Terminaba hace {{atraso}} y sigue abierta.", "pt-BR": "A cargo de {{asistente}}. Terminava há {{atraso}} e continua aberto."}, "clave": "comun.a_cargo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "87febe55-f9a4-42c0-b6fb-f34bb9c4e956", "i18n": {"en": "The phone number on your {{prestadora}} account was changed", "es-AR": "Se cambió el teléfono de su cuenta en {{prestadora}}", "pt-BR": "O telefone da sua conta na {{prestadora}} foi alterado"}, "clave": "telefono_cambiado.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "88c1928f-588b-469e-bfcc-a1bea79568da", "i18n": {"en": "Code to confirm the access of your authorized people — {{remite}}", "es-AR": "Código para confirmar los accesos de sus personas autorizadas — {{remite}}", "pt-BR": "Código para confirmar os acessos das suas pessoas autorizadas — {{remite}}"}, "clave": "codigo_instruccion_personas_autorizadas.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "8db623ba-0b7e-4102-8dee-de368070f4ac", "i18n": {"en": "The relief has still not arrived after {{minutos}} minute.", "es-AR": "El relevo sigue sin llegar hace {{minutos}} minuto.", "pt-BR": "A rendição continua sem chegar há {{minutos}} minuto."}, "clave": "incidente_relevo_respaldo.demora_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "8e1d8826-f79d-41f2-b5ae-f9557ca7c6cb", "i18n": {"en": "Shift not covered: the start time has passed", "es-AR": "Guardia sin cubrir: la hora de inicio ya pasó", "pt-BR": "Plantão sem cobertura: o horário de início já passou"}, "clave": "guardia_sin_cubrir.asunto_ya_empezo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "8e8d1f7c-00a3-499b-8c37-36ac8af90918", "i18n": {"en": "Shift on {{fecha}} at {{horaInicio}}. The care worker reported an emergency. The details are in the Panel.", "es-AR": "Guardia del {{fecha}} a las {{horaInicio}}. El Asistente avisó una emergencia. El detalle está en el Panel.", "pt-BR": "Plantão de {{fecha}} às {{horaInicio}}. O Assistente avisou uma emergência. O detalhe está no Painel."}, "clave": "emergencia_en_guardia.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9021c989-86af-4a4e-ba8e-e0e107150b3d", "i18n": {"en": "No care worker assigned.", "es-AR": "Sin Asistente asignado.", "pt-BR": "Sem Assistente atribuído."}, "clave": "guardia_sin_cubrir.sin_asignar", "activo": true, "created_at": "2026-10-15T22:38:21.592176+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "90a03246-68c9-45c2-b2c7-0dc6f817d756", "i18n": {"en": "Recurring shift assigned", "es-AR": "Turno fijo asignado", "pt-BR": "Plantão fixo atribuído"}, "clave": "turno_fijo_para_responder.titulo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "928204fd-fed5-4ad1-b093-bcb64ed39e3a", "i18n": {"en": "This leaves {{turnos}} shifts with nobody. The first one is on {{fecha}}, from {{horaInicio}} to {{horaFin}}, and it starts in {{horas}} h.", "es-AR": "Deja {{turnos}} guardias sin nadie. La primera es la del {{fecha}}, de {{horaInicio}} a {{horaFin}}, y empieza en {{horas}} h.", "pt-BR": "Deixa {{turnos}} plantões sem ninguém. O primeiro é o de {{fecha}}, das {{horaInicio}} às {{horaFin}}, e começa em {{horas}} h."}, "clave": "ausencia_avisada_con_tiempo.deja_turnos_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "92c1055e-26d5-48a7-8230-a0b0a7b8d60a", "i18n": {"en": "This is message number {{veces}} for this same absence.", "es-AR": "Es el mensaje número {{veces}} de esta misma ausencia.", "pt-BR": "É a mensagem número {{veces}} desta mesma ausência."}, "clave": "comun.aviso_repetido_ausencia", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "952aa54b-be35-4266-b163-760ab4c09d14", "i18n": {"en": "Remove", "es-AR": "Quitar", "pt-BR": "Remover"}, "clave": "apoderado.quitar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "96ea6354-3422-4deb-bbbf-4a593723d056", "i18n": {"en": "care worker", "es-AR": "Asistente", "pt-BR": "Assistente"}, "clave": "comun.asistente_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "9979b20f-1785-4f0f-bc9c-5ffe6b50fc48", "i18n": {"en": "First name", "es-AR": "Nombre", "pt-BR": "Nome"}, "clave": "apoderado.nombre", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9a7b939e-58dc-4a59-8fed-192ed19715e2", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, for {{pacientes}} is past its closing time and is still open. If you have any questions, you can contact your coordinator.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, para {{pacientes}} pasó su hora de cierre y todavía figura abierta. Ante cualquier duda, puede comunicarse con su Coordinador.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, para {{pacientes}} passou da hora de encerramento e ainda consta aberto. Em caso de dúvida, pode entrar em contato com o seu Coordenador."}, "clave": "guardia_sin_cerrar_cliente.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9afaccb3-c90e-4121-9323-96a97e4158d8", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, is no longer assigned to you.", "es-AR": "Ya no tiene asignado el turno del {{fecha}}, de {{horaInicio}} a {{horaFin}}.", "pt-BR": "O plantão do dia {{fecha}}, das {{horaInicio}} às {{horaFin}}, não está mais atribuído a você."}, "clave": "turno_retirado.cuerpo", "activo": true, "created_at": "2026-10-16T05:03:19.135198+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9b5fcfe7-71f8-4cb0-baaf-f2865e29df2a", "i18n": {"en": "Activate your {{empresa}} account", "es-AR": "Active su cuenta en {{empresa}}", "pt-BR": "Ative a sua conta na {{empresa}}"}, "clave": "activacion_cuenta.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9d79a573-5817-4495-8228-f2f0d061f808", "i18n": {"en": "delay reported by the care worker from the application", "es-AR": "aviso de demora dado por el Asistente desde la aplicación", "pt-BR": "aviso de atraso dado pelo Assistente pelo aplicativo"}, "clave": "origen_de_alerta.aviso_demora_asistente", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9ec364e7-d375-4284-b233-81227b15fda0", "i18n": {"en": "There is something to look at in the application, no rush.", "es-AR": "Hay algo para mirar sin apuro en la aplicación.", "pt-BR": "Há algo para olhar sem pressa no aplicativo."}, "clave": "alerta_ia_cliente.cuerpo_amarilla", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9f196448-107f-40a9-b817-f5ad6e127283", "i18n": {"en": "Change of care worker", "es-AR": "Cambio de Asistente", "pt-BR": "Mudança de Assistente"}, "clave": "cambio_de_asistente_cliente.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9f4308f6-a4a6-490f-b207-1b4fb5899a9f", "i18n": {"en": "{{fecha}}, from {{horaInicio}} to {{horaFin}}, for {{pacientes}}.", "es-AR": "{{fecha}}, de {{horaInicio}} a {{horaFin}}, para {{pacientes}}.", "pt-BR": "{{fecha}}, das {{horaInicio}} às {{horaFin}}, para {{pacientes}}."}, "clave": "cambio_de_asistente.linea_turno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "9f8c2e55-ce96-48a3-85ec-15d6e64519e7", "i18n": {"en": "The early warning has been unresolved for {{minutos}} minute.", "es-AR": "La alerta temprana sigue sin resolver hace {{minutos}} minuto.", "pt-BR": "O alerta antecipado continua sem resolver há {{minutos}} minuto."}, "clave": "alerta_temprana_respaldo.demora_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a02b0b9f-2b34-4451-9eb4-bd8b33d32231", "i18n": {"en": "You have a shift assigned for {{fecha}}, from {{horaInicio}} to {{horaFin}}. Accept or decline the offer.", "es-AR": "Tiene un turno asignado para el {{fecha}}, de {{horaInicio}} a {{horaFin}}. Acepte o rechace la propuesta.", "pt-BR": "Você tem um plantão atribuído para o dia {{fecha}}, das {{horaInicio}} às {{horaFin}}. Aceite ou recuse a proposta."}, "clave": "turno_para_responder.cuerpo", "activo": true, "created_at": "2026-10-16T05:03:19.135198+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a08edeef-24cd-44b4-af82-8414046474ed", "i18n": {"en": "Unresolved for {{minutos}} minute: passed to every coordinator", "es-AR": "Sin resolver hace {{minutos}} minuto: pasa a todos los Coordinadores", "pt-BR": "Sem resolver há {{minutos}} minuto: passa a todos os Coordenadores"}, "clave": "escalada_a_todos_los_coordinadores.asunto_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a0a8c6dc-a7b4-454d-a2a7-a8d3b4ac6c76", "i18n": {"en": "Activate the account", "es-AR": "Activar la cuenta", "pt-BR": "Ativar a conta"}, "clave": "activacion_cuenta.boton", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a405e3d6-bc89-4ce3-9bcc-1dc2767255a1", "i18n": {"en": "Unresolved for {{minutos}} minute: passed to management", "es-AR": "Sin resolver hace {{minutos}} minuto: pasa a la administración", "pt-BR": "Sem resolver há {{minutos}} minuto: passa à administração"}, "clave": "escalada_a_la_administracion.asunto_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a53ea39f-99dd-4fba-8199-6e0dc5f4d4d0", "i18n": {"en": "{{etiqueta}} expiring soon — {{cuantos}} care worker", "es-AR": "Vencimientos próximos de {{etiqueta}} — {{cuantos}} Asistente", "pt-BR": "Vencimentos próximos de {{etiqueta}} — {{cuantos}} Assistente"}, "clave": "vencimiento_documentos.asunto_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a58ac948-e75c-4550-ae4c-c87ddc699e90", "i18n": {"en": "Assigned to a care worker. Pending response.", "es-AR": "Asignada a un Asistente. Pendiente de respuesta.", "pt-BR": "Atribuída a um Assistente. Pendente de resposta."}, "clave": "guardia_sin_cubrir.sin_responder", "activo": true, "created_at": "2026-10-15T22:38:21.592176+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a5b9e3b5-e68c-4c0f-aca7-a8fc44646625", "i18n": {"en": "Approve", "es-AR": "Aprobar", "pt-BR": "Aprovar"}, "clave": "apoderado.aprobar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a6429c3c-0066-402b-84c2-d8c2877be947", "i18n": {"en": "The system notified the Coordinator and the shift is still not closed. Step in to resolve it.", "es-AR": "El sistema avisó al Coordinador y la guardia sigue sin cerrarse. Intervenga para resolverlo.", "pt-BR": "O sistema avisou o Coordenador e o plantão continua sem ser encerrado. Intervenha para resolver."}, "clave": "guardia_sin_cerrar_grave.hace_falta_autoridad", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a67242f5-0a9e-4c36-ab0e-095e9b9b3da7", "i18n": {"en": "Email sent", "es-AR": "Email enviado", "pt-BR": "E-mail enviado"}, "clave": "documento_para_firmar.enviado", "activo": true, "created_at": "2026-11-05T04:47:46.731061+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a8f58178-7489-4b93-8847-0562d61cc755", "i18n": {"en": "source not recorded", "es-AR": "origen sin registrar", "pt-BR": "origem sem registro"}, "clave": "origen_de_alerta.sin_registrar", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a9247b11-5161-44be-8e67-665c44ac1fe9", "i18n": {"en": "Recurring shift withdrawn", "es-AR": "Turno fijo retirado", "pt-BR": "Plantão fixo retirado"}, "clave": "turno_fijo_retirado.titulo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "a96d318a-7ab3-40eb-a798-1f9d9f1808d7", "i18n": {"en": "Assigned to {{asistente}} (declined).", "es-AR": "Asignada a {{asistente}} (rechazada).", "pt-BR": "Atribuída a {{asistente}} (recusada)."}, "clave": "guardia_sin_cubrir.rechazada_una_vez", "activo": true, "created_at": "2026-10-15T22:38:21.592176+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ac0b9f75-e18c-4ed5-ae9e-9d414fab9e6b", "i18n": {"en": "{{nombre}}: your account was opened from a device that had never been used before.\n\nIf this was not you, change your password and sign out on every device from your own screen.", "es-AR": "{{nombre}}: se entró a su cuenta desde un equipo desde el que nunca se había entrado.\n\nSi no fue usted, cambie su clave y cierre la sesión en todos los equipos desde su propia pantalla.", "pt-BR": "{{nombre}}: entraram na sua conta a partir de um equipamento do qual nunca se tinha entrado.\n\nSe não foi você, troque a sua senha e feche a sessão em todos os equipamentos pela sua própria tela."}, "clave": "entrada_desde_equipo_nuevo.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "ad053d1b-5ad0-4ae2-99e9-844c811b8969", "i18n": {"en": "Your interview is scheduled for {{cuando}}.\n\nJoin through the same link as before:\n{{enlace}}\n\nAccess opens {{anticipo}} minutes before the start time.", "es-AR": "Su entrevista está agendada para el {{cuando}}.\n\nIngrese por el mismo enlace de siempre:\n{{enlace}}\n\nEl acceso se habilita {{anticipo}} minutos antes de la hora.", "pt-BR": "Sua entrevista está marcada para {{cuando}}.\n\nEntre pelo mesmo link de sempre:\n{{enlace}}\n\nO acesso é liberado {{anticipo}} minutos antes do horário."}, "clave": "entrevista_reprogramada.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ae71a92a-082e-450b-a87f-313193b77256", "i18n": {"en": "Wednesday", "es-AR": "miércoles", "pt-BR": "quarta-feira"}, "clave": "comun.dia_miercoles", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "aed364b7-7aaf-4917-ae92-3b473ee2d0ab", "i18n": {"en": "The {{empresa}} team", "es-AR": "Equipo de {{empresa}}", "pt-BR": "Equipe {{empresa}}"}, "clave": "estado_postulacion.firma", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "af28fd70-8764-48d7-86de-27035c58d713", "i18n": {"en": "system estimate: the expected arrival time is past the start time", "es-AR": "cuenta del sistema: la hora estimada de llegada pasa la hora de inicio", "pt-BR": "cálculo do sistema: o horário previsto de chegada passa do horário de início"}, "clave": "origen_de_alerta.calculo_llegada_tardia", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "b0f83569-88a6-4a00-99bb-367186aa63de", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, is still open {{minutos}} minutes past the deadline.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, sigue sin cerrarse {{minutos}} minutos después del plazo.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, continua sem fechar {{minutos}} minutos depois do prazo."}, "clave": "guardia_sin_cerrar_respaldo.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "b4bb3e0f-8ae2-43cf-b94a-235a43b9b1e3", "i18n": {"en": "The interview set for {{cuando}} has been called off. Your application still stands.", "es-AR": "La entrevista del {{cuando}} quedó sin efecto. Su postulación sigue en pie.", "pt-BR": "A entrevista de {{cuando}} ficou sem efeito. A sua candidatura continua de pé."}, "clave": "entrevista_cancelada.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "b737f79d-cf2b-44ba-9014-342908a5a3d3", "i18n": {"en": "From {{dia}} the charge is {{importe}}. If you would rather not continue, you can cancel before then from the application.", "es-AR": "A partir del {{dia}} se cobra {{importe}}. Si prefiere no continuar, puede darse de baja antes desde la aplicación.", "pt-BR": "A partir de {{dia}} passa a ser cobrado {{importe}}. Se preferir não continuar, pode cancelar antes pelo aplicativo."}, "clave": "fin_periodo_sin_cargo.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "b8feadfb-c054-4093-9e84-9821af397726", "i18n": {"en": "{{nombre}}: {{prestadora}} has opened a short window for you to choose a new password. You choose it: nobody at {{prestadora}} sees it or knows it.\n\nIf you did not call to ask for this, say so right away.", "es-AR": "{{nombre}}: {{prestadora}} habilitó por un rato que usted elija una clave nueva. La clave la elige usted: nadie de {{prestadora}} la ve ni la conoce.\n\nSi usted no llamó para pedirlo, avise ahora mismo.", "pt-BR": "{{nombre}}: a {{prestadora}} liberou por um tempo curto que você escolha uma senha nova. A senha é escolhida por você: ninguém da {{prestadora}} a vê nem a conhece.\n\nSe você não ligou para pedir isso, avise agora mesmo."}, "clave": "cambio_de_clave_habilitado.texto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "b92526c5-b06e-4c38-b4d3-2417253ad3e9", "i18n": {"en": "Shift with nobody: it already started and is still open", "es-AR": "Guardia sin nadie: ya empezó y sigue abierta", "pt-BR": "Plantão sem ninguém: já começou e continua aberto"}, "clave": "incidente_turno_sin_cubrir.asunto_ya_empezo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "be27eca1-8c1e-47d5-b836-d47e0f63d763", "i18n": {"en": "Shift finished and still open", "es-AR": "Guardia terminada y todavía sin cerrar", "pt-BR": "Plantão terminado e ainda sem fechar"}, "clave": "guardia_sin_cerrar.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "be7f0965-4403-466e-b245-955fe6b297c4", "i18n": {"en": "{{nuevo}} replaces {{anterior}} on the shift of {{fecha}}, from {{horaInicio}} to {{horaFin}}.", "es-AR": "{{nuevo}} reemplaza a {{anterior}} en la guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}.", "pt-BR": "{{nuevo}} substitui {{anterior}} no plantão do dia {{fecha}}, das {{horaInicio}} às {{horaFin}}."}, "clave": "cambio_de_asistente_cliente.reemplaza_uno", "activo": true, "created_at": "2026-10-16T05:03:19.135198+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "bfbaa005-c5a2-4a6c-a222-ac17157719e3", "i18n": {"en": "Confirm {{nombre}}'s return", "es-AR": "Confirmar la vuelta de {{nombre}}", "pt-BR": "Confirmar o retorno de {{nombre}}"}, "clave": "vuelta_de_coordinador_sin_confirmar.asunto", "activo": true, "created_at": "2026-09-30T23:36:26.907358+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c02d9cc1-1117-496e-87e6-0b7e7d9a817c", "i18n": {"en": "Tuesday", "es-AR": "martes", "pt-BR": "terça-feira"}, "clave": "comun.dia_martes", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c12fb745-525c-48a2-a477-84fe1e4e8f8c", "i18n": {"en": "Your {{prestadora}} account password was changed", "es-AR": "Se cambió la clave de su cuenta en {{prestadora}}", "pt-BR": "A senha da sua conta na {{prestadora}} foi alterada"}, "clave": "clave_recuperada.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "c2dc730e-64a6-4d2e-a57a-f578db921684", "i18n": {"en": "Urgent: a shift has been open for hours", "es-AR": "Urgente: una guardia lleva horas sin cerrarse", "pt-BR": "Urgente: um plantão está há horas sem fechar"}, "clave": "guardia_sin_cerrar_grave.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c32932d3-2ec0-48cc-9793-902e09b85b3f", "i18n": {"en": "{{cuantas}} shifts, starting with the one on {{fecha}}, will be covered by {{nuevo}}.", "es-AR": "{{cuantas}} guardias, desde la del {{fecha}}, las hace {{nuevo}}.", "pt-BR": "{{cuantas}} plantões, a partir do de {{fecha}}, serão feitos por {{nuevo}}."}, "clave": "cambio_de_asistente_cliente.cuerpo_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c3ef5c04-24ca-4f86-9b92-01d2e9caa0f4", "i18n": {"en": "{{nombre}} did not accept the recording of their location", "es-AR": "{{nombre}} no aceptó el registro de su ubicación", "pt-BR": "{{nombre}} não aceitou o registro da sua localização"}, "clave": "plazo_ubicacion_sin_aceptar.asunto", "activo": true, "created_at": "2026-10-22T06:06:30.781747+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c4404d04-b48d-472b-b9e0-d4a880b2ed8c", "i18n": {"en": "The care worker did not clock out, so there is no record that the shift ended or of who was left in charge of the patient.", "es-AR": "El Asistente no marcó su salida, así que no hay constancia de que la guardia haya terminado ni de quién quedó a cargo del Paciente.", "pt-BR": "O Assistente não registrou a saída, então não há registro de que o plantão tenha terminado nem de quem ficou a cargo do Paciente."}, "clave": "guardia_sin_cerrar_grave.salida_sin_marcar", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c4a28037-c61d-47d1-b46a-b532bd8d11c0", "i18n": {"en": "Shift continuity", "es-AR": "Continuidad de guardia", "pt-BR": "Continuidade de plantão"}, "clave": "incidente_relevo_cliente.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c584a832-d853-475a-8094-f7470e47adfb", "i18n": {"en": "Still unresolved: passed to the backup coordinator", "es-AR": "Sin resolver: pasa al Coordinador de respaldo", "pt-BR": "Sem resolver: passa ao Coordenador de retaguarda"}, "clave": "escalada_a_respaldo.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c63de285-1e71-488c-b165-4a1ec3a2a661", "i18n": {"en": "A care worker is missing and the shift starts shortly", "es-AR": "Falta un Asistente y la guardia empieza enseguida", "pt-BR": "Falta um Assistente e o plantão começa em seguida"}, "clave": "ausencia_de_golpe.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c6f5cf39-ec19-431c-8334-42ba31abea00", "i18n": {"en": "Yellow alert about a patient", "es-AR": "Alerta amarilla sobre un Paciente", "pt-BR": "Alerta amarelo sobre um Paciente"}, "clave": "alerta_ia_coordinador.asunto_amarilla", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c74b1632-1aa9-4e1e-993b-97ef290a4ec1", "i18n": {"en": "Confirm {{nombre}}'s return", "es-AR": "Confirmar la vuelta de {{nombre}}", "pt-BR": "Confirmar o retorno de {{nombre}}"}, "clave": "vuelta_de_ausencia_sin_confirmar.asunto", "activo": true, "created_at": "2026-09-30T23:36:26.907358+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "c7923eaa-6524-45c1-845a-a14a573ce10c", "i18n": {"en": "This shift goes to {{nuevo}}.", "es-AR": "Esta guardia pasa a {{nuevo}}.", "pt-BR": "Este plantão passa para {{nuevo}}."}, "clave": "cambio_de_asistente.pasa_uno", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "cb982850-3272-499b-b76f-69e2affa84f7", "i18n": {"en": "Covers this patient's days off: {{nombres}}.", "es-AR": "Cubre francos de este Paciente: {{nombres}}.", "pt-BR": "Cobre as folgas deste Paciente: {{nombres}}."}, "clave": "incidente_turno_sin_cubrir.cubren_francos", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "cd9a9de6-cd7e-409e-b1ed-1e4f7def968f", "i18n": {"en": "These shifts go to {{nuevo}}.", "es-AR": "Estas guardias pasan a {{nuevo}}.", "pt-BR": "Estes plantões passam para {{nuevo}}."}, "clave": "cambio_de_asistente.pasa_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "cdbc527d-1c8d-4d41-a813-4851774de083", "i18n": {"en": "patient with no name on file", "es-AR": "Paciente sin nombre cargado", "pt-BR": "Paciente sem nome cadastrado"}, "clave": "comun.paciente_sin_nombre", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "ce198e3d-2700-496d-89db-fef6ada68590", "i18n": {"en": "You are about to remove an authorization, please confirm.", "es-AR": "Está por remover una autorización, por favor, confirme.", "pt-BR": "Você está prestes a remover uma autorização, por favor, confirme."}, "clave": "apoderado.quitar_aviso", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "cec87e57-51c4-4bf5-b54d-9f1b2dba8a3c", "i18n": {"en": "A care worker is missing: the shift should have started already", "es-AR": "Falta un Asistente: la guardia ya tendría que haber empezado", "pt-BR": "Falta um Assistente: o plantão já deveria ter começado"}, "clave": "ausencia_de_golpe.asunto_ya_empezo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ced6b0e6-4456-4ba3-b8da-beb3f920db55", "i18n": {"en": "Reason", "es-AR": "Motivo", "pt-BR": "Motivo"}, "clave": "apoderado.motivo", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "cf49466c-6485-4235-9c01-75a549ab45a9", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, for {{pacientes}} has an alert that is still open. If you have any questions, you can contact the coordinator.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, para {{pacientes}} tiene una alerta pendiente de resolver. Ante cualquier duda, puede comunicarse con el Coordinador.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, para {{pacientes}} tem um alerta pendente de resolver. Em caso de dúvida, pode entrar em contato com o Coordenador."}, "clave": "alerta_temprana_guardia_cliente.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "cfd19955-e5aa-4e8c-b262-cf6e5f2d0d70", "i18n": {"en": "Activate it here:", "es-AR": "Se activa acá:", "pt-BR": "A ativação é feita aqui:"}, "clave": "activacion_cuenta.invitacion_al_enlace", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d07a2c1c-c69d-4796-bbda-2710e15a8468", "i18n": {"en": "{{prestadora}} opened a password change on your account", "es-AR": "{{prestadora}} habilitó un cambio de clave en su cuenta", "pt-BR": "A {{prestadora}} liberou uma troca de senha na sua conta"}, "clave": "cambio_de_clave_habilitado.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "d0a5129b-0574-41de-b677-f918bc81dc24", "i18n": {"en": "{{nombre}} reported being unable to cover the recurring shift assigned during an absence. Those shifts are uncovered again.", "es-AR": "{{nombre}} avisó que no puede cubrir el turno fijo que se le asignó durante una ausencia. Esas guardias volvieron a quedar sin cubrir.", "pt-BR": "{{nombre}} avisou que não pode cobrir o turno fixo atribuído durante uma ausência. Esses plantões voltaram a ficar sem cobertura."}, "clave": "cobertura_objetada.cuerpo", "activo": true, "created_at": "2026-09-30T23:36:26.907358+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d1b230d0-9a95-4a98-805b-f6dce357a623", "i18n": {"en": "Powered by {{producto}}", "es-AR": "Con la tecnología de {{producto}}", "pt-BR": "Com a tecnologia de {{producto}}"}, "clave": "comun.marca", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "d2122345-2c3e-40f9-92a4-26790625c469", "i18n": {"en": "On {{fecha}} the system will delete the {{anio}} record of access to health information. You can download it beforehand from Audit, in the Panel.", "es-AR": "El {{fecha}} el sistema borrará el registro de accesos a la información de salud del año {{anio}}. Puede descargarlo antes desde Auditoría, en el Panel.", "pt-BR": "Em {{fecha}} o sistema excluirá o registro de acessos às informações de saúde do ano {{anio}}. Você pode baixá-lo antes em Auditoria, no Painel."}, "clave": "borrado_del_registro_de_accesos_preaviso.texto", "activo": true, "created_at": "2026-11-10T23:51:19.634456+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "d3aee9ba-c06f-41f7-93f0-41eca9548129", "i18n": {"en": "The shift on {{fecha}} starts at {{horaInicio}}.", "es-AR": "La guardia del {{fecha}} empieza a las {{horaInicio}}.", "pt-BR": "O plantão do dia {{fecha}} começa às {{horaInicio}}."}, "clave": "recordatorio_de_guardia.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d5174168-6208-4d4f-bb09-dd3b0499662d", "i18n": {"en": "{{importe}} could not be charged. Access keeps working until {{dia}}; if the payment has not come through by then, it is suspended.", "es-AR": "No se pudo cobrar {{importe}}. El acceso sigue funcionando hasta el {{dia}}; si para entonces el cobro no entró, queda suspendido.", "pt-BR": "Não foi possível cobrar {{importe}}. O acesso continua funcionando até {{dia}}; se até lá a cobrança não entrar, fica suspenso."}, "clave": "cobro_no_realizado.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d6a929ef-0914-4e3b-99b6-584b619df8f4", "i18n": {"en": "The early warning has been unresolved for {{minutos}} minutes.", "es-AR": "La alerta temprana sigue sin resolver hace {{minutos}} minutos.", "pt-BR": "O alerta antecipado continua sem resolver há {{minutos}} minutos."}, "clave": "alerta_temprana_respaldo.demora", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d7548019-6b03-4df9-97f3-2318601797d7", "i18n": {"en": "A new password was requested for your {{empresa}} account.", "es-AR": "Se pidió una clave nueva para su cuenta en {{empresa}}.", "pt-BR": "Foi pedida uma senha nova para a sua conta na {{empresa}}."}, "clave": "recuperacion_clave.cuerpo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d7b591c8-f3ba-40f2-95ad-ec241e4cce22", "i18n": {"en": "Your application was approved. We will be in touch with you.", "es-AR": "Su postulación fue aprobada. Nos vamos a poner en contacto con usted.", "pt-BR": "A sua candidatura foi aprovada. Entraremos em contato."}, "clave": "estado_postulacion.aprobado", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "d7be4d8f-e18f-4ea8-9496-3c55481e439b", "i18n": {"en": "Shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, for {{pacientes}}.", "es-AR": "Guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, para {{pacientes}}.", "pt-BR": "Plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, para {{pacientes}}."}, "clave": "comun.linea_guardia", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "d819afa5-5411-4559-ba49-8a1e23a2ea23", "i18n": {"en": "Download", "es-AR": "Descargar", "pt-BR": "Baixar"}, "clave": "documento_para_firmar.descargar", "activo": true, "created_at": "2026-11-05T04:47:46.731061+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "da3b97e4-6fd6-49ac-9ebb-73300eb78d94", "i18n": {"en": "Shift not closed", "es-AR": "Guardia sin cerrar", "pt-BR": "Plantão sem encerrar"}, "clave": "guardia_sin_cerrar_cliente.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "dbd1c27f-acb9-4d40-9eb4-e02b3486882d", "i18n": {"en": "Emergency relief", "es-AR": "Relevo de emergencia", "pt-BR": "Rendição de emergência"}, "clave": "relevo_de_emergencia.asunto", "activo": true, "created_at": "2026-10-27T04:40:58.720695+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "dc15a998-0bd1-459c-b808-6a226e904adc", "i18n": {"en": "A care worker reported an absence", "es-AR": "Un Asistente avisó que falta", "pt-BR": "Um Assistente avisou que vai faltar"}, "clave": "ausencia_avisada_con_tiempo.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "dca2070d-5746-4dc8-a8d5-753fbff71057", "i18n": {"en": "Cover needed for a shift: {{fecha}}, from {{horaInicio}} to {{horaFin}}", "es-AR": "Se busca quién cubra una guardia: {{fecha}}, de {{horaInicio}} a {{horaFin}}", "pt-BR": "Procura-se quem cubra um plantão: {{fecha}}, das {{horaInicio}} às {{horaFin}}"}, "clave": "convocatoria_de_relevo.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "de568bcf-8ed0-4cfc-bfba-b9bea6a67293", "i18n": {"en": "no care worker assigned", "es-AR": "Asistente sin asignar", "pt-BR": "Assistente sem atribuição"}, "clave": "comun.asistente_sin_asignar", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "de7467a4-29f5-47d8-9045-67d5f07bc9c6", "i18n": {"en": "The shift on {{fecha}}, from {{horaInicio}} to {{horaFin}}, is still open {{minutos}} minute past the deadline.", "es-AR": "La guardia del {{fecha}}, de {{horaInicio}} a {{horaFin}}, sigue sin cerrarse {{minutos}} minuto después del plazo.", "pt-BR": "O plantão de {{fecha}}, das {{horaInicio}} às {{horaFin}}, continua sem fechar {{minutos}} minuto depois do prazo."}, "clave": "guardia_sin_cerrar_respaldo.texto_uno", "activo": true, "created_at": "2026-10-20T00:05:46.277827+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ded5f5fd-ce58-41be-9644-687d29f8a4b7", "i18n": {"en": "Sign", "es-AR": "Firmar", "pt-BR": "Assinar"}, "clave": "documento_para_firmar.firmar", "activo": true, "created_at": "2026-11-05T04:47:46.731061+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "df3b3820-433e-4e12-850f-8db4bccebb5b", "i18n": {"en": "You have a recurring shift assigned: {{dias}}, from {{horaInicio}} to {{horaFin}}. Accept or decline the offer.", "es-AR": "Tiene un turno fijo asignado: {{dias}}, de {{horaInicio}} a {{horaFin}}. Acepte o rechace la propuesta.", "pt-BR": "Você tem um plantão fixo atribuído: {{dias}}, das {{horaInicio}} às {{horaFin}}. Aceite ou recuse a proposta."}, "clave": "turno_fijo_para_responder.cuerpo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "df6bc5eb-1101-4fa6-8a5b-f4e40daa35bc", "i18n": {"en": "Replace", "es-AR": "Reemplazar", "pt-BR": "Substituir"}, "clave": "apoderado.reemplazar", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "df73c44c-6abd-40eb-a2ed-c089b44eafc0", "i18n": {"en": "Document approved", "es-AR": "Documento aprobado", "pt-BR": "Documento aprovado"}, "clave": "documento_aprobado.titulo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e1426eeb-9e49-40bc-aa79-2ff3c208d2a6", "i18n": {"en": "New shift assigned", "es-AR": "Nueva guardia asignada", "pt-BR": "Novo plantão atribuído"}, "clave": "guardia_asignada.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e2e0652d-e06a-4b69-9c0d-c33821f6213a", "i18n": {"en": "On {{fecha}} the system will delete the {{anio}} record of access to health information. You can download it beforehand from Audit, in the Panel.", "es-AR": "El {{fecha}} el sistema borrará el registro de accesos a la información de salud del año {{anio}}. Puede descargarlo antes desde Auditoría, en el Panel.", "pt-BR": "Em {{fecha}} o sistema excluirá o registro de acessos às informações de saúde do ano {{anio}}. Você pode baixá-lo antes em Auditoria, no Painel."}, "clave": "borrado_del_registro_de_accesos_notificacion.texto", "activo": true, "created_at": "2026-11-10T23:51:19.634456+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "e36d9cb1-35d5-4154-b830-c70158984b80", "i18n": {"en": "CUIL", "es-AR": "CUIL", "pt-BR": "CUIL"}, "clave": "apoderado.cuil", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e39c6ed2-0c7a-447a-8002-dabec21c04ef", "i18n": {"en": "View document", "es-AR": "Ver documento", "pt-BR": "Ver documento"}, "clave": "documento_para_firmar.boton", "activo": true, "created_at": "2026-11-05T04:47:46.731061+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e52090c0-0d8a-4101-8f8e-9a6bce5b8e3e", "i18n": {"en": "Coordinator {{nombre}}'s absence was expected to end on {{fecha}} and no return has been recorded. Until a return or a new expected date is recorded, the absence stays open and the covering coordinator remains in charge of the zone.", "es-AR": "La ausencia del Coordinador {{nombre}} tenía prevista la vuelta para el {{fecha}} y nadie la anotó. Mientras no se anote la vuelta o una nueva fecha prevista, la ausencia sigue abierta y quien lo cubre sigue a cargo de su zona.", "pt-BR": "A ausência do Coordenador {{nombre}} tinha retorno previsto para {{fecha}} e ninguém o registrou. Enquanto não se registrar o retorno ou uma nova data prevista, a ausência continua aberta e quem o cobre segue responsável pela zona."}, "clave": "vuelta_de_coordinador_sin_confirmar.cuerpo", "activo": true, "created_at": "2026-09-30T23:36:26.907358+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e52fb180-f84f-479d-a4a2-540855c3aff8", "i18n": {"en": "The link expires in {{horas}} hours and works only once. If you did not request it, you can ignore this email: your password stays as it was.", "es-AR": "El enlace vence en {{horas}} horas y sirve una sola vez. Si no lo pidió, puede ignorar este correo: su clave sigue siendo la de siempre.", "pt-BR": "O link expira em {{horas}} horas e serve uma só vez. Se não tiver sido solicitada, pode ignorar este e-mail: a sua senha continua a mesma."}, "clave": "recuperacion_clave.pie_de_aviso", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e532b511-26a2-4d65-954c-c6562fbab51e", "i18n": {"en": "Monday", "es-AR": "lunes", "pt-BR": "segunda-feira"}, "clave": "comun.dia_lunes", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e65cd0dc-93a7-45ea-ab96-67c9916261ba", "i18n": {"en": "Your interview with {{prestadora}} has moved", "es-AR": "Se cambió el día de su entrevista con {{prestadora}}", "pt-BR": "Mudou o dia da sua entrevista com {{prestadora}}"}, "clave": "entrevista_reprogramada.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e662e05e-ff2e-4e28-b1cd-0b9003c8f1d8", "i18n": {"en": "Sunday", "es-AR": "domingo", "pt-BR": "domingo"}, "clave": "comun.dia_domingo", "activo": true, "created_at": "2026-10-16T17:26:23.1134+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "e7537188-dfe9-4679-91cc-96f60f37f21f", "i18n": {"en": "Red alert about a patient", "es-AR": "Alerta roja sobre un Paciente", "pt-BR": "Alerta vermelho sobre um Paciente"}, "clave": "alerta_ia_coordinador.asunto_roja", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ea395820-7ca5-4d76-ad36-48a317ed9943", "i18n": {"en": "View", "es-AR": "Ver", "pt-BR": "Ver"}, "clave": "apoderado.ver", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ea70fd58-8c82-4b55-96d8-a354cc8a64b5", "i18n": {"en": "{{documento}} expired on {{fecha}}. Please upload the renewal.", "es-AR": "{{documento}} venció el {{fecha}}. Suba la renovación.", "pt-BR": "{{documento}} venceu em {{fecha}}. Envie a renovação."}, "clave": "documento_vencido.cuerpo", "activo": true, "created_at": "2026-10-26T16:17:14.735958+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ea7e464e-80d8-4828-b46e-c3456623e710", "i18n": {"en": "Patient's team: {{nombres}}.", "es-AR": "Equipo del Paciente: {{nombres}}.", "pt-BR": "Equipe do Paciente: {{nombres}}."}, "clave": "incidente_turno_sin_cubrir.equipo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "eb9e56cc-516c-4489-a0d3-896146311168", "i18n": {"en": "{{anterior}} no longer covers these shifts. {{nuevo}} covers them now.", "es-AR": "{{anterior}} ya no hace estas guardias. Ahora las hace {{nuevo}}.", "pt-BR": "{{anterior}} não faz mais estes plantões. Agora são feitos por {{nuevo}}."}, "clave": "cambio_de_asistente.cambio_varios", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ede03d80-c132-4be7-b5b7-8083b717f519", "i18n": {"en": "{{empresa}} — Your application", "es-AR": "{{empresa}} — Su postulación", "pt-BR": "{{empresa}} — A sua candidatura"}, "clave": "estado_postulacion.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "efbbcb5e-daa8-443a-8db2-ae2d93a8ff58", "i18n": {"en": "Send email", "es-AR": "Enviar email", "pt-BR": "Enviar e-mail"}, "clave": "documento_para_firmar.enviar", "activo": true, "created_at": "2026-11-05T04:47:46.731061+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f0486cb6-5616-48ad-8289-bb5798b0a0f8", "i18n": {"en": "{{nuevo}} replaces {{anterior}} on {{cuantas}} shifts starting {{fecha}}.", "es-AR": "{{nuevo}} reemplaza a {{anterior}} en {{cuantas}} guardias a partir del {{fecha}}.", "pt-BR": "{{nuevo}} substitui {{anterior}} em {{cuantas}} plantões a partir do dia {{fecha}}."}, "clave": "cambio_de_asistente_cliente.reemplaza_varios", "activo": true, "created_at": "2026-10-16T05:03:19.135198+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f1b48d16-bc99-4323-88cf-acb3a05ce914", "i18n": {"en": "The period of {{dias}} days expired and {{nombre}} did not accept the recording of their location during the shift.", "es-AR": "Venció el plazo de {{dias}} días y {{nombre}} no aceptó el registro de su ubicación durante el turno de guardia.", "pt-BR": "Venceu o prazo de {{dias}} dias e {{nombre}} não aceitou o registro da sua localização durante o turno de plantão."}, "clave": "plazo_ubicacion_sin_aceptar.texto", "activo": true, "created_at": "2026-10-22T06:06:30.781747+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f21f1920-690f-4b46-b084-71f838e1370f", "i18n": {"en": "A care worker", "es-AR": "Un Asistente", "pt-BR": "Um Assistente"}, "clave": "comun.un_asistente", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": false}, {"id": "f2a539e7-ae17-4ca4-b5c9-8cd5e29415a5", "i18n": {"en": "Alert about the patient", "es-AR": "Alerta sobre el Paciente", "pt-BR": "Alerta sobre o Paciente"}, "clave": "alerta_ia_cliente.titulo_roja", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f5e4e3e0-2cb5-49b6-88da-cc7a066d203f", "i18n": {"en": "Power of attorney", "es-AR": "Poder", "pt-BR": "Procuração"}, "clave": "apoderado.poder", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f643c083-4dd9-4706-8281-2b359363b390", "i18n": {"en": "Shift not covered", "es-AR": "Guardia sin cubrir", "pt-BR": "Plantão sem cobertura"}, "clave": "guardia_sin_cubrir.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f697cbbb-1c25-4c5c-94a1-0514ace2c953", "i18n": {"en": "Thank you for your interest in {{empresa}}. We will not be moving forward with your application at this time.", "es-AR": "Gracias por su interés en {{empresa}}. En esta oportunidad no vamos a avanzar con su postulación.", "pt-BR": "Obrigado pelo interesse na {{empresa}}. Desta vez não vamos avançar com a candidatura."}, "clave": "estado_postulacion.rechazado", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "f9c1d2be-a74e-4ddd-ac4f-bed6f3146d2d", "i18n": {"en": "The free period is ending", "es-AR": "Termina el período sin cargo", "pt-BR": "Termina o período sem cobrança"}, "clave": "fin_periodo_sin_cargo.titulo", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "fbf05dbe-d80d-40a0-8648-54b2c8012556", "i18n": {"en": "These care workers have their {{etiqueta}} expired or expiring within {{dias}} days:", "es-AR": "Estos Asistentes tienen {{etiqueta}} vencido o por vencer dentro de {{dias}} días:", "pt-BR": "Estes Assistentes têm {{etiqueta}} vencido ou a vencer dentro de {{dias}} dias:"}, "clave": "vencimiento_documentos.encabezado", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "fd1a0a26-47d3-47f5-b326-023de0f15026", "i18n": {"en": "Unresolved for {{minutos}} minutes: passed to every coordinator", "es-AR": "Sin resolver hace {{minutos}} minutos: pasa a todos los Coordinadores", "pt-BR": "Sem resolver há {{minutos}} minutos: passa a todos os Coordenadores"}, "clave": "escalada_a_todos_los_coordinadores.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "fe844b5b-8cfd-4066-ba4b-5a50411fabf3", "i18n": {"en": "Authorised signatory", "es-AR": "Apoderado", "pt-BR": "Procurador"}, "clave": "apoderado.titulo", "activo": true, "created_at": "2026-11-04T15:40:56.798767+00:00", "prestadora_id": null, "admite_texto_propio": true}, {"id": "ff3a3e28-9841-4f67-a27d-2b84b7c36f56", "i18n": {"en": "Care worker reported a delay", "es-AR": "Aviso de demora del Asistente", "pt-BR": "Aviso de atraso do Assistente"}, "clave": "aviso_demora_asistente.asunto", "activo": true, "created_at": "2026-09-19T18:55:45.335187+00:00", "prestadora_id": null, "admite_texto_propio": true}]$datos$::jsonb);  -- 238 filas

