INSERT INTO "public"."textos_consentimiento" (id, jurisdiccion, clave, modalidad, version, idioma, titulo, cuerpo, puntos_clave, es_borrador, vigente_desde, vigente_hasta, created_at, updated_at, control_de_ubicacion_en_el_turno)
SELECT id, jurisdiccion, clave, modalidad, version, idioma, titulo, cuerpo, puntos_clave, es_borrador, vigente_desde, vigente_hasta, created_at, updated_at, control_de_ubicacion_en_el_turno FROM jsonb_populate_recordset(NULL::"public"."textos_consentimiento", $datos$[{"id": "0aa2d1a2-6a40-4ba4-86c2-b6937168ee4f", "clave": "consentimiento_medicacion", "cuerpo": "I declare under oath that the data of the medical prescription —including the treatment, the medication, the dosage, the frequency, the route of administration and the validity of the indicated period— faithfully and exactly match what was ordered by the treating physician.\n\nAccordingly, I assume full and exclusive responsibility for the correct entry of this information into the system.\n\nThe entity {{prestadora}} and the staff involved in administering the medication will act on the basis of the information recorded in the system, which has the nature of a sworn statement, and are released from all liability arising from errors, omissions or inaccuracies in the entry made by the declarant.", "idioma": "en", "titulo": "Medication entered by the Client", "version": 1, "modalidad": null, "created_at": "2026-11-03T20:15:02.282494+00:00", "updated_at": "2026-11-03T20:15:02.282494+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T20:15:02.282494+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "0bd813a2-6b9f-402d-a825-0bbd32525e17", "clave": "autorizacion_signos_vitales", "cuerpo": "Por medio de la presente, en mi carácter de contratante del servicio, autorizo a {{prestadora}} y al personal asistente que asigne a {{paciente}}, tanto para el momento actual como para futuras asistencias, a realizar el control y registro de su presión arterial, temperatura corporal y saturación de oxígeno.\n\nLa presente autorización se limita exclusivamente a prácticas no invasivas y no comprende procedimientos que requieran punción (tales como la medición de glucemia), salvo que el asistente designado cuente expresamente con la matrícula profesional habilitante para tal fin.", "idioma": "es-AR", "titulo": "Autorización control de signos vitales", "version": 1, "modalidad": null, "created_at": "2026-11-03T05:08:21.521829+00:00", "updated_at": "2026-11-03T05:08:21.521829+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T05:08:21.521829+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "17858d26-f4dc-41e0-ab05-caf7644096e8", "clave": "seguimiento_ubicacion", "cuerpo": "THIS IS PLACEHOLDER TEXT AND HAS NO LEGAL VALIDITY. It exists so the screen can be built and tested while the professional wording is obtained.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit.", "idioma": "en", "titulo": "DRAFT TEXT — Recording your location on your way to a shift", "version": 1, "modalidad": "dependencia", "created_at": "2026-07-31T21:33:19.215973+00:00", "updated_at": "2026-07-31T21:33:19.215973+00:00", "es_borrador": true, "jurisdiccion": "AR", "puntos_clave": ["DRAFT — Placeholder point, pending legal wording."], "vigente_desde": "2026-07-31T21:33:19.215973+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "205ffd51-14bd-417d-a53e-141672fefb7d", "clave": "seguimiento_ubicacion", "cuerpo": "We record your location during the trip to the home and during your shift.", "idioma": "en", "titulo": "Location", "version": 2, "modalidad": "autonomo", "created_at": "2026-10-22T06:06:30.368879+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-10-22T06:06:30.368879+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": true}, {"id": "20a1bd84-cf17-4432-9424-ca44330db7e0", "clave": "seguimiento_ubicacion", "cuerpo": "Registramos su ubicación durante el viaje al domicilio y durante su turno de guardia.", "idioma": "es-AR", "titulo": "Ubicación", "version": 2, "modalidad": "autonomo", "created_at": "2026-10-22T06:06:30.368879+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-10-22T06:06:30.368879+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": true}, {"id": "27e41201-5ccc-435a-8ae0-20c3c50b2d62", "clave": "seguimiento_ubicacion", "cuerpo": "Registramos sua localização durante o trajeto até o domicílio e durante seu turno de plantão.", "idioma": "pt-BR", "titulo": "Localização", "version": 2, "modalidad": "autonomo", "created_at": "2026-10-22T06:06:30.368879+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-10-22T06:06:30.368879+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": true}, {"id": "4ada5511-886f-47a0-8e03-c3808d4207d3", "clave": "autorizacion_signos_vitales", "cuerpo": "By means of this document, in my capacity as the contracting party of the service, I authorize {{prestadora}} and the assistant staff it assigns to {{paciente}}, both at present and for future assistance, to monitor and record their blood pressure, body temperature and oxygen saturation.\n\nThis authorization is limited exclusively to non-invasive practices and does not include procedures that require a puncture (such as blood glucose measurement), unless the designated assistant expressly holds the professional license required for that purpose.", "idioma": "en", "titulo": "Vital signs monitoring authorization", "version": 1, "modalidad": null, "created_at": "2026-11-03T05:08:21.521829+00:00", "updated_at": "2026-11-03T05:08:21.521829+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T05:08:21.521829+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "5157b276-a17e-4db3-aef1-7f3ca4ad091a", "clave": "consentimiento_pagador", "cuerpo": "CONSENTIMIENTO A LA OBLIGACIÓN DE PAGAR\n\nPrestadora: {{prestadora}}\nQuien se obliga: {{pagador}}\nDocumento: {{documento}}\nFirma en su representación: {{apoderado}}\nServicio contratado para: {{cliente}}\nFecha: {{fecha}}\n\n------------------------------------------------------------------------\n\nQuien firma declara que conoce el servicio contratado y asume la obligación de pagarlo\na {{prestadora}}, en las condiciones y con la periodicidad que se hayan acordado.\n\nEsta obligación es propia y no depende de que un tercero —una obra social, una prepaga u\notra entidad— reconozca, autorice o pague la prestación.\n\nQuien firma puede dejar de estar obligado para adelante avisándolo por escrito a la\nPrestadora. Lo que ya se prestó hasta ese aviso queda alcanzado por esta obligación.\n\nLos datos personales que se dejan acá se usan para facturar y cobrar el servicio, y para\nnada más.\n\n------------------------------------------------------------------------\n\nFirma: ................................................................\n\nAclaración: ...........................................................\n", "idioma": "es-AR", "titulo": "Consentimiento a la obligación de pagar", "version": 1, "modalidad": null, "created_at": "2026-11-03T20:15:02.282494+00:00", "updated_at": "2026-11-08T19:27:12.397247+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T20:15:02.282494+00:00", "vigente_hasta": "2026-11-08T19:27:12.397247+00:00", "control_de_ubicacion_en_el_turno": null}, {"id": "58c28268-4a11-4860-b598-62c6d62824f5", "clave": "seguimiento_ubicacion", "cuerpo": "We record your location during the trip to the home and when you check in and check out.", "idioma": "en", "titulo": "Location", "version": 2, "modalidad": "autonomo", "created_at": "2026-10-22T06:06:30.368879+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-10-22T06:06:30.368879+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": false}, {"id": "5a116fa3-c7bd-4580-a818-548ee9ffbc41", "clave": "consentimiento_medicacion", "cuerpo": "Declaro bajo juramento que los datos correspondientes a la prescripción médica —incluyendo el tratamiento, la medicación, la dosificación, la frecuencia, la vía de administración y la vigencia del período indicado— concuerdan fiel y exactamente con lo dispuesto por el profesional médico tratante.\n\nEn virtud de ello, asumo plena y exclusiva responsabilidad por la correcta carga e ingreso de dicha información en el sistema.\n\nLa entidad {{prestadora}} y el personal interviniente en la administración de la medicación actuarán sobre la base de la información registrada en el sistema, la cual reviste carácter de declaración jurada, quedando liberados de toda responsabilidad derivada de errores, omisiones o inexactitudes en la carga efectuada por el declarante.", "idioma": "es-AR", "titulo": "Medicación que carga el Cliente", "version": 1, "modalidad": null, "created_at": "2026-11-03T20:15:02.282494+00:00", "updated_at": "2026-11-03T20:15:02.282494+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T20:15:02.282494+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "711f5cf6-72fc-4e4d-be35-e46f62c03b42", "clave": "seguimiento_ubicacion", "cuerpo": "ESTE TEXTO ES DE RELLENO Y NO TIENE VALIDEZ LEGAL. Está acá para poder construir y probar la pantalla mientras se consigue la redacción profesional.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit. Esta sección va a explicar, en palabras simples, qué se registra del recorrido hacia una guardia y para qué se usa ese dato.\n\nSed do eiusmod tempor incididunt ut labore. Acá va a ir la finalidad concreta: saber con tiempo si una guardia se va a poder cubrir, y nada más que eso.\n\nUt enim ad minim veniam, quis nostrud exercitation. Acá va a ir qué NO se hace con el dato: no se comparte con el Cliente, no se usa fuera del horario del trayecto, no se guarda para siempre.\n\nDuis aute irure dolor in reprehenderit in voluptate velit esse. Acá va a ir cómo se retira este consentimiento y qué pasa cuando se retira.", "idioma": "es-AR", "titulo": "TEXTO PROVISORIO — Registro de la ubicación en el trayecto hacia una guardia", "version": 1, "modalidad": "dependencia", "created_at": "2026-07-31T21:33:19.215973+00:00", "updated_at": "2026-10-11T03:33:52.458709+00:00", "es_borrador": true, "jurisdiccion": "AR", "puntos_clave": ["PROVISORIO — Qué se registra: solo el recorrido hacia la guardia.", "PROVISORIO — Cuándo empieza: al avisar la salida. Cuándo termina: al llegar.", "PROVISORIO — Quién lo ve: la Prestadora. El Cliente ve solo la hora estimada de llegada, nunca el lugar exacto.", "PROVISORIO — Cuánto se guarda: [pendiente de definir con el abogado].", "PROVISORIO — Se puede retirar en cualquier momento, desde Perfil."], "vigente_desde": "2026-07-31T21:33:19.215973+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "7170949d-c309-491a-b595-c7bc89d80397", "clave": "seguimiento_ubicacion", "cuerpo": "ESTE TEXTO É DE PREENCHIMENTO E NÃO TEM VALIDADE LEGAL. Está aqui para permitir construir e testar a tela enquanto se obtém a redação profissional.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit.", "idioma": "pt-BR", "titulo": "TEXTO PROVISÓRIO — Registro da sua localização a caminho do plantão", "version": 1, "modalidad": "dependencia", "created_at": "2026-07-31T21:33:19.215973+00:00", "updated_at": "2026-07-31T21:33:19.215973+00:00", "es_borrador": true, "jurisdiccion": "AR", "puntos_clave": ["PROVISÓRIO — Ponto de preenchimento, aguardando redação legal."], "vigente_desde": "2026-07-31T21:33:19.215973+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "79004ec7-a13b-445d-b6e1-36c79fe01acd", "clave": "seguimiento_ubicacion", "cuerpo": "THIS IS PLACEHOLDER TEXT AND HAS NO LEGAL VALIDITY.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit.", "idioma": "en", "titulo": "DRAFT TEXT — Recording your location on your way to a shift", "version": 1, "modalidad": "autonomo", "created_at": "2026-07-31T21:33:19.215973+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": true, "jurisdiccion": "AR", "puntos_clave": ["DRAFT — Placeholder point, pending legal wording."], "vigente_desde": "2026-07-31T21:33:19.215973+00:00", "vigente_hasta": "2026-10-22T06:06:30.368879+00:00", "control_de_ubicacion_en_el_turno": null}, {"id": "836f5f76-f9ff-4ba0-8b95-51937fdc4c2b", "clave": "seguimiento_ubicacion", "cuerpo": "Registramos su ubicación durante el viaje al domicilio y al registrar la entrada y la salida.", "idioma": "es-AR", "titulo": "Ubicación", "version": 2, "modalidad": "autonomo", "created_at": "2026-10-22T06:06:30.368879+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-10-22T06:06:30.368879+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": false}, {"id": "9dcb3c3b-eafe-4aea-addd-c9ca575c025a", "clave": "consentimiento_medicacion", "cuerpo": "Declaro sob juramento que os dados correspondentes à prescrição médica —incluindo o tratamento, a medicação, a dosagem, a frequência, a via de administração e a vigência do período indicado— correspondem fiel e exatamente ao disposto pelo profissional médico responsável.\n\nEm virtude disso, assumo plena e exclusiva responsabilidade pelo correto cadastro e inserção dessas informações no sistema.\n\nA entidade {{prestadora}} e o pessoal envolvido na administração da medicação atuarão com base nas informações registradas no sistema, as quais têm caráter de declaração juramentada, ficando isentos de toda responsabilidade decorrente de erros, omissões ou inexatidões no cadastro efetuado pelo declarante.", "idioma": "pt-BR", "titulo": "Medicação cadastrada pelo Cliente", "version": 1, "modalidad": null, "created_at": "2026-11-03T20:15:02.282494+00:00", "updated_at": "2026-11-03T20:15:02.282494+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T20:15:02.282494+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "ae09a075-7882-428f-803d-31fd74ef6696", "clave": "seguimiento_ubicacion", "cuerpo": "ESTE TEXTO É DE PREENCHIMENTO E NÃO TEM VALIDADE LEGAL.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit.", "idioma": "pt-BR", "titulo": "TEXTO PROVISÓRIO — Registro da sua localização a caminho do plantão", "version": 1, "modalidad": "autonomo", "created_at": "2026-07-31T21:33:19.215973+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": true, "jurisdiccion": "AR", "puntos_clave": ["PROVISÓRIO — Ponto de preenchimento, aguardando redação legal."], "vigente_desde": "2026-07-31T21:33:19.215973+00:00", "vigente_hasta": "2026-10-22T06:06:30.368879+00:00", "control_de_ubicacion_en_el_turno": null}, {"id": "c9dd5451-c8c9-4288-a949-81d35baafede", "clave": "seguimiento_ubicacion", "cuerpo": "ESTE TEXTO ES DE RELLENO Y NO TIENE VALIDEZ LEGAL. Está acá para poder construir y probar la pantalla mientras se consigue la redacción profesional.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit. Esta versión es la de quien trabaja de forma autónoma y acepta guardias por su cuenta.\n\nSed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Acá va a ir la diferencia con la versión de relación de dependencia: este seguimiento se acepta como parte de un servicio que se ofrece, no como condición de un empleo.", "idioma": "es-AR", "titulo": "TEXTO PROVISORIO — Registro de la ubicación en el trayecto hacia una guardia", "version": 1, "modalidad": "autonomo", "created_at": "2026-07-31T21:33:19.215973+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": true, "jurisdiccion": "AR", "puntos_clave": ["PROVISORIO — Qué se registra: solo el recorrido hacia la guardia aceptada.", "PROVISORIO — Quién lo ve: la Prestadora que publicó la guardia.", "PROVISORIO — Cuánto se guarda: [pendiente de definir con el abogado].", "PROVISORIO — Se puede retirar en cualquier momento, desde Perfil."], "vigente_desde": "2026-07-31T21:33:19.215973+00:00", "vigente_hasta": "2026-10-22T06:06:30.368879+00:00", "control_de_ubicacion_en_el_turno": null}, {"id": "ca186853-abd6-448a-9b68-5931d5dae29b", "clave": "autorizacion_signos_vitales", "cuerpo": "Por meio da presente, na qualidade de contratante do serviço, autorizo {{prestadora}} e o pessoal assistente que designar para {{paciente}}, tanto no momento atual quanto em futuros atendimentos, a realizar o controle e o registro de sua pressão arterial, temperatura corporal e saturação de oxigênio.\n\nA presente autorização limita-se exclusivamente a práticas não invasivas e não abrange procedimentos que exijam punção (tais como a medição de glicemia), salvo se o assistente designado possuir expressamente o registro profissional habilitante para tal fim.", "idioma": "pt-BR", "titulo": "Autorização de controle de sinais vitais", "version": 1, "modalidad": null, "created_at": "2026-11-03T05:08:21.521829+00:00", "updated_at": "2026-11-03T05:08:21.521829+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-03T05:08:21.521829+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "e230bd7a-7d0d-4ca4-843c-33c93f387c7f", "clave": "consentimiento_pagador", "cuerpo": "CONSENTIMIENTO A LA OBLIGACIÓN DE PAGAR\n\nPrestadora: {{prestadora}}\nQuien se obliga: {{pagador}}\nDocumento: {{documento}}\nFirma en su representación: {{apoderado}}\nServicio contratado para: {{cliente}}\nFecha: {{fecha}}\n\n------------------------------------------------------------------------\n\nQuien firma declara que conoce el servicio contratado y asume la obligación de pagarlo\na {{prestadora}}, en las condiciones y con la periodicidad que se hayan acordado.\n\nEsta obligación es propia y no depende de que un tercero —una obra social, una prepaga u\notra entidad— reconozca, autorice o pague la prestación.\n\nQuien firma puede dejar de estar obligado para adelante avisándolo por escrito a la\nPrestadora. Lo que ya se prestó hasta ese aviso queda alcanzado por esta obligación.\n\nLos datos personales que se dejan acá se usan para facturar y cobrar el servicio, y para\nnada más.\n", "idioma": "es-AR", "titulo": "Consentimiento a la obligación de pagar", "version": 2, "modalidad": null, "created_at": "2026-11-08T19:27:12.397247+00:00", "updated_at": "2026-11-08T19:27:12.397247+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-11-08T19:27:12.397247+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": null}, {"id": "eb981775-0456-415f-9777-6fe3f4b6e7df", "clave": "seguimiento_ubicacion", "cuerpo": "Registramos sua localização durante o trajeto até o domicílio e ao registrar a entrada e a saída.", "idioma": "pt-BR", "titulo": "Localização", "version": 2, "modalidad": "autonomo", "created_at": "2026-10-22T06:06:30.368879+00:00", "updated_at": "2026-10-22T06:06:30.368879+00:00", "es_borrador": false, "jurisdiccion": "AR", "puntos_clave": [], "vigente_desde": "2026-10-22T06:06:30.368879+00:00", "vigente_hasta": null, "control_de_ubicacion_en_el_turno": false}]$datos$::jsonb);  -- 20 filas

